  const SIDE_DEFAULT_CHARS = 20, SIDE_MIN_CHARS = 8, SIDE_MAX_CHARS = 60, SIDE_GAP_CHARS = 2;
  const SIDE_MAX_BOXES = 40, SIDE_MAX_LINES = 200, SIDE_MAX_TEXT = 2000, SIDE_MAX_NAME = 200;
  // One empty row between boxes on a side, always (ruling Q3); a stored `row` is a whole sheet row,
  // capped well past MAX_WEEKS' 600 so a typo'd file cannot ask for a page millions of rows tall.
  const SIDE_GAP_ROWS = 1, SIDE_MAX_ROW = 1000;
  // On screen, the least room between two boxes when the zoom has squeezed their rows together.
  // 18: room for a box's "Hide from Exports" tab, which hangs 18 px under it. At 100% the empty row
  // leaves ~18.8 px, so nothing moves there.
  const SIDE_SCREEN_GAP_PX = 18;
  const SIDE_TITLE_DEFAULT = { key: 'Color Key', text: 'Notes' };
  // What an unformatted title looks like, and an unformatted line. A title is a line with these
  // defaults under its own format (plan §3.2).
  const SIDE_TITLE_FMT = { bold: true, align: 'center' };
  const SIDE_LINE_FMT = { align: 'left' };
  // The grid header's fill in both writers (exportExcel HEADER_FILL, buildWaterfallPdf HEADER_FILL_PDF).
  const SIDE_TITLE_FILL = '#D9D9D9';
  // The PDF frame and header rule, the values buildWaterfallPdf draws the grid's with (FRAME, HDR_RULE).
  const SIDE_PDF_FRAME = '#1E1D1B', SIDE_PDF_RULE = '#1E1D1B';
  // A single line needs its glyph box (ascent + descent is 1.22 em in Carlito/Calibri) plus a little
  // air; every further line costs SHEET_LINE_RATIO. At 11 pt that is 13.2 pt, one 15 pt row; a 13 pt line
  // or a wrapped one takes two rows rather than being squeezed (plan §5.2).
  const SIDE_GLYPH_RATIO = 1.2;
  const SIDE_KEY_SHRINK_FLOOR = 0.5;

  function sideText(v, max){ return stripXmlIllegal(String(v), ' ').replace(/[\r\n]+/g, ' ').slice(0, max); }
  function sideHex(v){ const h = (typeof v === 'string') ? v.toUpperCase() : ''; return /^#[0-9A-F]{6}$/.test(h) ? h : null; }
  function sideNewBox(side, kind){
    const b = { side, kind, title: SIDE_TITLE_DEFAULT[kind] };
    if(kind === 'key'){ b.names = {}; b.hidden = []; }
    else b.lines = [{ t: '' }];
    return b;
  }

  // Held to the shape the app writes (audit H-1), from sanitizeSnapshot(). Returns undefined when the
  // value is unusable; an unknown `kind` (a future build's box) is dropped and counted, never guessed at.
  function cleanSideBoxes(v, bad){
    if(!isPlainObj(v)){ bad.n++; return undefined; }
    const out = { boxes: [], widths: {} };
    let boxes = v.boxes;
    if(!Array.isArray(boxes)){ if(boxes !== undefined) bad.n++; boxes = []; }
    if(boxes.length > SIDE_MAX_BOXES) bad.n++;
    boxes.slice(0, SIDE_MAX_BOXES).forEach(b=>{
      if(!isPlainObj(b) || !SIDE_SIDES.includes(b.side) || !SIDE_KINDS.includes(b.kind)){ bad.n++; return; }
      const o = { side: b.side, kind: b.kind,
                  title: (typeof b.title === 'string') ? sideText(b.title, SIDE_MAX_NAME) : SIDE_TITLE_DEFAULT[b.kind] };
      if(b.title !== undefined && typeof b.title !== 'string') bad.n++;
      // A bad row is dropped and counted; the box then stacks under the one before it, as it would have
      // before rows existed.
      if(b.row !== undefined){
        if(Number.isInteger(b.row) && b.row >= 0 && b.row <= SIDE_MAX_ROW) o.row = b.row; else bad.n++;
      }
      if(b.titleFmt !== undefined){ const f = cleanHeaderFormatEntry(b.titleFmt, bad); if(f) o.titleFmt = f; }
      if(b.kind === 'key'){
        o.names = {};
        if(b.names !== undefined){
          if(isPlainObj(b.names)) Object.keys(b.names).forEach(k=>{
            const h = sideHex(k);
            if(h && typeof b.names[k] === 'string') o.names[h] = sideText(b.names[k], SIDE_MAX_NAME); else bad.n++;
          });
          else bad.n++;
        }
        o.hidden = [];
        if(b.hidden !== undefined){
          if(Array.isArray(b.hidden)) b.hidden.forEach(x=>{
            const h = sideHex(x);
            if(!h){ bad.n++; return; }
            if(!o.hidden.includes(h)) o.hidden.push(h);
          });
          else bad.n++;
        }
      } else {
        o.lines = [];
        let ls = b.lines;
        if(!Array.isArray(ls)){ if(ls !== undefined) bad.n++; ls = []; }
        if(ls.length > SIDE_MAX_LINES) bad.n++;
        ls.slice(0, SIDE_MAX_LINES).forEach(l=>{
          if(!isPlainObj(l) || (l.t !== undefined && typeof l.t !== 'string')){ bad.n++; return; }
          const ln = { t: sideText(l.t || '', SIDE_MAX_TEXT) };
          if(l.f !== undefined){ const f = cleanHeaderFormatEntry(l.f, bad); if(f) ln.f = f; }
          o.lines.push(ln);
        });
        if(!o.lines.length) o.lines.push({ t: '' });   // a text box always has a line to type in
      }
      // Last, where a live toggle appends it. Only `true` is kept; `false` is the absent key's meaning.
      if(b.noExport === true) o.noExport = true;
      else if(b.noExport !== undefined && b.noExport !== false) bad.n++;
      out.boxes.push(o);
    });
    if(v.widths !== undefined){
      if(isPlainObj(v.widths)) SIDE_SIDES.forEach(s=>{
        if(!(s in v.widths)) return;
        const n = finiteNum(v.widths[s]);
        if(n !== null && n >= SIDE_MIN_CHARS && n <= SIDE_MAX_CHARS) out.widths[s] = n; else bad.n++;
      });
      else bad.n++;
    }
    return out;
  }

  // The store as captureSnapshot() writes it: each box's keys in ONE order, the order cleanSideBoxes()
  // gives a restored box. ⛔ The undo stack compares snapshots as TEXT. A box whose keys arrived in
  // another order -- a `row` given by a move, a title formatted after the box was made -- read as a
  // change right after an undo had restored it in the sanitizer's order, so the next debounced push
  // banked that "change" and wiped the redo (found 21 Oct 2026 by the sideboxes leg's F8).
  function sideBoxesSnapshot(){
    return sideBoxes.map(b=>{
      const o = { side: b.side, kind: b.kind, title: b.title };
      if(b.row !== undefined) o.row = b.row;
      if(b.titleFmt !== undefined) o.titleFmt = b.titleFmt;
      if(b.kind === 'key'){ o.names = b.names; o.hidden = b.hidden; }
      else o.lines = b.lines;
      // Last, as cleanSideBoxes() writes it, and only as true (Hide from Exports). ⚠️ A NEW per-box key
      // must be added here too, or every save and undo step silently drops it.
      if(b.noExport === true) o.noExport = true;
      return o;
    });
  }

  function sideWidthChars(side){
    const w = sideWidths[side];
    return clampChars((w !== undefined) ? w : SIDE_DEFAULT_CHARS, SIDE_MIN_CHARS, SIDE_MAX_CHARS);
  }

  // The colour key's entries, read from the COMPUTED schedule -- the cells all three outputs draw -- so
  // it cannot list a phase the waterfall does not show or miss one it does (plan §3.1). Rulings Q1/Q2:
  // the order phases first appear down the waterfall; phases sharing a colour share a row, their names
  // joined " / "; Simultaneous Post's yellow when it shows; the hiatus red last, when a hiatus shows.
  function sideKeyEntries(schedule){
    const weeks = (schedule && schedule.weeks) || [];
    const labelOf = {};
    getAllPhaseDefs().forEach(d=>{ labelOf[d.key] = d.label; });
    const order = [], byHex = new Map();
    let hiatus = false;
    const add = (hex, name)=>{
      const h = sideHex(hex) || '#FFFFFF';
      let e = byHex.get(h);
      if(!e){ e = { hex: h, names: [] }; byHex.set(h, e); order.push(e); }
      if(name && !e.names.includes(name)) e.names.push(name);
    };
    weeks.forEach(w=>{
      const cells = w.cells || [];
      if(cells.length && cells[0].type === 'hiatus'){ hiatus = true; return; }
      cells.forEach(c=>{
        if(c.type === 'phase') add(c.color, labelOf[c.key] || 'Phase');
        else if(c.type === 'phaseHiatus') hiatus = true;
      });
      if(w.simPost) add(SIMPOST_COLOR, 'Simultaneous Post');
    });
    if(hiatus) add(HIATUS_COLOR, 'Hiatus');
    // The hiatus row goes LAST even when a phase shares the red: moved, not duplicated.
    const hi = sideHex(HIATUS_COLOR), at = order.findIndex(e => e.hex === hi);
    if(at >= 0 && at !== order.length - 1) order.push(order.splice(at, 1)[0]);
    return order.map(e => ({ hex: e.hex, name: e.names.join(' / ') }));
  }
  // The rows ONE key box shows: its hidden colours left out, its edited names applied.
  function sideKeyRows(b, entries){
    const hidden = b.hidden || [], names = b.names || {};
    return entries.filter(e => !hidden.includes(e.hex))
                  .map(e => ({ hex: e.hex, name: (names[e.hex] !== undefined) ? names[e.hex] : e.name, auto: e.name }));
  }

  // Greedy wrap at the box's width, with the grid's own measure (11 pt basis, scaled to the size). The
  // same rule buildWaterfallPdf's wrapLines() uses for notes, decision for decision.
  function sideWrap(text, chars, sizePt, bold){
    const availPx = Math.max(1, chars * EXCEL_MDW) * (11 / sizePt);
    const spaceW = measureTextPx(' ', bold);
    const words = String(text).split(/\s+/).filter(Boolean);
    if(!words.length) return [''];
    const out = [];
    let line = '', lineW = 0;
    words.forEach(w=>{
      const ww = measureTextPx(w, bold);
      const cand = lineW ? lineW + spaceW + ww : ww;
      if(cand <= availPx || lineW === 0){ line = lineW ? line + ' ' + w : w; lineW = cand; }
      else { out.push(line); line = w; lineW = ww; }
    });
    out.push(line);
    return out;
  }
  // A key name stays on one row and shrinks to fit it, as a phase label does.
  function sideKeyScale(name, chars){
    const w = measureTextPx(String(name || ''), true), avail = Math.max(1, chars * EXCEL_MDW);
    if(!name || w <= avail) return 1;
    return Math.max(SIDE_KEY_SHRINK_FLOOR, Math.floor(avail / w * 50) / 50);
  }
  // A sheet row's height in points: row 0 is the header row (the workbook's row 1), row i >= 1 the
  // grid's body row i-1 -- its dragged height or the default -- and any row past the grid the default.
  // These are the exact numbers buildWaterfallPdf lays the grid out with (HDR_ROW_PT, rowPt[]).
  function sideRowPtFn(schedule){
    let maxRows = 0;
    if(schedule && schedule.weeks && schedule.weeks.length){
      maxRows = sheetRowCount(schedule, computeYearBlocks(schedule.weeks));
    }
    const fn = i => ((i >= 1 && i <= maxRows) ? (rowHeights[i - 1] || ROW_DEFAULT_PX) : ROW_DEFAULT_PX) * ROW_PX_TO_PT;
    fn.maxRows = maxRows;
    return fn;
  }
  function sideRowsFor(nLines, sizePt, row0, rowPt){
    const need = (nLines - 1) * sizePt * SHEET_LINE_RATIO + sizePt * SIDE_GLYPH_RATIO;
    let have = 0, k = 0;
    while(have < need - 0.01 && k < 400){ have += rowPt(row0 + k); k++; }
    return Math.max(1, k);
  }

  // ⭐ THE ONE LAYOUT. The screen, exportExcel and buildWaterfallPdf all read this, so the three cannot
  // place a box differently -- the lesson of the column model (PROJECT-CONTEXT §9a). Per side: segments
  // (`title` | `key` | `line`), each a run of whole sheet rows, and each box's extent. null for a side
  // with no box.
  //
  // Where each box goes, in two passes. First where it WANTS to be: its `row`, or -- with none -- one
  // empty row under the box before it in the list (ruling Q3's stack, which is every calendar saved
  // before 21 Oct 2026). Then top to bottom, a box that would overlap the one above it, or sit closer
  // than the empty row, goes down until it doesn't. Its stored row is untouched, so a box pushed down by
  // one that grew while typing comes back up when it shrinks.
  //
  // `opts` is for the drag (sideDropPlan): `boxes` lays out a working copy instead of the store, and
  // `lead: {box, side, row}` puts one box on that side and row, ahead of any box that wants the same row.
  // The writers never pass it. A drag is a screen thing: its plans pass `screen: true` with them.
  //
  // ⛔ TWO AUDIENCES since "Hide from Exports" (21 Oct 2026). With no `opts` this is the PRINTED layout: a
  // `noExport` box is left out, and the boxes under it close up as if it had never been added (those that
  // stack; a box with a `row` keeps it). That is
  // what the frozen writers get, because they call sideBoxLayoutSafe(schedule) with nothing else -- so not
  // one frozen line changed (CLAUDE.md, sanctioned pattern 1). The screen passes SIDE_SCREEN and gets every
  // box. A box's segments keep its index into sideBoxes either way. ⚠️ A new SCREEN caller must pass
  // SIDE_SCREEN, or a hidden box vanishes from the screen too.
  function sideBoxLayout(schedule, opts){
    const boxes = (opts && opts.boxes) || sideBoxes, lead = (opts && opts.lead) || null;
    const shown = b => !!(opts && opts.screen) || !b.noExport;
    const rowPt = sideRowPtFn(schedule);
    const entries = boxes.some(b => b.kind === 'key') ? sideKeyEntries(schedule) : [];
    const out = { any: false, rowPt, maxRows: rowPt.maxRows, left: null, right: null };
    const sideOf = i => (lead && lead.box === i) ? lead.side : boxes[i].side;
    SIDE_SIDES.forEach(side=>{
      const mine = [];
      boxes.forEach((b, i)=>{ if(sideOf(i) === side && shown(b)) mine.push(i); });
      if(!mine.length) return;
      const chars = sideWidthChars(side);
      let segs = [];
      // Box i's segments from row0 down; returns the row after its last.
      const place = (i, row0)=>{
        const b = boxes[i];
        let row = row0;
        const text = (type, str, f, base, fill, li)=>{
          const fm = Object.assign({}, base, f || {});
          const size = fm.size || 11, bold = !!fm.bold;
          const lines = sideWrap(str, chars, size, bold);
          const rows = sideRowsFor(lines.length, size, row, rowPt);
          segs.push({ box: i, type, li, row, rows, text: str, lines, size, bold, italic: !!fm.italic,
                      color: fm.color || '#000000', align: fm.align || 'left', fill: fm.highlight || fill || null });
          row += rows;
        };
        text('title', b.title, b.titleFmt, SIDE_TITLE_FMT, SIDE_TITLE_FILL, -1);
        if(b.kind === 'key'){
          sideKeyRows(b, entries).forEach(e=>{
            const size = Math.round(11 * sideKeyScale(e.name, chars) * 100) / 100;
            segs.push({ box: i, type: 'key', hex: e.hex, auto: e.auto, row, rows: 1, text: e.name, lines: [e.name],
                        size, bold: true, italic: false, color: textColorFor(e.hex), align: 'center', fill: e.hex });
            row++;
          });
        } else {
          b.lines.forEach((l, li)=> text('line', l.t, l.f, SIDE_LINE_FMT, null, li));
        }
        return row;
      };
      // Pass 1: where each box wants to be. A box's height depends on the rows it starts on (a dragged
      // grid row is taller), so a stacked box is measured where it wants to sit.
      const want = [];
      let prevEnd = null;
      mine.forEach((i, n)=>{
        const isLead = !!(lead && lead.box === i);
        const r = isLead ? lead.row : Number.isInteger(boxes[i].row) ? boxes[i].row
                : (prevEnd === null ? 0 : prevEnd + SIDE_GAP_ROWS);
        want.push({ i, r, n, lead: isLead });
        const next = mine[n + 1];
        if(next !== undefined && !(lead && lead.box === next) && !Number.isInteger(boxes[next].row)){
          const keep = segs; segs = [];
          prevEnd = place(i, r);
          segs = keep;
        }
      });
      // Pass 2: top to bottom, never overlapping. Ties go to the box being placed, then to list order.
      want.sort((a, b)=> (a.r - b.r) || (b.lead - a.lead) || (a.n - b.n));
      const extents = [];
      let floor = 0;
      want.forEach(w=>{
        const row0 = Math.max(w.r, floor);
        const end = place(w.i, row0);
        extents.push({ box: w.i, row0, row1: end - 1 });
        floor = end + SIDE_GAP_ROWS;
      });
      out[side] = { chars, segs, extents, rows: extents[extents.length - 1].row1 + 1 };
      out.any = true;
    });
    return out;
  }
  // ⛔ What the frozen writers call. A box must never be able to stop an export: on any error the
  // writers get "no boxes" -- which is also exactly what they got before this feature existed.
  // Every box hidden from exports is the same "no boxes", the very object a calendar without one gets, so
  // both writers' bytes are those of a calendar that never had a box (leg `sbnoexport` N2, N3).
  const SIDE_SCREEN = Object.freeze({ screen: true });
  function sideBoxLayoutSafe(schedule, opts){
    if(!sideBoxes.some(b => (opts && opts.screen) || !b.noExport)) return { any: false, left: null, right: null, rows: 0 };
    try { return sideBoxLayout(schedule, opts); }
    catch(err){ console.error(err); return { any: false, left: null, right: null }; }
  }
  // Width in points (= the grid's column units through charsToScreenPx, which IS points in the PDF) of
  // a side and its spacer; 0 for a side with no box.
  function sideSidePt(S){ return S ? charsToScreenPx(S.chars) + charsToScreenPx(SIDE_GAP_CHARS) : 0; }
  // The extent BOTH writers hand frozen sheetPageOrientation() (ruling Q4: orientation from grid +
  // boxes). The FLAT height model, as sheetGridMetrics() measures the grid -- a dragged row must not be
  // able to turn the page over. With no box it returns the grid's own numbers, untouched.
  function sideBoxPageExtent(L, metrics){
    if(!L || !L.any) return { w: metrics.gridW, h: metrics.gridH };
    const rows = Math.max(L.left ? L.left.rows : 0, L.right ? L.right.rows : 0);
    return { w: metrics.gridW + sideSidePt(L.left) + sideSidePt(L.right),
             h: Math.max(metrics.gridH, rows * ROW_DEFAULT_PX * ROW_PX_TO_PT) };
  }
  // The PDF's real extents, in unscaled points: what buildWaterfallPdf fits and centres. All zero
  // with no box, which is what keeps its arithmetic -- and its bytes -- exactly as they were.
  function sideBoxPdfExtent(L){
    if(!L || !L.any) return { left: 0, right: 0, h: 0 };
    const sideH = S => { let h = 0; if(S) for(let i = 0; i < S.rows; i++) h += L.rowPt(i); return h; };
    return { left: sideSidePt(L.left), right: sideSidePt(L.right), h: Math.max(sideH(L.left), sideH(L.right)) };
  }

  // ⛔ Called ONLY from frozen exportExcel (frozen edit E3, owner-approved 20 Oct 2026). `cols` gives the
  // side column for each side; the spacer is the column between it and the grid. `gridRows` is the
  // last row the grid sets a height on -- rows past it get the default 15 pt explicitly (plan §5.1).
  function writeSideBoxesXlsx(ws, L, cols, gridRows){
    if(!L || !L.any) return;
    const thin = { style: 'thin' };
    const argb = hex => 'FF' + String(hex).replace('#', '').toUpperCase();
    SIDE_SIDES.forEach(side=>{
      const S = L[side];
      if(!S) return;
      const col = cols[side];
      ws.getColumn(col).width = Math.min(EXCEL_MAX_COL_CHARS, S.chars);
      ws.getColumn(side === 'left' ? col + 1 : col - 1).width = SIDE_GAP_CHARS;
      for(let r = 0; r < S.rows; r++){
        if(r + 1 > gridRows) ws.getRow(r + 1).height = ROW_DEFAULT_PX * ROW_PX_TO_PT;
      }
      S.segs.forEach(sg=>{
        const r0 = sg.row + 1, r1 = sg.row + sg.rows;
        if(r1 > r0) ws.mergeCells(r0, col, r1, col);
        const cell = ws.getRow(r0).getCell(col);
        cell.value = sg.text ? sg.text : null;
        const font = { name: 'Calibri', size: sg.size, color: { argb: argb(sg.color) } };
        if(sg.bold) font.bold = true;
        if(sg.italic) font.italic = true;
        cell.font = font;
        // Key names never wrap (they shrink, like phase labels); text wraps inside its merged rows.
        cell.alignment = { horizontal: sg.align, vertical: 'middle', wrapText: sg.type !== 'key' };
        if(sg.fill) cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: argb(sg.fill) } };
      });
      // Each box's outline, set on EVERY cell of its rows: a merged range only draws an edge its own
      // cells carry (exportExcel's note on the hiatus band's rightmost cell). Plus the rule under the title.
      S.extents.forEach(ex=>{
        const t = S.segs.find(sg => sg.box === ex.box && sg.type === 'title');
        const titleEnd = t ? t.row + t.rows - 1 : -1;
        for(let r = ex.row0; r <= ex.row1; r++){
          const bd = { left: thin, right: thin };
          if(r === ex.row0) bd.top = thin;
          if(r === ex.row1 || r === titleEnd) bd.bottom = thin;
          ws.getRow(r + 1).getCell(col).border = bd;
        }
      });
    });
  }

  // ⛔ Called ONLY from frozen buildWaterfallPdf (frozen edit E6, owner-approved 20 Oct 2026), after the
  // grid is drawn. `g` carries the writer's own geometry and fonts: scale, the content's left edge, the
  // grid's right edge and top, and the two Carlito faces.
  function drawSideBoxesPdf(page, L, g){
    if(!L || !L.any) return;
    const S = v => v * g.scale;
    const asc = g.reg.ascent / g.reg.unitsPerEm, desc = g.reg.descent / g.reg.unitsPerEm;
    // buildWaterfallPdf's baselineIn(): CSS half-leading on the font's real metrics, block centred.
    const baselineIn = (topY, h, lines, size, i)=>{
      const lh = size * SHEET_LINE_RATIO;
      const top = topY + Math.max(0, (h - lines * lh) / 2);
      return top + i * lh + (lh - (asc - desc) * size) / 2 + asc * size;
    };
    const rowY = [];   // unscaled top of each sheet row, from the grid's top
    const yOf = i => { while(rowY.length <= i){ const k = rowY.length; rowY.push(k ? rowY[k - 1] + L.rowPt(k - 1) : 0); } return rowY[i]; };
    SIDE_SIDES.forEach(side=>{
      const B = L[side];
      if(!B) return;
      const w = S(charsToScreenPx(B.chars));
      const x = side === 'left' ? g.contentX : g.gridRight + S(charsToScreenPx(SIDE_GAP_CHARS));
      const pad = S(3);
      B.segs.forEach(sg=>{
        const y = g.gridTop + S(yOf(sg.row)), h = S(yOf(sg.row + sg.rows) - yOf(sg.row));
        if(sg.fill) page.rect(x, y, w, h, sg.fill);
        const size = S(sg.size), ttf = sg.bold ? g.bold : g.reg, tag = sg.bold ? 'F2' : 'F1';
        page.clipPush(x, y, w, h);
        sg.lines.forEach((ln, i)=>{
          const tw = ttfTextWidth(ttf, ln, size);
          const tx = sg.align === 'center' ? x + (w - tw) / 2 : sg.align === 'right' ? x + w - pad - tw : x + pad;
          page.text(ln, tx, baselineIn(y, h, sg.lines.length, size, i), tag, size, sg.color, sg.italic ? 0.21 : 0);
        });
        page.clipPop();
      });
      B.extents.forEach(ex=>{
        const y0 = g.gridTop + S(yOf(ex.row0)), y1 = g.gridTop + S(yOf(ex.row1 + 1));
        const t = B.segs.find(sg => sg.box === ex.box && sg.type === 'title');
        if(t && t.row + t.rows - 1 < ex.row1){
          const ty = g.gridTop + S(yOf(t.row + t.rows));
          page.line(x, ty, x + w, ty, SIDE_PDF_RULE, 0.75);
        }
        page.line(x, y0, x + w, y0, SIDE_PDF_FRAME, 1.2);
        page.line(x, y1, x + w, y1, SIDE_PDF_FRAME, 1.2);
        page.line(x, y0, x, y1, SIDE_PDF_FRAME, 1.2);
        page.line(x + w, y0, x + w, y1, SIDE_PDF_FRAME, 1.2);
      });
    });
  }

  // ---------- SIDE BOXES ON SCREEN (plan §3.3, §4) ----------
  // Rendered from the store into the two .side-col hosts after every grid render (a childList observer
  // on #table-wrap: CLAUDE.md sanctioned pattern 3), and after every edit of their own. They are drawn
  // like the grid, not like the chrome -- Carlito 11 px, the 20 px row pitch, a dark frame -- because
  // they print; each line's min-height is its print row count x ROW_DEFAULT_PX (plan §4.2), so the
  // screen shows how many rows a line takes in print. The chrome around them (grip, x, format bar, width
  // handle, the Side boxes menu) is the app's.
  const sideCols = { left: document.querySelector('.side-col[data-side="left"]'),
                     right: document.querySelector('.side-col[data-side="right"]') };
  const sidePanel = document.querySelector('main.preview-panel');
  let sideLastSig = null;
  let sideFmtTarget = null;     // { box, li } -- li -1 is the title -- or null
  let sideFmtBar = null;        // the body-level format bar, built once
  let sideFmtPressing = false;
  let sideMenu = null, sideMenuAnchor = null;
  let sideFmtLive = false;      // a colour well is being dragged: its edits bank as ONE step, on `change`

  // Everything a render of the side columns depends on. A grid render that changes none of it leaves
  // the side columns alone, so a caret in a box is never thrown away by an unrelated re-render.
  function sideSignature(L){
    if(!L.any) return '[]';
    const pick = S => S && { c: S.chars, s: S.segs.map(sg => [sg.box, sg.type, sg.li, sg.hex, sg.rows, sg.size, sg.text]) };
    return JSON.stringify([sideBoxes, sideWidths, pick(L.left), pick(L.right)]);
  }
  function sideFmtCss(f, base){
    const fm = Object.assign({}, base, f || {});
    const out = [];
    const size = finiteNum(fm.size);
    if(size && size > 0 && size <= 400) out.push('font-size:' + size + 'px');
    out.push('font-weight:' + (fm.bold ? 700 : 400));
    out.push('font-style:' + (fm.italic ? 'italic' : 'normal'));
    if(isHexColor(fm.color)) out.push('color:' + fm.color);
    // Ruling Q6: a highlight fills the whole line, as the workbook's cell fill must.
    if(isHexColor(fm.highlight)) out.push('background-color:' + fm.highlight);
    if(fm.align === 'left' || fm.align === 'center' || fm.align === 'right') out.push('text-align:' + fm.align);
    return out.join(';');
  }
  function sideBoxHtml(L, S, i){
    const b = sideBoxes[i];
    const segs = S.segs.filter(sg => sg.box === i);
    const h = sg => 'min-height:' + (sg.rows * ROW_DEFAULT_PX) + 'px';
    let html = `<div class="sb-box${b.noExport ? ' sb-noexport' : ''}" data-i="${i}" data-kind="${b.kind}">`
      + `<div class="sb-chrome"><button type="button" class="sb-grip" title="Drag to move this box (or Alt+arrow keys)" aria-label="Move box">&#8942;&#8942;</button>`
      + `<button type="button" class="sb-del" title="Delete this box" aria-label="Delete box">&times;</button></div>`;
    segs.forEach(sg=>{
      if(sg.type === 'title'){
        html += `<div class="sb-title sb-edit" contenteditable="plaintext-only" spellcheck="false" data-li="-1" data-ph="Title"`
          + ` style="${h(sg)};${sideFmtCss(b.titleFmt, SIDE_TITLE_FMT)}">${escHtml(b.title)}</div>`;
      } else if(sg.type === 'key'){
        html += `<div class="sb-key" data-hex="${sg.hex}" style="background:${sg.fill};color:${sg.color};font-size:${sg.size}px">`
          + `<span class="sb-key-name" contenteditable="plaintext-only" spellcheck="false" data-ph="${escHtml(sg.auto || '')}">${escHtml(sg.text)}</span>`
          + `<button type="button" class="sb-key-hide" title="Hide this row" aria-label="Hide row">&times;</button></div>`;
      } else {
        const l = b.lines[sg.li];
        html += `<div class="sb-line sb-edit" contenteditable="plaintext-only" spellcheck="false" data-li="${sg.li}"`
          + ` style="${h(sg)};${sideFmtCss(l.f, SIDE_LINE_FMT)}">${escHtml(l.t)}</div>`;
      }
    });
    if(b.kind === 'key'){
      const shown = new Set(segs.map(sg => sg.hex));
      const hiddenNow = (b.hidden || []).filter(x => !shown.has(x) && sideKeyEntries(currentSchedule).some(e => e.hex === x));
      if(hiddenNow.length) html += `<button type="button" class="sb-unhide">Show ${hiddenNow.length} hidden row${hiddenNow.length > 1 ? 's' : ''}</button>`;
    }
    // "Hide from Exports" (owner's wording, 21 Oct 2026): a tab hanging under the box, in the empty row
    // every box keeps below it, so it covers nothing. It shows on hover, and stays shown -- pressed -- while
    // the box is hidden, which is how the screen says this box will not print. The label never changes;
    // aria-pressed carries the state. No id (collectFieldValues).
    html += `<button type="button" class="sb-noexp" aria-pressed="${b.noExport ? 'true' : 'false'}" title="${b.noExport
      ? 'This box shows here but is left out of Excel and the PDF. Click to export it again.'
      : 'Keep this box on screen but leave it out of Excel and the PDF'}">Hide from Exports</button>`;
    return html + '</div>';
  }
  function renderSideBoxes(force){
    if(!sideCols.left || !sideCols.right || !sidePanel) return;
    const L = sideBoxLayoutSafe(currentSchedule, SIDE_SCREEN);
    const sig = sideSignature(L);
    // Unchanged boxes still follow the grid: a render can move its rows (a taller header, a dragged row).
    if(!force && sig === sideLastSig){ positionSideBoxes(L); return; }
    sideLastSig = sig;
    // A rebuild must not throw away the caret: whatever text was focused is focused again afterwards, at
    // the same offset (moving from one key name to the next re-renders on the first one's blur).
    const ae = document.activeElement;
    let keep = null;
    if(ae && ae.closest && ae.closest('.side-col') && (ae.classList.contains('sb-edit') || ae.classList.contains('sb-key-name'))){
      const bx = ae.closest('.sb-box'), k = ae.closest('.sb-key');
      keep = { i: bx.dataset.i, li: ae.dataset.li, hex: k ? k.dataset.hex : null, at: sideCaret(ae).at };
    }
    sidePanel.classList.toggle('has-side-boxes', L.any);
    const scrolled = {};
    SIDE_SIDES.forEach(side=>{
      const col = sideCols[side], S = L[side];
      const old = col.querySelector('.sb-stack');
      scrolled[side] = old ? old.scrollTop : null;
      if(!S){ col.hidden = true; col.replaceChildren(); return; }
      col.hidden = false;
      col.style.setProperty('--sb-w', charsToScreenPx(S.chars) + 'px');
      // Top to bottom (the layout's extents are in that order), so the tab order reads down the side.
      const ids = S.extents.map(ex => ex.box);
      col.innerHTML = `<div class="sb-stack">${ids.map(i => sideBoxHtml(L, S, i)).join('')}<div class="sb-sizer"></div></div>`
        + `<div class="sb-width" role="separator" aria-orientation="vertical" title="Drag to change this side's width; double-click for the default" aria-label="Side width"></div>`;
    });
    positionSideBoxes(L);
    // A rebuild starts each column scrolled to the top; put it back where it was. A column that has only
    // just appeared opens level with the grid instead, so a box dropped on an empty side shows where it
    // was let go. From there each column scrolls on its own (sideScrollOwn).
    SIDE_SIDES.forEach(side=>{
      const st = L[side] && sideCols[side].querySelector('.sb-stack');
      if(st) st.scrollTop = scrolled[side] !== null ? scrolled[side] : sideLevelWithGrid(side);
    });
    if(keep){
      const sel = `.sb-box[data-i="${keep.i}"] ` + (keep.hex ? `.sb-key[data-hex="${keep.hex}"] .sb-key-name` : `.sb-edit[data-li="${keep.li}"]`);
      const el = sidePanel.querySelector('.side-col ' + sel);
      if(el) sideFocusAt(el, keep.at);
    }
    if(sideFmtTarget && !sideTargetEl()) hideSideFmt();
    else if(sideFmtTarget) placeSideFmt();
  }
  // Re-derive the heights and places in place while typing, without rebuilding anything under the
  // caret: a line that takes another row can push the box under it down.
  function refreshSideHeights(){ positionSideBoxes(null); }

  // ---- Where the boxes are drawn: level with the grid's own rows (owner, 21 Oct 2026) ----
  // A box on row r prints beside the grid's sheet row r, so on screen it is drawn beside that row too:
  // otherwise a box moved "next to March" would print next to May. The rows are READ off the frozen
  // table (each body <tr> carries data-row; reading never edits it), and a row past the grid's last
  // continues at the default height, as both writers print it (sideRowPtFn).
  //
  // Measured in SCREEN px (getBoundingClientRect), the one unit the zoomed #table-wrap and the
  // unzoomed side columns agree on: a position becomes a side column's own px by dividing by ITS zoom
  // (1), and a height of rows becomes the grid's own px by dividing by the grid's -- so a box's TOP is
  // on its row at any zoom while its size stays the 100% size (positionSideBoxes).
  let sideRows100 = null;
  function sideGridRows(){
    const tw = document.getElementById('table-wrap');
    const scroll = tw && tw.querySelector(':scope > .sheet-scroll');
    const table = scroll && scroll.querySelector('table.sheet-table');
    if(!table || !table.getClientRects().length) return null;
    const z = gridZoom(tw), t0 = table.getBoundingClientRect().top;
    const tops = [0];
    let bottom = table.tHead ? table.tHead.getBoundingClientRect().bottom - t0 : ROW_DEFAULT_PX * z;
    table.querySelectorAll(':scope > tbody > tr[data-row]').forEach(tr=>{
      const r = tr.getBoundingClientRect();
      tops.push(r.top - t0); bottom = r.bottom - t0;
    });
    const n = tops.length, pitch = ROW_DEFAULT_PX * z;
    const rel = r => r < n ? tops[r] : bottom + (r - n) * pitch;
    // The rows' heights as laid out at 100%, kept for the zoom: a grid laid out at another zoom has
    // slightly different rows (20.00 px a row at 200% against 20.84 at 100%, text laid out at the zoomed
    // size), and the boxes keep their 100% size whatever the zoom (positionSideBoxes).
    if(z === 1) sideRows100 = { n, tops: tops.slice(), bottom };
    return {
      scroll, table, z, n,
      // Row r's top below the table's top (the heading row's top), in screen px; scroll does not move it.
      rel,
      // Row r's top in the grid's own px AS LAID OUT AT 100%, when that is known for these rows.
      rel100: (sideRows100 && sideRows100.n === n)
        ? (R => r => r < R.n ? R.tops[r] : R.bottom + (r - R.n) * ROW_DEFAULT_PX)(sideRows100)
        : r => rel(r) / z,
      // The table's top on screen as of now, and as it would be with the grid scrolled to the top.
      top: ()=> table.getBoundingClientRect().top,
      top0: ()=> table.getBoundingClientRect().top + scroll.scrollTop * z,
    };
  }
  // WIDE is the side columns beside the grid (the panel's grid layout, above 960 px). Below that they
  // stack under it, where nothing lines up with the grid and row 0 is simply the column's top.
  function sideWide(){
    return !!sidePanel && sidePanel.classList.contains('has-side-boxes') && getComputedStyle(sidePanel).display === 'grid';
  }
  // One side's row map, everything read once: `css(r)` is row r's top in the stack's own px, from its
  // content top (what a box's `top` is), and `screen(r)` where that is on screen as scrolled now. A side
  // with no column (an empty side, mid-drag) maps straight onto the grid's rows.
  function sideRowMap(side, G){
    const col = sideCols[side];
    const stack = col && !col.hidden ? col.querySelector('.sb-stack') : null;
    const wide = sideWide();
    if(!stack || !stack.getClientRects().length){
      const t = G ? G.top() : 0;
      return { stack: null, zs: 1, css: r => G ? G.rel(r) : r * ROW_DEFAULT_PX,
               screen: r => G ? t + G.rel(r) : r * ROW_DEFAULT_PX };
    }
    const zs = gridZoom(col), sr = stack.getBoundingClientRect(), st = stack.scrollTop;
    // Wide: the stack's content top sits where the grid's table top sits with both scrolled to the top,
    // so the two line up whenever they are scrolled alike; each scrolls on its own (sideScrollOwn), and
    // `screen` reads this column's own scroll. Narrow: row 0 is the stack's own top.
    const base = (G && wide) ? (G.top0() - sr.top) / zs : 0;
    const css = r => base + (G ? G.rel(r) : r * ROW_DEFAULT_PX * zs) / zs;
    return { stack, zs, css, screen: r => sr.top + (css(r) - st) * zs };
  }
  // Puts every drawn box on its rows, every line at the height of the rows it takes, and the column's
  // scroll length to at least the grid's, so a box can be carried down beside any of the grid's rows.
  function positionSideBoxes(L){
    if(!sideCols.left || !sideCols.right) return;
    if(!L) L = sideBoxLayoutSafe(currentSchedule, SIDE_SCREEN);
    const G = sideGridRows();
    SIDE_SIDES.forEach(side=>{
      const S = L[side];
      if(!S) return;
      const M = sideRowMap(side, G);
      if(!M.stack) return;   // hidden (the month view): placed again when it shows
      const zg = G ? G.z : 1;
      const tall = (row, rows)=> G ? G.rel100(row + rows) - G.rel100(row) : rows * ROW_DEFAULT_PX;
      S.segs.forEach(sg=>{
        const box = M.stack.querySelector(`:scope > .sb-box[data-i="${sg.box}"]`);
        if(!box) return;
        if(sg.type === 'key'){
          const el = box.querySelector(`.sb-key[data-hex="${sg.hex}"]`);
          if(el) el.style.height = tall(sg.row, 1) + 'px';
        } else {
          const el = box.querySelector(`.sb-edit[data-li="${sg.li}"]`);
          if(el) el.style.minHeight = tall(sg.row, sg.rows) + 'px';
        }
      });
      // Tops last, top to bottom, once each box has its height: level with its row, unless the box
      // above reaches past that, when it sits just under it instead. That happens zoomed OUT, where
      // the grid's rows shrink and the boxes keep their size (owner, 21 Oct 2026: "the side boxes
      // should not change size with the viewport slider"), and it is screen only: print reads rows.
      // At 100% the empty row between boxes always leaves room, so nothing moves.
      let below = -Infinity, bottom = 0;
      S.extents.forEach(ex=>{
        const el = M.stack.querySelector(`:scope > .sb-box[data-i="${ex.box}"]`);
        if(!el) return;
        const top = Math.max(M.css(ex.row0), below);
        el.style.top = top + 'px';
        bottom = top + el.offsetHeight;
        below = bottom + SIDE_SCREEN_GAP_PX;
      });
      let h = Math.max(M.css(S.rows) + 2, bottom);   // + the box's frame
      // Wide: at least the grid's whole scroll length (+ its 2 px frame and a little), so the column can
      // reach every row the grid can. Read off the grid, which is observed, never off the column's own
      // height cap: that moves with the grid fit, which settles after this runs and signals nothing.
      if(G && sideWide()) h = Math.max(h, G.scroll.scrollHeight * zg / M.zs + 4);
      const sizer = M.stack.querySelector(':scope > .sb-sizer');
      if(sizer) sizer.style.height = Math.ceil(h) + 'px';
    });
  }
  // sideScrollOwn: each side column and the grid scroll ON THEIR OWN. Owner, 22 Oct 2026: *"it should
  // only scroll the viewport or only scroll the sidebar with the boxes dependent on where your cursor
  // is"* -- the wheel scrolls whatever is under the pointer, so a colour key can stay in view while the
  // grid scrolls under it. ⛔ This REVERSES free positions' "the side columns scroll with the grid"
  // (21 Oct, a choice made in that session, never ruled): there is deliberately no scroll listener
  // tying the two together any more. A box is still drawn level with its sheet row in its own column
  // (sideRowMap), so the two line up whenever they are scrolled alike -- at the top, for instance -- and
  // a drop lands on the row as drawn in the column it is dropped in.
  //
  // Where a side's column would be scrolled to sit level with the grid as scrolled now: a column that
  // has only just appeared opens there (renderSideBoxes).
  function sideLevelWithGrid(side){
    if(!sideWide()) return 0;
    const tw = document.getElementById('table-wrap');
    const g = tw && tw.querySelector(':scope > .sheet-scroll');
    return g ? g.scrollTop * gridZoom(tw) / gridZoom(sideCols[side]) : 0;
  }
  window.addEventListener('resize', ()=>{ if(sideBoxes.length) positionSideBoxes(null); });
  // One committed structural edit is ONE undo step, banked deterministically on both sides of the write
  // (the day menu's pattern) rather than left to the 500 ms debounce. Typing still coalesces through it.
  function sideCommit(fn){
    pushUndoSnapshot();
    fn();
    renderSideBoxes(true);
    markDirty();
    cancelPendingUndoPush();
    pushUndoSnapshot();
  }
  // A new grid (childList) or a new calendar zoom on #table-wrap (its style) can move the rows the boxes
  // sit beside; observing changes nothing (sanctioned pattern 3).
  new MutationObserver(recs=>{
    if(recs.some(r => r.type === 'childList')) watchSideGrid();
    renderSideBoxes(false);
  }).observe(document.getElementById('table-wrap'), { childList: true, attributes: true, attributeFilter: ['style'] });
  // The header bar above the grid's rows can change height without a re-render (a narrower window wraps
  // it), which moves every row; so can the table itself. And the grid's box changes height when the app
  // shell's grid fit settles (after a zoom, a moment after this observer's own pass), which is what a
  // side column's length is measured against. Re-observed after each render, which replaces them all.
  let sideGridRO = null;
  function watchSideGrid(){
    if(typeof ResizeObserver !== 'function') return;
    if(!sideGridRO) sideGridRO = new ResizeObserver(()=>{ if(sideBoxes.length) positionSideBoxes(null); });
    sideGridRO.disconnect();
    const tw = document.getElementById('table-wrap');
    if(!tw) return;
    tw.querySelectorAll(':scope > .sheet-scroll, :scope > .sheet-scroll > *').forEach(el => sideGridRO.observe(el));
  }

  // ---- The Side boxes menu (ruling Q7: the preview toolbar, Waterfall view only) ----
  function closeSideMenu(){
    if(sideMenu){ sideMenu.remove(); sideMenu = null; }
    if(sideMenuAnchor) sideMenuAnchor.setAttribute('aria-expanded', 'false');
    sideMenuAnchor = null;
    document.removeEventListener('mousedown', onSideMenuOutside, true);
    window.removeEventListener('resize', closeSideMenu);
    window.removeEventListener('scroll', closeSideMenu, true);
  }
  function onSideMenuOutside(e){
    if(sideMenuAnchor && sideMenuAnchor.contains(e.target)) return;
    if(sideMenu && !sideMenu.contains(e.target)) closeSideMenu();
  }
  function addSideBox(side, kind){
    closeSideMenu();
    let idx = -1;
    sideCommit(()=>{
      const b = sideNewBox(side, kind);
      // A new box goes UNDER the boxes already on its side, one empty row down; the first, at the top.
      // On a side whose boxes all still stack that is what stacking does, so it gets no row; once a box
      // there has been moved, it is given the row under the lowest.
      if(sideBoxes.some(x => x.side === side && Number.isInteger(x.row))){
        const S = sideBoxLayoutSafe(currentSchedule, SIDE_SCREEN)[side];
        if(S) b.row = Math.min(SIDE_MAX_ROW, S.rows + SIDE_GAP_ROWS);
      }
      sideBoxes.push(b); idx = sideBoxes.length - 1;
    });
    // The cursor lands in the new box's title, selected, so typing renames it.
    const t = sideCols[side] && sideCols[side].querySelector(`.sb-box[data-i="${idx}"] .sb-title`);
    if(t){ t.focus(); const r = document.createRange(); r.selectNodeContents(t); const s = getSelection(); s.removeAllRanges(); s.addRange(r); }
  }
  function openSideMenu(anchor){
    closeSideMenu();
    const pop = document.createElement('div');
    pop.className = 'sb-menu';
    pop.setAttribute('role', 'menu');
    [['key','left','Color key','on the left'], ['key','right','Color key','on the right'],
     ['text','left','Text box','on the left'], ['text','right','Text box','on the right']].forEach(([kind, side, a, b], n)=>{
      if(n === 2){ const sep = document.createElement('div'); sep.className = 'sb-menu-sep'; pop.appendChild(sep); }
      const it = document.createElement('button');
      it.type = 'button';
      it.className = 'sb-menu-item';
      it.setAttribute('role', 'menuitem');
      it.dataset.kind = kind; it.dataset.side = side;
      it.setAttribute('aria-label', a + ' ' + b);
      it.innerHTML = `<span>${a}</span><span class="sb-menu-where">${b}</span>`;
      it.addEventListener('click', ev=>{ ev.stopPropagation(); addSideBox(side, kind); });
      pop.appendChild(it);
    });
    document.body.appendChild(pop);
    sideMenu = pop; sideMenuAnchor = anchor;
    anchor.setAttribute('aria-expanded', 'true');
    const r = anchor.getBoundingClientRect();
    pop.style.top = (window.scrollY + r.bottom + 5) + 'px';
    pop.style.left = (window.scrollX + r.left) + 'px';
    const pr = pop.getBoundingClientRect();
    if(pr.right > window.innerWidth - 8) pop.style.left = (window.scrollX + window.innerWidth - pr.width - 8) + 'px';
    if(pr.bottom > window.innerHeight - 8) pop.style.top = (window.scrollY + r.top - pr.height - 5) + 'px';
    // Bound on the next tick, or the click that opened the menu would close it.
    setTimeout(()=>{
      document.addEventListener('mousedown', onSideMenuOutside, true);
      window.addEventListener('resize', closeSideMenu);
      window.addEventListener('scroll', closeSideMenu, true);
    }, 0);
  }
  // React renders #tb-side-boxes-btn, so it is reached by DELEGATION (HANDOFF §2b-3's law).
  document.addEventListener('click', e=>{
    const b = e.target.closest && e.target.closest('#tb-side-boxes-btn');
    if(!b) return;
    if(sideMenu && sideMenuAnchor === b){ closeSideMenu(); return; }
    openSideMenu(b);
  });
  document.addEventListener('keydown', e=>{ if(e.key === 'Escape' && sideMenu) closeSideMenu(); });

  // ---- Editing text: titles, lines and key names ----
  function sideEditInfo(el){
    const box = el.closest && el.closest('.sb-box');
    if(!box) return null;
    const i = +box.dataset.i, b = sideBoxes[i];
    if(!b) return null;
    return { i, b, box, li: el.dataset.li !== undefined ? +el.dataset.li : null };
  }
  function sideCaret(el){
    const s = getSelection();
    if(!s.rangeCount || !el.contains(s.anchorNode)) return { at: 0, end: 0 };
    const r = s.getRangeAt(0), pre = document.createRange();
    pre.selectNodeContents(el); pre.setEnd(r.startContainer, r.startOffset);
    const at = pre.toString().length;
    pre.selectNodeContents(el); pre.setEnd(r.endContainer, r.endOffset);
    return { at, end: pre.toString().length };
  }
  function sideFocusAt(el, at){
    if(!el) return;
    el.focus();
    const s = getSelection(), r = document.createRange();
    const tn = el.firstChild;
    if(tn && tn.nodeType === 3){ r.setStart(tn, Math.min(at, tn.length)); }
    else r.setStart(el, 0);
    r.collapse(true);
    s.removeAllRanges(); s.addRange(r);
  }
  function sideLineEl(i, li){
    const b = sideBoxes[i];
    return b && sideCols[b.side] ? sideCols[b.side].querySelector(`.sb-box[data-i="${i}"] .sb-edit[data-li="${li}"]`) : null;
  }
  function onSideInput(e){
    const t = e.target;
    if(t.classList.contains('sb-key-name')){
      const info = sideEditInfo(t); if(!info) return;
      const hex = t.closest('.sb-key').dataset.hex;
      // An edit is stored against the COLOUR, so it survives renaming the phase (plan §3.1).
      info.b.names[hex] = sideText(t.textContent, SIDE_MAX_NAME);
      markDirty();
      return;
    }
    if(!t.classList.contains('sb-edit')) return;
    const info = sideEditInfo(t); if(!info) return;
    const txt = t.textContent || '';
    if(/[\r\n]/.test(txt)){ sideSplitPaste(t, info, txt); return; }
    if(info.li === -1) info.b.title = sideText(txt, SIDE_MAX_NAME);
    else if(info.b.lines[info.li]) info.b.lines[info.li].t = sideText(txt, SIDE_MAX_TEXT);
    refreshSideHeights();
    markDirty();
  }
  // Text carrying line breaks (a paste, or a browser that slipped one in) becomes separate lines, each
  // taking the format of the line it was typed into.
  function sideSplitPaste(el, info, txt){
    const parts = String(txt).split(/\r?\n/);
    sideCommit(()=>{
      if(info.li === -1){
        info.b.title = sideText(parts.shift(), SIDE_MAX_NAME);
        if(info.b.kind === 'text') info.b.lines.splice(0, 0, ...parts.map(p => ({ t: sideText(p, SIDE_MAX_TEXT) })));
      } else {
        const f = info.b.lines[info.li].f;
        const add = parts.map(p => Object.assign({ t: sideText(p, SIDE_MAX_TEXT) }, f ? { f: Object.assign({}, f) } : {}));
        info.b.lines.splice(info.li, 1, ...add);
        info.b.lines.length = Math.min(info.b.lines.length, SIDE_MAX_LINES);
      }
    });
  }
  function onSideKeydown(e){
    const t = e.target;
    if(t.classList.contains('sb-grip')){ onSideGripKey(e); return; }
    if(t.classList.contains('sb-key-name')){
      if(e.key === 'Enter' || e.key === 'Escape'){ e.preventDefault(); t.blur(); }
      return;
    }
    if(!t.classList.contains('sb-edit')) return;
    const info = sideEditInfo(t); if(!info) return;
    const { i, b, li } = info;
    if(e.key === 'Escape'){ e.preventDefault(); t.blur(); return; }
    if(e.key === 'Enter'){
      e.preventDefault();
      if(li === -1){
        // Enter in a title goes to the first line; a key's title has none, so it simply commits.
        if(b.kind === 'text') sideFocusAt(sideLineEl(i, 0), 0); else t.blur();
        return;
      }
      if(b.lines.length >= SIDE_MAX_LINES) return;
      const { at, end } = sideCaret(t), txt = t.textContent || '';
      const f = b.lines[li].f;
      sideCommit(()=>{
        b.lines[li].t = txt.slice(0, at);
        // The new line carries the format of the line it was split from, as a word processor does.
        b.lines.splice(li + 1, 0, Object.assign({ t: txt.slice(end) }, f ? { f: Object.assign({}, f) } : {}));
      });
      sideFocusAt(sideLineEl(i, li + 1), 0);
      return;
    }
    if(li === -1) return;
    const { at, end } = sideCaret(t), len = (t.textContent || '').length;
    if(e.key === 'Backspace' && at === 0 && end === 0 && li > 0){
      e.preventDefault();
      const prevLen = b.lines[li - 1].t.length;
      sideCommit(()=>{ b.lines[li - 1].t += b.lines[li].t; b.lines.splice(li, 1); });
      sideFocusAt(sideLineEl(i, li - 1), prevLen);
    } else if(e.key === 'Delete' && at === len && end === len && li < b.lines.length - 1){
      e.preventDefault();
      sideCommit(()=>{ b.lines[li].t += b.lines[li + 1].t; b.lines.splice(li + 1, 1); });
      sideFocusAt(sideLineEl(i, li), len);
    } else if(e.key === 'ArrowUp' && at === 0){
      const prev = sideLineEl(i, li - 1);
      if(prev){ e.preventDefault(); sideFocusAt(prev, (prev.textContent || '').length); }
    } else if(e.key === 'ArrowDown' && end === len){
      const next = sideLineEl(i, li + 1);
      if(next){ e.preventDefault(); sideFocusAt(next, 0); }
    }
  }
  function onSidePaste(e){
    const t = e.target;
    if(!(t.classList && (t.classList.contains('sb-edit') || t.classList.contains('sb-key-name')))) return;
    const txt = (e.clipboardData && e.clipboardData.getData('text/plain')) || '';
    if(!/[\r\n]/.test(txt) && !t.classList.contains('sb-key-name')) return;   // a one-line paste is ordinary typing
    e.preventDefault();
    const one = txt.replace(/[\r\n]+/g, ' ');
    if(t.classList.contains('sb-key-name')){ document.execCommand('insertText', false, one); return; }
    const info = sideEditInfo(t); if(!info) return;
    const { at, end } = sideCaret(t), cur = t.textContent || '';
    sideSplitPaste(t, info, cur.slice(0, at) + txt + cur.slice(end));
  }
  function onSideFocusout(e){
    const t = e.target;
    if(t.classList && t.classList.contains('sb-key-name')){
      // An emptied name goes back to the phase's own (plan §3.1): it is stored by deleting the edit.
      const info = sideEditInfo(t);
      if(info){
        const hex = t.closest('.sb-key').dataset.hex;
        const v = (info.b.names[hex] || '').trim();
        // Typing the phase's own name back in is the same as no edit.
        if(!v || v === t.dataset.ph) delete info.b.names[hex];
      }
      setTimeout(()=> renderSideBoxes(true), 0);
      return;
    }
    if(!(t.classList && t.classList.contains('sb-edit'))) return;
    const to = e.relatedTarget;
    if(sideFmtPressing || (to && to.closest && (to.closest('.sb-fmt') || to.closest('.style-bar') || to.closest('.sb-edit')))) return;
    hideSideFmt();
  }
  function onSideClick(e){
    const t = e.target;
    const del = t.closest('.sb-del');
    if(del){
      const info = sideEditInfo(del); if(!info) return;
      hideSideFmt();
      sideCommit(()=>{ sideBoxes.splice(info.i, 1); });
      return;
    }
    const nx = t.closest('.sb-noexp');
    if(nx){
      const info = sideEditInfo(nx); if(!info) return;
      // Off is the ABSENT key, never false (the store's comment).
      sideCommit(()=>{ if(info.b.noExport) delete info.b.noExport; else info.b.noExport = true; });
      return;
    }
    const hide = t.closest('.sb-key-hide');
    if(hide){
      const info = sideEditInfo(hide); if(!info) return;
      const hex = hide.closest('.sb-key').dataset.hex;
      sideCommit(()=>{ if(!info.b.hidden.includes(hex)) info.b.hidden.push(hex); });
      return;
    }
    const un = t.closest('.sb-unhide');
    if(un){
      const info = sideEditInfo(un); if(!info) return;
      sideCommit(()=>{ info.b.hidden = []; });
    }
  }
  SIDE_SIDES.forEach(side=>{
    const col = sideCols[side];
    if(!col) return;
    col.addEventListener('input', onSideInput);
    col.addEventListener('keydown', onSideKeydown);
    col.addEventListener('paste', onSidePaste);
    col.addEventListener('focusout', onSideFocusout);
    col.addEventListener('click', onSideClick);
    col.addEventListener('focusin', e=>{
      const el = e.target;
      if(!(el.classList && el.classList.contains('sb-edit'))) return;
      const info = sideEditInfo(el); if(!info) return;
      sideFmtTarget = { box: info.i, li: info.li };
      showSideFmt();
    });
    col.addEventListener('pointerdown', e=>{
      if(e.button !== 0) return;
      if(e.target.closest('.sb-grip')) beginSideDrag(e);
      else if(e.target.closest('.sb-width')) beginSideWidthDrag(e, side);
    });
    col.addEventListener('dblclick', e=>{
      if(!e.target.closest('.sb-width')) return;
      if(sideWidths[side] === undefined) return;
      sideCommit(()=>{ delete sideWidths[side]; });
    });
  });

  // ---- The format bar: the header's controls, for one line at a time (plan §3.2) ----
  // Body-level and built once. ⛔ Its own root class (.sb-fmt), NOT .hdr-fmt: syncHdrFmtToolbar() writes
  // into EVERY .hdr-fmt in the document, and the header's handlers are delegated on #table-wrap. The
  // controls reuse the .hf-* classes for their look only.
  function sideTargetEl(){ return sideFmtTarget ? sideLineEl(sideFmtTarget.box, sideFmtTarget.li) : null; }
  function sideTargetFmt(){
    const b = sideFmtTarget && sideBoxes[sideFmtTarget.box];
    if(!b) return null;
    if(sideFmtTarget.li === -1) return { base: SIDE_TITLE_FMT, f: b.titleFmt || {} };
    const l = b.lines && b.lines[sideFmtTarget.li];
    return l ? { base: SIDE_LINE_FMT, f: l.f || {} } : null;
  }
  function buildSideFmt(){
    const bar = document.createElement('div');
    bar.className = 'sb-fmt';
    bar.setAttribute('role', 'toolbar');
    bar.setAttribute('aria-label', 'Box line formatting');
    bar.innerHTML = `<select class="hf-ctl hf-size" title="Text size" aria-label="Text size">
        <option value="">Size</option>${[8,9,10,11,12,13,14,16,18,22].map(s=>`<option value="${s}">${s}</option>`).join('')}
      </select>
      <button type="button" class="hf-ctl hf-btn hf-b" title="Bold" aria-label="Bold"><b>B</b></button>
      <button type="button" class="hf-ctl hf-btn hf-i" title="Italic" aria-label="Italic"><i>I</i></button>
      <label class="hf-ctl hf-swatch" title="Text color"><span class="hf-swatch-ink">A</span>
        <input type="color" class="hf-color" value="#000000" aria-label="Text color"></label>
      <label class="hf-ctl hf-swatch hf-swatch-hl" title="Highlight color"><span class="hf-swatch-ink">A</span>
        <input type="color" class="hf-hl" value="#ffff00" aria-label="Highlight color"></label>
      ${alignMenuHtml()}
      <button type="button" class="hf-ctl hf-btn hf-clear" title="Clear formatting on this line" aria-label="Clear formatting">&#8709;</button>`;
    bar.addEventListener('pointerdown', ()=>{ sideFmtPressing = true; }, true);
    bar.addEventListener('mousedown', e=>{ if(e.target.closest('.hf-btn')) e.preventDefault(); });
    bar.addEventListener('click', e=>{
      const look = sideTargetFmt();
      if(!look) return;
      const eff = Object.assign({}, look.base, look.f);
      if(e.target.closest('.hf-b')) return applySideFmt({ bold: !eff.bold });
      if(e.target.closest('.hf-i')) return applySideFmt({ italic: !eff.italic });
      if(e.target.closest('.hf-clear')) return applySideFmt(null);
      const toggle = e.target.closest('.hf-al-toggle');
      if(toggle){
        const menu = bar.querySelector('.hf-al-menu');
        menu.hidden = !menu.hidden;
        toggle.setAttribute('aria-expanded', menu.hidden ? 'false' : 'true');
        return;
      }
      const opt = e.target.closest('.hf-al-opt');
      if(opt){
        bar.querySelector('.hf-al-menu').hidden = true;
        bar.querySelector('.hf-al-toggle').setAttribute('aria-expanded', 'false');
        // Picking the alignment the line already has clears the override, as the header's menu does.
        return applySideFmt({ align: look.f.align === opt.dataset.align ? '' : opt.dataset.align });
      }
    });
    bar.addEventListener('input', e=>{
      if(e.target.classList.contains('hf-color')) applySideFmt({ color: e.target.value }, true);
      if(e.target.classList.contains('hf-hl')) applySideFmt({ highlight: e.target.value }, true);
    });
    bar.addEventListener('change', e=>{
      if(e.target.classList.contains('hf-size')) applySideFmt({ size: e.target.value ? Number(e.target.value) : '' });
      if(e.target.classList.contains('hf-color') || e.target.classList.contains('hf-hl')){
        sideFmtLive = false; cancelPendingUndoPush(); pushUndoSnapshot();
      }
    });
    return bar;
  }
  document.addEventListener('pointerup', ()=>{ setTimeout(()=>{ sideFmtPressing = false; }, 0); }, true);
  // `live` is a colour well being dragged: state and paint only, banked as one step on its `change`.
  function applySideFmt(patch, live){
    const b = sideFmtTarget && sideBoxes[sideFmtTarget.box];
    if(!b) return;
    const isTitle = sideFmtTarget.li === -1;
    const cur = isTitle ? (b.titleFmt || {}) : ((b.lines[sideFmtTarget.li] || {}).f || {});
    const write = ()=>{
      let next = patch ? Object.assign({}, cur, patch) : {};
      Object.keys(next).forEach(k=>{ if(next[k] === '' || next[k] == null) delete next[k]; });
      next = Object.keys(next).length ? cleanHeaderFormatEntry(next, { n: 0 }) : null;
      if(isTitle){ if(next) b.titleFmt = next; else delete b.titleFmt; }
      else { const l = b.lines[sideFmtTarget.li]; if(next) l.f = next; else delete l.f; }
    };
    if(live){
      if(!sideFmtLive){ sideFmtLive = true; cancelPendingUndoPush(); pushUndoSnapshot(); }
      write(); markDirty();
    }
    else { pushUndoSnapshot(); write(); markDirty(); cancelPendingUndoPush(); pushUndoSnapshot(); }
    // Paint in place -- a rebuild would destroy the caret -- then let the heights follow the new size.
    const el = sideTargetEl();
    if(el){
      const f = isTitle ? b.titleFmt : b.lines[sideFmtTarget.li].f;
      el.setAttribute('style', 'min-height:' + el.style.minHeight + ';' + sideFmtCss(f, isTitle ? SIDE_TITLE_FMT : SIDE_LINE_FMT));
    }
    refreshSideHeights();
    syncSideFmt();
  }
  function syncSideFmt(){
    syncStyleBar();
    if(!sideFmtBar) return;
    const look = sideTargetFmt();
    if(!look) return;
    const f = look.f, eff = Object.assign({}, look.base, f);
    const q = s => sideFmtBar.querySelector(s);
    q('.hf-size').value = f.size ? String(f.size) : '';
    q('.hf-b').classList.toggle('is-on', !!eff.bold);
    q('.hf-i').classList.toggle('is-on', !!eff.italic);
    q('.hf-color').value = f.color || '#000000';
    q('.hf-hl').value = f.highlight || '#ffff00';
    const al = eff.align || 'left';
    q('.hf-al-toggle').innerHTML = alignIcon(al) + '<span class="hf-caret">▾</span>';
    q('.hf-al-toggle').classList.toggle('is-on', !!f.align);
    sideFmtBar.querySelectorAll('.hf-al-opt').forEach(o=>{
      const on = o.dataset.align === al;
      o.classList.toggle('is-on', on);
      o.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  }
  // UNDER the line being edited, over the lines after it: above it, the bar hid the lines just typed --
  // and for a box at the top of its column, the preview toolbar. It flips above only when the window
  // has no room below. A right-side box's bar hangs from the box's RIGHT edge, so it opens over the
  // grid rather than off the window.
  function placeSideFmt(){
    const el = sideTargetEl();
    if(!el || !sideFmtBar) return;
    const r = el.getBoundingClientRect(), br = sideFmtBar.getBoundingClientRect();
    let top = r.bottom + 4;
    if(top + br.height > window.innerHeight - 8) top = r.top - br.height - 4;
    const b = sideBoxes[sideFmtTarget.box];
    let left = (b && b.side === 'right') ? r.right - br.width : r.left;
    if(left + br.width > window.innerWidth - 8) left = window.innerWidth - br.width - 8;
    sideFmtBar.style.top = (window.scrollY + Math.max(8, top)) + 'px';
    sideFmtBar.style.left = (window.scrollX + Math.max(8, left)) + 'px';
  }
  function showSideFmt(){
    // ⛔ The floating bar retired with the text style bar (TEXT-STYLE-BAR-PLAN.md, 21 Oct 2026): the bar under
    // the toolbar styles a box's line through applySideFmt, the code below it. Kept for a page without the
    // bar's host, which the build never is.
    if(styleBar){ setStyleTarget('side'); return; }
    if(!sideFmtBar) sideFmtBar = buildSideFmt();
    if(!sideFmtBar.isConnected) document.body.appendChild(sideFmtBar);
    syncSideFmt();
    placeSideFmt();
  }
  function hideSideFmt(){
    if(sideFmtBar && sideFmtBar.isConnected) sideFmtBar.remove();
    sideFmtTarget = null;
    if(styleTarget === 'side'){ styleTarget = null; syncStyleBar(); }
  }
  window.addEventListener('resize', ()=>{ if(sideFmtTarget) placeSideFmt(); });
  window.addEventListener('scroll', ()=>{ if(sideFmtTarget) placeSideFmt(); }, true);
  document.addEventListener('mousedown', e=>{
    if(!sideFmtTarget) return;
    if(e.target.closest && (e.target.closest('.sb-fmt') || e.target.closest('.style-bar') || e.target.closest('.side-col'))) return;
    hideSideFmt();
  }, true);

  // ---- Moving a box: drag by its grip, to any row on either side (plan §3.3; owner, 21 Oct 2026) ----
  // The box goes where its TOP is let go, on the row nearest it, and a dashed outline shows where it will
  // land while it moves -- beside the grid's rows, which is where it prints. Dropped onto another box:
  // in that box's upper half it takes that box's place and the box moves down under it; in its lower
  // half it goes under that box. Any box it would then overlap moves down too. Nothing else moves: every
  // box keeps the row it is drawn on now (sideDropPlan), so a drag never rearranges the boxes it missed.
  let sideDrag = null;
  // What a move would leave: a working copy of the boxes, each on the row it is drawn on now, with box
  // `from` laid out on `side` at `row`. A calendar whose boxes still stack (no rows yet) gets its rows
  // here, from where they are drawn, so the first move cannot shuffle the boxes it did not touch.
  function sideDropPlan(from, side, row){
    const now = sideBoxLayoutSafe(currentSchedule, SIDE_SCREEN);
    const boxes = sideBoxes.map(b => Object.assign({}, b));
    SIDE_SIDES.forEach(s=>{ if(now[s]) now[s].extents.forEach(ex=>{ boxes[ex.box].row = ex.row0; }); });
    row = Math.max(0, Math.min(SIDE_MAX_ROW, row));
    const T = now[side];
    if(T) for(const ex of T.extents){
      if(ex.box !== from && row > ex.row0 && row <= ex.row1 && row < (ex.row0 + ex.row1 + 1) / 2){ row = ex.row0; break; }
    }
    const L = sideBoxLayout(currentSchedule, { screen: true, boxes, lead: { box: from, side, row } });
    return { L, now, row };
  }
  // Where the dragged box's top (screen y) would land on `side`: the row whose top is nearest it.
  function sideDropTarget(x, topY, from){
    const wrap = document.getElementById('table-wrap').getBoundingClientRect();
    const side = x < wrap.left + wrap.width / 2 ? 'left' : 'right';
    const M = sideRowMap(side, sideGridRows());
    let row = 0, best = Infinity;
    for(let r = 0; r <= SIDE_MAX_ROW; r++){
      const d = Math.abs(M.screen(r) - topY);
      if(d < best){ best = d; row = r; } else if(M.screen(r) > topY) break;
    }
    const plan = sideDropPlan(from, side, row);
    const ex = plan.L[side].extents.find(e => e.box === from);
    return { side, row: plan.row, plan, wrap, empty: !M.stack, y0: M.screen(ex.row0), y1: M.screen(ex.row1 + 1) };
  }
  function showSideDrop(t){
    let ind = sideDrag.ind;
    if(!ind){ ind = sideDrag.ind = document.createElement('div'); document.body.appendChild(ind); }
    ind.style.top = t.y0 + 'px';
    ind.style.height = Math.max(8, t.y1 - t.y0) + 'px';
    if(t.empty){
      // An empty side has no column to land in yet, so the outline is drawn over that edge of the grid.
      ind.className = 'sb-drop sb-drop-zone';
      ind.textContent = 'Drop on the ' + t.side;
      const w = Math.min(180, t.wrap.width / 3);
      ind.style.left = (t.side === 'left' ? t.wrap.left : t.wrap.right - w) + 'px';
      ind.style.width = w + 'px';
    } else {
      const cr = sideCols[t.side].querySelector('.sb-stack').getBoundingClientRect();
      ind.className = 'sb-drop sb-drop-ghost';
      ind.textContent = '';
      ind.style.left = cr.left + 'px';
      ind.style.width = cr.width + 'px';
    }
  }
  function beginSideDrag(e){
    const info = sideEditInfo(e.target);
    if(!info) return;
    e.preventDefault();
    hideSideFmt();
    const br = info.box.getBoundingClientRect();
    sideDrag = { from: info.i, x0: e.clientX, y0: e.clientY, x: e.clientX, y: e.clientY, dy: e.clientY - br.top,
                 moved: false, ind: null, target: null, el: info.box, raf: 0 };
    const aim = ()=>{
      sideDrag.target = sideDropTarget(sideDrag.x, sideDrag.y - sideDrag.dy, sideDrag.from);
      showSideDrop(sideDrag.target);
    };
    // Near the top or bottom of the column the box is being carried down, THAT column scrolls, so a box
    // can be carried to a row that is not in view. The columns scroll on their own (sideScrollOwn), so it
    // is never the grid -- except over an empty side, which has no column yet: its drop zone is drawn over
    // the grid's edge and read off the grid's rows (sideRowMap), so there the grid is what scrolls.
    const tick = ()=>{
      sideDrag.raf = 0;
      if(!sideWide()) return;
      const t = sideDrag.target;
      const st = t && !t.empty ? sideCols[t.side].querySelector('.sb-stack') : null;
      const G = st ? null : sideGridRows();
      const el = st || (G && G.scroll);
      if(!el) return;
      const r = el.getBoundingClientRect(), edge = 36;
      const v = sideDrag.y < r.top + edge ? -Math.ceil((r.top + edge - sideDrag.y) / 3)
              : sideDrag.y > r.bottom - edge ? Math.ceil((sideDrag.y - (r.bottom - edge)) / 3) : 0;
      if(!v) return;
      if(st) st.scrollTop += v / gridZoom(sideCols[t.side]);
      else G.scroll.scrollTop += v / G.z;
      aim();
      sideDrag.raf = requestAnimationFrame(tick);
    };
    const move = ev=>{
      sideDrag.x = ev.clientX; sideDrag.y = ev.clientY;
      if(!sideDrag.moved && Math.hypot(ev.clientX - sideDrag.x0, ev.clientY - sideDrag.y0) < 4) return;
      sideDrag.moved = true;
      sideDrag.el.classList.add('sb-dragging');
      document.body.classList.add('sb-moving');
      aim();
      if(!sideDrag.raf) sideDrag.raf = requestAnimationFrame(tick);
    };
    const end = ev=>{
      window.removeEventListener('pointermove', move, true);
      window.removeEventListener('pointerup', end, true);
      window.removeEventListener('keydown', esc, true);
      const d = sideDrag; sideDrag = null;
      if(d.raf) cancelAnimationFrame(d.raf);
      document.body.classList.remove('sb-moving');
      if(d.ind) d.ind.remove();
      if(d.el) d.el.classList.remove('sb-dragging');
      if(!ev || !d.moved || !d.target) return;
      moveSideBox(d.from, d.target.side, d.target.row);
    };
    const esc = ev=>{ if(ev.key === 'Escape'){ ev.preventDefault(); sideDrag.moved = false; end(null); } };
    window.addEventListener('pointermove', move, true);
    window.addEventListener('pointerup', end, true);
    window.addEventListener('keydown', esc, true);
  }
  // Box `from` to `side`, its top on `row` (sideDropPlan's rules). Every box on the side(s) involved then
  // HAS a row: the one it is drawn on. A drop that changes nothing on screen is no undo step.
  function moveSideBox(from, side, row){
    const b = sideBoxes[from];
    if(!b) return;
    const plan = sideDropPlan(from, side, row);
    const at = (L, i)=>{
      for(const s of SIDE_SIDES){ const ex = L[s] && L[s].extents.find(e => e.box === i); if(ex) return s + ':' + ex.row0; }
      return '';
    };
    if(sideBoxes.every((x, i) => at(plan.L, i) === at(plan.now, i))) return;
    const touched = [b.side, side];
    sideCommit(()=>{
      b.side = side;
      touched.forEach(s=>{
        if(plan.L[s]) plan.L[s].extents.forEach(ex=>{ sideBoxes[ex.box].row = Math.min(SIDE_MAX_ROW, ex.row0); });
      });
    });
  }
  // The grip's keyboard twin. Alt+Up / Alt+Down move the box a row; against the box above or below, it
  // trades places with it instead. Alt+Left / Alt+Right cross to the other side on the same row.
  function onSideGripKey(e){
    if(!e.altKey) return;
    const info = sideEditInfo(e.target); if(!info) return;
    const { i, b } = info;
    const S = sideBoxLayoutSafe(currentSchedule, SIDE_SCREEN)[b.side];
    const k = S ? S.extents.findIndex(ex => ex.box === i) : -1;
    if(k < 0) return;
    const me = S.extents[k], above = S.extents[k - 1], below = S.extents[k + 1];
    if(e.key === 'ArrowUp'){
      e.preventDefault();
      const floor = above ? above.row1 + 1 + SIDE_GAP_ROWS : 0;
      if(me.row0 - 1 >= floor) moveSideBox(i, b.side, me.row0 - 1);
      else if(above) moveSideBox(i, b.side, above.row0);
    } else if(e.key === 'ArrowDown'){
      e.preventDefault();
      if(!below || me.row1 + 2 + SIDE_GAP_ROWS <= below.row0) moveSideBox(i, b.side, me.row0 + 1);
      else moveSideBox(below.box, b.side, me.row0);
    }
    else if(e.key === 'ArrowLeft' && b.side === 'right'){ e.preventDefault(); moveSideBox(i, 'left', me.row0); }
    else if(e.key === 'ArrowRight' && b.side === 'left'){ e.preventDefault(); moveSideBox(i, 'right', me.row0); }
    else return;
    const g = Array.from(document.querySelectorAll('.side-col .sb-box')).find(el => sideBoxes[+el.dataset.i] === b);
    if(g) g.querySelector('.sb-grip').focus();
  }

  // ---- A side's width: drag its inner edge; double-click for the default (plan §3.3) ----
  function beginSideWidthDrag(e, side){
    e.preventDefault();
    const col = sideCols[side];
    const startChars = sideWidthChars(side), startPx = charsToScreenPx(startChars), x0 = e.clientX;
    let chars = startChars;
    document.body.classList.add('sb-resizing');
    const move = ev=>{
      const px = startPx + (side === 'left' ? ev.clientX - x0 : x0 - ev.clientX);
      chars = clampChars(screenPxToChars(px), SIDE_MIN_CHARS, SIDE_MAX_CHARS);
      // Presentation only while dragging; the store is written once, on release (installGridResizers' rule).
      col.style.setProperty('--sb-w', charsToScreenPx(chars) + 'px');
      if(sideFmtTarget) placeSideFmt();
    };
    const up = ()=>{
      window.removeEventListener('pointermove', move, true);
      window.removeEventListener('pointerup', up, true);
      document.body.classList.remove('sb-resizing');
      if(chars === startChars) return;
      sideCommit(()=>{ sideWidths[side] = chars; });
    };
    window.addEventListener('pointermove', move, true);
    window.addEventListener('pointerup', up, true);
  }

  // The 10 "Standard Colors" from Microsoft Office / Excel's color picker.
  const EXCEL_STANDARD_COLORS = [
    '#C00000', '#FF0000', '#FFC000', '#FFFF00', '#92D050',
    '#00B050', '#00B0F0', '#0070C0', '#002060', '#7030A0'
  ];
  // ⭐ THE MONTH NOTE PALETTE (MONTH-NOTES-PLAN.md §2; owner, 20 Oct 2026, by picker: "Remember last colour",
  // "'No fill' plain text", "Light tints", "Greys", all four). A DAY note's colours: No fill, the ten standard
  // colours above, four light tints and three greys. Its own list, because the literal above is frozen
  // (MANTINE-SEAM §4.8) and is still the WATERFALL note's palette: a waterfall-owned note's colour is
  // noteColors[week], which the waterfall, Excel and the waterfall PDF print, and none of them knows No fill.
  // Each entry carries a name, which "Paste notes…" reads (pasteNoteColor). Every tint and grey is plain
  // #RRGGBB, so the frozen renderer, sanitizeSnapshot and both month PDFs take it as they take any colour.
  // ⛔ NO FILL IS '#FFFFFF00', white at zero alpha. It needs no format change, and every build draws it
  // harmlessly: the frozen renderer's `background:${oc}; color:${textColorFor(oc)}` paints a transparent fill
  // with black ink (textColorFor reads the first six digits, white), with no edit; a build from v1.3.0 to
  // v1.5.0 resets a colour that is not #RRGGBB to null in sanitizeSnapshot, so the note shows the default
  // purple; an older build draws it as this one does. A 'none' was rejected: a pre-v1.3.0 build inks it
  // textColorFor('none'), white on nothing. The frozen CSS line beside .mv-note-block takes its border away
  // (ruling Q2, "No box at all"), and the month-PDF writer draws neither fill nor ring for it (mvlNoFill).
  const MV_NOTE_NOFILL = '#FFFFFF00';
  const MV_NOTE_PALETTE = [{name: 'No fill', color: MV_NOTE_NOFILL}].concat(
    ['Dark red', 'Red', 'Orange', 'Yellow', 'Light green', 'Green', 'Light blue', 'Blue', 'Dark blue', 'Purple']
      .map(function(name, i){ return {name: name, color: EXCEL_STANDARD_COLORS[i]}; }),
    [{name: 'Pink', color: '#F7C1D9'}, {name: 'Lavender', color: '#D5C8EC'}, {name: 'Peach', color: '#FCCB9E'},
     {name: 'Pale blue', color: '#BBDCF7'},
     {name: 'Light grey', color: '#D9D9D9'}, {name: 'Grey', color: '#A6A6A6'}, {name: 'Dark grey', color: '#595959'}]);
  function isMvNoFill(c){ return typeof c === 'string' && c.toUpperCase() === MV_NOTE_NOFILL; }
  // The colour a NEW day note opens on: the one last committed from the editor (prefs.mvNoteColor, per user,
  // never in a saved calendar), or the default purple. Only a palette colour is honoured, so a hand-edited
  // store cannot reach a style attribute.
  function mvNoteStartColor(){
    const c = prefs.mvNoteColor;
    const hit = (typeof c === 'string') && MV_NOTE_PALETTE.find(function(p){ return p.color.toUpperCase() === c.toUpperCase(); });
    return hit ? hit.color : MILESTONE_COLOR;
  }
  function rememberMvNoteColor(c){
    if(!MV_NOTE_PALETTE.some(function(p){ return p.color.toUpperCase() === String(c).toUpperCase(); })) return;
    if(prefs.mvNoteColor === c) return;
    prefs.mvNoteColor = c;
    savePrefs();
  }
  // Black or white text depending on the fill's luminance, so labels stay readable
  // on light colors like yellow or light green.
  function textColorFor(hex){
    const h = hex.replace('#','');
    const r = parseInt(h.slice(0,2),16), g = parseInt(h.slice(2,4),16), b = parseInt(h.slice(4,6),16);
    return (0.299*r + 0.587*g + 0.114*b) > 160 ? '#000000' : '#FFFFFF';
  }
  // Escape user-provided text for safe interpolation into HTML (labels, notes, titles).
  function escHtml(s){
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  // Compute per-block slot maps (global column -> visual slot) and the phase-slot count for
  // each year-block. Shared by the live view and the Excel export so they never drift.
  // mc for a block accounts for Simultaneous Post needing its own slot in weeks where every
  // phase slot is already occupied, so the SimPost marker always has room.
  function computeBlockLayout(schedule, yearBlocks){
    const blockSlotMaps = yearBlocks.map((b, bi)=>{
      const firstAppear = new Map();
      for(let i=b.startIdx; i<b.startIdx+b.count; i++){
        const local = i - b.startIdx;
        schedule.weeks[i].cells.forEach(c=>{
          if(c.col!==undefined && !firstAppear.has(c.col)) firstAppear.set(c.col, local);
        });
      }
      const sortedSlots = Array.from(firstAppear.keys()).sort((a,bv)=>{
        const fa = firstAppear.get(a), fb = firstAppear.get(bv);
        return (fa - fb) || (a - bv);
      });
      const map = new Map();
      // ⛔ THE ONE AUTHORISED EDIT TO THIS FROZEN FUNCTION (owner sign-off E0, 1 Sep 2026; scope:
      // the slot-order assignment ONLY -- see COLUMN-ORDER-PLAN.md and HANDOFF.md). stintOrderFor is
      // NOT frozen and returns null unless a stint swap is stored, in which case the line below is
      // byte-for-byte the behaviour it always had. That inertness is the whole safety argument, and
      // the gate proves it by byte-comparing the waterfall PDF and every Excel part.
      // ⚠️ Its job is to PRESERVE this order across a col exchange done upstream in computeSchedule,
      // not to reorder anything here. Read applyStintSwaps before touching either half.
      (stintOrderFor(schedule, bi, sortedSlots) || sortedSlots)
        .forEach((slot, localIdx) => map.set(slot, localIdx));
      return map;
    });
    // Simultaneous Post gets ONE fixed column per block, immediately to the right of the
    // Production column, and always renders there (never hopping columns week to week). It
    // may share that column with a phase that has already ended. We compute that fixed slot
    // and ensure the block has enough columns that the slot is free during every SimPost week.
    const blockMaxConcurrent = [];
    const blockSimSlot = [];
    yearBlocks.forEach((b, bi)=>{
      const slotMap = blockSlotMaps[bi];
      const phaseSlots = slotMap.size;
      const anySim = (()=>{ for(let i=b.startIdx;i<b.startIdx+b.count;i++){ if(schedule.weeks[i].simPost) return true; } return false; })();
      if(!anySim){ blockMaxConcurrent[bi] = Math.max(1, phaseSlots); blockSimSlot[bi] = -1; return; }
      // Production's local slot (SimPost sits just right of it; fall back to rightmost).
      let prodSlot = -1;
      for(let i=b.startIdx; i<b.startIdx+b.count; i++){
        const pc = schedule.weeks[i].cells.find(c=>c.key==='production');
        if(pc && pc.col!==undefined && slotMap.has(pc.col)){ prodSlot = slotMap.get(pc.col); break; }
      }
      let simSlot = prodSlot>=0 ? prodSlot+1 : phaseSlots; // desired column for SimPost
      // Check whether any phase occupies simSlot during a SimPost week; if so, SimPost needs
      // its own extra lane (we widen the block by one and place SimPost in that new column).
      let conflict = false;
      for(let i=b.startIdx; i<b.startIdx+b.count && !conflict; i++){
        const wk = schedule.weeks[i];
        if(!wk.simPost || (wk.cells.length && wk.cells[0].type==='hiatus')) continue;
        for(const c of wk.cells){
          if(c.col!==undefined && slotMap.has(c.col) && slotMap.get(c.col)===simSlot){ conflict = true; break; }
        }
      }
      let mc = phaseSlots;
      if(simSlot >= phaseSlots || conflict){ mc = Math.max(phaseSlots + 1, simSlot + 1); if(conflict) simSlot = mc - 1; }
      blockMaxConcurrent[bi] = Math.max(1, mc);
      blockSimSlot[bi] = Math.min(simSlot, blockMaxConcurrent[bi]-1);
    });
    // For each block build an occupancy grid: occupied[slot] = Map(local week index -> occupant
    // key) for the phase (or Simultaneous Post marker) holding that slot. Spanning is then decided
    // per phase LIFETIME (not per block): a phase may span into a neighbor slot only if that
    // neighbor is empty for every week the phase itself runs. Two phases that never share a
    // week don't block each other, so a phase can fill a column its non-overlapping neighbor
    // used at a different time.
    const blockOccupancy = yearBlocks.map((b, bi)=>{
      const slotMap = blockSlotMaps[bi];
      const mc = blockMaxConcurrent[bi];
      const simSlot = blockSimSlot[bi];
      // Each slot maps local-week -> the KEY of whatever occupies it (a phase key, or a sentinel
      // for the Simultaneous Post marker). Tracking the occupant's identity -- not just "occupied"
      // -- lets phaseRunBounds() stop a run where the column's occupant changes, so a later,
      // non-overlapping phase that REUSES a column isn't treated as one continuous run with the
      // earlier phase (which would let the earlier phase's overlaps block the later one's spanning).
      const SIM_KEY = '␀simpost';
      const occupied = Array.from({length:mc}, ()=>new Map());
      for(let i=b.startIdx; i<b.startIdx+b.count; i++){
        const local = i - b.startIdx;
        const wk = schedule.weeks[i];
        // Hiatus weeks render as a full-width band and don't belong to any phase slot, so
        // they must NOT mark slots as occupied -- otherwise they'd artificially extend a
        // phase's run through the hiatus and block legitimate spanning around it.
        if(wk.cells.length && wk.cells[0].type==='hiatus') continue;
        wk.cells.forEach(c=>{ if(c.col!==undefined && slotMap.has(c.col)){ const s=slotMap.get(c.col); if(s<mc){ occupied[s].set(local, c.key || ('col'+c.col)); } } });
        if(wk.simPost && simSlot>=0) occupied[simSlot].set(local, SIM_KEY); // SimPost's fixed lane
      }
      return occupied;
    });
    return { blockSlotMaps, blockMaxConcurrent, blockOccupancy, blockSimSlot };
  }

  // Given a block's occupancy grid, the local week index, and a phase occupying slot `s`,
  // return the phase's run [start,end] (contiguous weeks it occupies slot s) so we can test
  // whether a neighbor slot is free for the phase's whole lifetime.
  function phaseRunBounds(occupiedSlot, localWeek){
    // Bound the run to the SAME occupant (phase key) that holds the slot at localWeek, stopping
    // where the occupant changes. occupiedSlot is now a Map(local -> key); walking raw occupancy
    // across an occupant change would merge two non-overlapping phases sharing a reused column
    // into one run -- and then one phase's overlaps (e.g. Simultaneous Post) would wrongly block
    // the other phase from spanning to fill the width.
    const key = occupiedSlot.get(localWeek);
    let start = localWeek, end = localWeek;
    while(start-1 >= 0 && occupiedSlot.get(start-1) === key) start--;
    while(occupiedSlot.get(end+1) === key) end++;
    return [start, end];
  }

  // Compute how a single week's phase area (mc phase slots) should be laid out:
  //  - Phases sit in their stable slots.
  //  - A phase spans rightward into a neighbor slot only if that neighbor is empty for the
  //    phase's ENTIRE run (its contiguous set of weeks). Non-overlapping phases don't block
  //    each other; a phase stays narrow beside anything it actually overlaps.
  //  - Simultaneous Post occupies ONE fixed slot for the whole block (simSlot, just right of
  //    Production) and always renders there; a phase span stops before it.
  // `occupancy` is the block's per-slot Map(local week index -> occupant key); `localWeek` is
  // this row's index within the block; `fixedSimSlot` is the block's SimPost column (or -1).
  function computePhaseRowLayout(week, mc, slotMap, occupancy, localWeek, fixedSimSlot){
    const bySlot = new Array(mc).fill(null);
    week.cells.forEach(c=>{
      if(c.col!==undefined && slotMap.has(c.col)){
        const s = slotMap.get(c.col);
        if(s<mc) bySlot[s] = c;
      }
    });

    // Simultaneous Post's slot this week: the fixed lane, only when this week flags it.
    const simSlot = (week.simPost && fixedSimSlot!==undefined && fixedSimSlot>=0) ? fixedSimSlot : -1;

    // Is neighbor slot `n` free for the whole run of the phase occupying slot `s` at this
    // week? True only if `n` is empty across every week that slot `s` phase runs. The SimPost
    // lane is treated like any other column here: a phase may span across it during weeks it
    // isn't used, as long as SimPost never appears in that column during the phase's run.
    const freeForRun = (s, n) => {
      if(!occupancy) return false;
      if(n === simSlot) return false; // don't overrun THIS week's active SimPost marker
      const [rs, re] = phaseRunBounds(occupancy[s], localWeek);
      for(let wk=rs; wk<=re; wk++){ if(occupancy[n].has(wk)) return false; }
      return true;
    };
    // Are ALL slots from..to free for the whole run of the phase occupying slot `s`?
    const freeForRunSpan = (s, from, to) => {
      for(let n=from; n<=to; n++){ if(n===simSlot) return false; if(!freeForRun(s, n)) return false; }
      return true;
    };

    // How wide any ONE phase may get in this row. Phases running at the same time divide the
    // phase area evenly -- two take half each, three a third, four a quarter -- because a row
    // where one phase is three columns wide and the phase beside it is one reads as a mistake
    // rather than as a schedule. A phase running alone is unaffected and still fills the area.
    // A per-phase hiatus band counts as one of the phases sharing the row (owner, 1 Sep 2026) --
    // it stands in for its phase this week, so it divides the width the same way an active phase
    // does, rather than being a fixed 1-column reservation like the Simultaneous Post marker.
    const fixedSlots = (simSlot >= 0 ? 1 : 0);
    const nPhases = bySlot.filter(Boolean).length;
    const spanCap = nPhases > 1 ? Math.max(1, Math.floor((mc - fixedSlots) / nPhases)) : mc;

    const out = [];
    let k = 0;
    while(k < mc){
      if(k === simSlot){
        out.push({kind:'simpost', label:simPostLabel(week), color:SIMPOST_COLOR, textColor:SIMPOST_TEXT, colspan:1});
        k++;
      } else if(bySlot[k]){
        const c = bySlot[k];
        // Same rightward walk for a phase-hiatus band as for an active phase (owner, 1 Sep
        // 2026): it may widen into empty neighbor slots on its own column's terms, same spanCap,
        // same freeForRun check. own/cell are what let applyCellSpanOverrides() -- and, via the
        // data-* attributes rendered from them, the drag/double-click handles -- treat it exactly
        // like a phase cell, with no changes to either.
        let span = 1;
        while(k+span < mc && span < spanCap && !bySlot[k+span] && freeForRun(k, k+span)){ span++; }
        if(c.type === 'phaseHiatus'){
          // Resolve any per-band rename/recolor the user has applied, keyed by week + phase.
          const hKey = c.weekIso + '|' + c.key;
          const hTxt = (hKey in hiatusTexts) ? hiatusTexts[hKey] : c.defaultLabel;
          const hCol = hiatusColors[hKey] || HIATUS_COLOR;
          out.push({kind:'phaseHiatus', label:hTxt, color:hCol, textColor:textColorFor(hCol),
                    colspan:span, weekIso:c.weekIso, phaseKey:c.key, defaultLabel:c.defaultLabel,
                    cell:c, own:k});
        } else {
          out.push({kind:'phase', label:c.label, color:c.color||'#fff', textColor:c.textColor, colspan:span, cell:c, own:k});
        }
        k += span;
      } else {
        // Empty slot(s). If the next phase to the right can legally span left across this
        // empty run (each empty slot is free for that phase's whole run), let that phase
        // left-extend to absorb them -- so a lone phase fills the width even when an earlier
        // (non-overlapping) phase briefly held the column to its left. A per-phase hiatus band
        // is excluded as an absorb target so it can never widen past its own column.
        let n = k;
        while(n < mc && !bySlot[n] && n!==simSlot) n++;
        if(n < mc && bySlot[n] && bySlot[n].type!=='phaseHiatus' && freeForRunSpan(n, k, n-1)){
          // Absorb slots k..n-1 into the phase at slot n, then span it rightward as usual --
          // but never past its even share, and taking from the LEFT first so the run stays
          // flush against whatever is to its left rather than leaving a one-column island.
          let left = Math.min(n - k, Math.max(0, spanCap - 1));
          const from = n - left;
          let span = 1;
          while(n+span < mc && (left + span) < spanCap && !bySlot[n+span] && freeForRun(n, n+span)){ span++; }
          // Anything the cap stopped it taking is still empty and gets its own run.
          if(from > k) out.push({kind:'empty', colspan:from - k});
          const c = bySlot[n];
          out.push({kind:'phase', label:c.label, color:c.color||'#fff', textColor:c.textColor, colspan:left+span, cell:c, own:n});
          k = n + span;
        } else {
          // Plain empty run (merge consecutive empty non-SimPost slots).
          let span = 1;
          while(k+span < mc && !bySlot[k+span] && (k+span)!==simSlot){ span++; }
          out.push({kind:'empty', colspan:span});
          k += span;
        }
      }
    }
    out.forEach(sg=>{ if(sg.kind === 'phase' || sg.kind === 'phaseHiatus') sg.nPhases = nPhases; });
    return applyCellSpanOverrides(out, mc, slotMap, week, nPhases, spanCap);
  }

  // Lay the user's hand-dragged cell spans over the automatic layout.
  //
  // A claim may only take slots the automatic layout left EMPTY in this row, so it can never
  // hide a phase, a per-phase hiatus band, or an active Simultaneous Post marker -- those keep
  // their automatic footprint and the claim stops at the first slot it cannot have. A stale
  // override (the schedule moved under it) therefore shrinks to whatever is genuinely free
  // rather than being dropped outright or, worse, swallowing a neighbour.
  function applyCellSpanOverrides(segs, mc, slotMap, week, nPhases, spanCap){
    const weekIso = isoOf(week.date);
    const claim = new Map();   // segment index -> [from, to] in slot space
    const ownOf = new Map();   // segment index -> the phase's own slot
    const startOf = [];
    let s = 0;
    segs.forEach((seg, i)=>{ startOf[i] = s; s += seg.colspan; });
    segs.forEach((seg, i)=>{
      // A phase-hiatus band is claimable the same way a phase cell is (owner, 1 Sep 2026) --
      // both carry .cell/.own from computePhaseRowLayout() now, and share the same
      // weekIso+'|'+phaseKey cellSpans key a dragged phase cell already uses.
      if((seg.kind !== 'phase' && seg.kind !== 'phaseHiatus') || !seg.cell || seg.own === undefined) return;
      const ov = cellSpans[weekIso + '|' + seg.cell.key];
      if(!ov) return;
      // A width dragged out when the phase had the row to itself must not survive a phase moving
      // in beside it -- that is exactly the case where one cell ends up three columns wide and
      // its new neighbour one. The override records how many phases shared the row when it was
      // set; if that has changed since, it is held to the same even share the automatic layout
      // would give. Deliberately widening a cell while the overlap is on screen still wins,
      // because then the counts agree. (An override saved before this was recorded has no count
      // and is treated as stale, so old files rebalance rather than staying lopsided.)
      const cap = (ov.k === nPhases) ? mc : spanCap;
      let l = ov.l || 0, r = ov.r || 0;
      if(l + r + 1 > cap){
        // Trim the right edge first, then the left: a phase reads from its own column outward,
        // and pulling the right edge in keeps it flush with whatever sits to its left.
        r = Math.max(0, Math.min(r, cap - 1));
        l = Math.max(0, Math.min(l, cap - 1 - r));
      }
      ownOf.set(i, seg.own);
      claim.set(i, [Math.max(0, seg.own - l), Math.min(mc - 1, seg.own + r)]);
    });
    if(!claim.size) return segs;

    const taken = new Array(mc).fill(-1);
    // 1. Everything that isn't empty and isn't claiming keeps exactly what the auto layout gave it.
    segs.forEach((seg, i)=>{
      if(seg.kind === 'empty' || claim.has(i)) return;
      for(let n = startOf[i]; n < startOf[i] + seg.colspan; n++) taken[n] = i;
    });
    // 2. A claiming cell always keeps its own column (nothing else can own it -- it is the
    //    phase's slot), then 3. grows outward into free slots only, stopping at the first
    //    it cannot have so the result is always one contiguous cell.
    claim.forEach((_, i)=>{ taken[ownOf.get(i)] = i; });
    claim.forEach(([from, to], i)=>{
      const own = ownOf.get(i);
      for(let n = own - 1; n >= from; n--){ if(taken[n] !== -1) break; taken[n] = i; }
      for(let n = own + 1; n <= to;   n++){ if(taken[n] !== -1) break; taken[n] = i; }
    });

    const out = [];
    let k = 0;
    while(k < mc){
      const i = taken[k];
      let span = 1;
      while(k + span < mc && taken[k + span] === i) span++;
      out.push(i === -1 ? {kind:'empty', colspan:span}
                        : Object.assign({}, segs[i], {colspan:span}));
      k += span;
    }
    return out;
  }

  // Column widths for one schedule, in Excel column-width units, keyed by ROLE rather than by
  // absolute column index: a schedule change that alters maxConcurrent must not scramble
  // widths, and the three year-blocks are parallel views of the same structure so their Date
  // and Notes columns are linked (dragging one later should move all three).
  //
  // Consumed by renderSpreadsheetView (screen + the PDF, via <colgroup>) and by exportExcel.
  // Returns [{ date, labels:[...], notes }] -- one entry per year block.
  // How many table rows the grid actually needs.
  //
  // A table row is one row of EVERY year block at once, so the grid is as tall as the LONGEST
  // block. Years are not the same length -- 2029 has 53 Mondays because both Jan 1 and Dec 31
  // fall on one, while 2026-2028 have 52 -- so a 53-Monday year forces a final row that is
  // blank in every other block. When nothing is scheduled in that week either, the result is a
  // completely empty strip under the calendar.
  //
  // Trailing rows that are content-free in EVERY block are dropped. This deliberately does not
  // touch the full-year padding the layout is built around: a year whose work finishes in
  // September still shows its remaining weeks, because those rows carry content in some other
  // block. Only a row with nothing anywhere in it goes.
  function sheetRowCount(schedule, yearBlocks){
    let rows = Math.max(...yearBlocks.map(b=>b.count));
    const notesByIdx = schedule.notesByIdx || {};
    const hasContent = (b, r)=>{
      if(r >= b.count) return false;
      const i = b.startIdx + r;
      const w = schedule.weeks[i];
      if(!w) return false;
      if(w.cells && w.cells.length) return true;          // a phase, sim-post or hiatus band
      const wk = w.date.toISOString().slice(0,10);
      return !!effectiveNoteText(wk, autoNotesForView(notesByIdx[i], 'sheet'));
    };
    while(rows > 1 && !yearBlocks.some(b => hasContent(b, rows - 1))) rows--;
    return rows;
  }

  // Page geometry shared by the workbook and the PDF, in points.
  //
  // These live together because the orientation decision has to be made from IDENTICAL inputs in
  // both outputs. It very nearly was not: the workbook measured height as a flat rows*20px while
  // the PDF used its real per-row heights, and on a three-year calendar sitting right on the
  // 15% override boundary that 24px difference was enough to print the workbook landscape and
  // the PDF portrait. Height is deliberately the FLAT model here -- a note wrapping to a second
  // line should not be able to turn the page over.
  // Left/right and top are the workbook's Narrow preset (0.25in sides, 0.75in top), and the top
  // is load-bearing: the page header is drawn in the band between `hdr` and `t`.
  //
  // The BOTTOM is not. Excel reserves 0.75in there for a footer; this app draws none, and on a
  // landscape sheet the fit is usually height-bound, so that 54pt came straight off the size of
  // the calendar -- a near-square grid ended up 540pt wide on a 792pt page with 1.75in of white
  // down each side. Reclaiming it is the one free increase available.
  //
  // ⛔ HEADER: OFF RECLAIMS THE TOP (owner ruling 10 and its picker "Reclaim it", 20 Oct 2026;
  // HEADER-ROW-PLAN.md §2). With no page header there is nothing for the 54pt top or the 21.6pt
  // header band to hold, so the top becomes the sides' 18pt and the band 0. Getters, so the change is
  // in this DECLARATION and nothing that reads it is edited (sanctioned pattern 1): buildWaterfallPdf's
  // page box, sheetPageOrientation and Single Column's fill all read this one object, which is what
  // keeps the PDF and the workbook turning the page the same way. exportExcel writes the matching
  // 0.25in top itself. While headerOff is false each getter returns exactly the number it replaced.
  const SHEET_PAGE_MARGIN_PT = { l: 18, r: 18, get t(){ return headerOff ? 18 : 54; }, b: 18,
                                 get hdr(){ return headerOff ? 0 : 21.6; }, ftr: 0 };
  // ⛔ THE PAPER (owner, 21 Oct 2026; PAPER-SIZE-PLAN.md, rulings R1-R4): Letter, Legal or Tabloid, for the
  // waterfall PDF and the workbook. The month PDF stays Letter (R4), and so do both print rollbacks.
  //  - ⛔ CALENDAR DATA (R2, "With the calendar"): captureSnapshot()'s `paperSize`, 'legal' | 'tabloid'.
  //    LETTER IS AN ABSENT KEY ('' here), so a calendar left on Letter saves byte for byte as before.
  //    The key and its two values are permanent from the first file saved with them.
  //  - `xl` is Excel's paper number (ECMA-376 pageSetup@paperSize). Tabloid is 3, NOT Ledger's 4: 4 is the
  //    same sheet already turned, and orientation is set on its own.
  //  - `paperProbe` lets the Export PDF dialog ask the frozen page-turn rule about a paper that is not
  //    chosen yet (pageFitFor). It is set and cleared inside ONE synchronous call, so no render can see it.
  const SHEET_PAPERS = {
    letter:  { w: 612, h: 792,  xl: 1, label: 'Letter',  size: '8.5 × 11' },
    legal:   { w: 612, h: 1008, xl: 5, label: 'Legal',   size: '8.5 × 14' },
    tabloid: { w: 792, h: 1224, xl: 3, label: 'Tabloid', size: '11 × 17' }
  };
  // (`paperSize` itself is declared beside `dateFormat`, near the top of the IIFE: the sidebar's boot code
  // reflects it long before this line runs, and a `let` read there would throw from the temporal dead zone.)
  let paperProbe = null;
  function sheetPaper(){ return SHEET_PAPERS[paperProbe || paperSize || 'letter'] || SHEET_PAPERS.letter; }
  // Read by frozen exportExcel's pageSetup (FROZEN EDIT P2): 1 while the paper is Letter, as it always wrote.
  function sheetPaperCode(){ return sheetPaper().xl; }
  // ⛔ FROZEN EDIT P1, a DECLARATION change only (sanctioned pattern 1, the move Header: Off made on
  // SHEET_PAGE_MARGIN_PT just above): the two orientations are getters over the chosen paper. buildWaterfallPdf's
  // page box and fit, sheetPageOrientation and Single Column's fill all read this one object, so the PDF and the
  // workbook still turn the page the same way, and Single Column follows the paper (R3). While the paper is
  // Letter each getter returns exactly the {612, 792} / {792, 612} it replaced.
  const SHEET_PAPER_PT = {
    get portrait(){ const p = sheetPaper(); return { w: p.w, h: p.h }; },
    get landscape(){ const p = sheetPaper(); return { w: p.h, h: p.w }; }
  };
  // ⛔ THE CHOSEN ORIENTATION (the Export PDF dialog, ruling D1 "With the calendar"): captureSnapshot()'s
  // `pageOrientation`, 'portrait' | 'landscape', written ONLY when it differs from what sheetPageOrientation
  // recommends; exporting with the recommended one selected clears it, so a calendar never overridden keeps
  // following the rule as it grows. An ABSENT key ('' here) is "follow the rule".
  // ⛔ FROZEN EDIT P4: both writers pass the rule's answer through this, buildWaterfallPdf and exportExcel
  // alike, so they still cannot turn differently. With nothing chosen it returns the rule's answer untouched.
  const PAGE_ORIENTATIONS = ['portrait', 'landscape'];
  function chosenOrientation(auto){ return PAGE_ORIENTATIONS.includes(pageOrientation) ? pageOrientation : auto; }

  function sheetGridMetrics(schedule, yearBlocks, colWidthsFor){
    const rows = sheetRowCount(schedule, yearBlocks);
    let gridW = 0;
    colWidthsFor.forEach(b => b.cols.forEach(c => { gridW += charsToScreenPx(c.chars); }));
    return { rows, gridW, gridH: (rows + 1) * ROW_DEFAULT_PX * ROW_PX_TO_PT };
  }

  // Landscape from three year-blocks, unless the other way round prints meaningfully larger --
  // the rule the Excel export has always used, now the only copy of it.
  function sheetPageOrientation(gridW, gridH, blockCount){
    const M = SHEET_PAGE_MARGIN_PT;
    const fit = p => Math.min((p.w - M.l - M.r) / gridW,
                              (p.h - M.t - M.b - M.hdr - M.ftr) / gridH);
    const portrait = fit(SHEET_PAPER_PT.portrait), landscape = fit(SHEET_PAPER_PT.landscape);
    const preferred = blockCount >= 3 ? 'landscape' : 'portrait';
    const pref  = preferred === 'landscape' ? landscape : portrait;
    const other = preferred === 'landscape' ? portrait : landscape;
    const orientation = (other > pref * 1.15)
      ? (preferred === 'landscape' ? 'portrait' : 'landscape') : preferred;
    return { orientation, portrait, landscape, preferred };
  }

  function sheetColumnWidths(schedule, yearBlocks, layout){
    const { blockSlotMaps, blockMaxConcurrent, blockOccupancy, blockSimSlot } = layout;
    const notesByIdx = schedule.notesByIdx || {};
    // Measured PER BLOCK, including the date and notes columns. They used to share one width
    // across all blocks, which meant dragging one year's Date column silently resized every
    // other year's too -- surprising, and unlike Excel, where every column is its own thing.
    const maxByBlock = [];

    yearBlocks.forEach((b, bi)=>{
      const mc = blockMaxConcurrent[bi];
      const labelMax = new Array(mc).fill(0);
      const spans = [];
      let dateMax = 0, notesMax = 0;
      for(let i=b.startIdx; i<b.startIdx+b.count; i++){
        const week = schedule.weeks[i];
        // Date cells are bold, so they measure wider than the same digits in the body font.
        // ⛔ FROZEN EDIT (owner-approved 20 Oct 2026, ruling 4): measured in the calendar's date format,
        // so 1/6/2025 widens the column through this model rather than clipping. fmtShort() by default.
        dateMax = Math.max(dateMax, measureTextPx(fmtWeekDate(week.date), true));
        if(week.cells.length && week.cells[0].type==='hiatus') continue;   // spans the block
        const rows = computePhaseRowLayout(week, mc, blockSlotMaps[bi], blockOccupancy[bi],
                                           i - b.startIdx, blockSimSlot[bi]);
        let slot = 0;
        rows.forEach(cell=>{
          // A single-slot cell charges its whole label to its own column. A SPANNED cell is
          // deferred to a second pass: charging its label to the starting column would inflate
          // that column for every other row in the block, but ignoring it entirely (as the
          // first version of this did) left a block whose every row is one lone spanning phase
          // with nothing but minimum-width columns.
          if(cell.kind==='phase' || cell.kind==='simpost'){
            const px = measureTextPx(cell.label, false);
            if(cell.colspan === 1) labelMax[slot] = Math.max(labelMax[slot], px);
            else spans.push({ slot, colspan: cell.colspan, px });
          }
          slot += cell.colspan;
        });
        const wk = week.date.toISOString().slice(0,10);
        const noteText = effectiveNoteText(wk, autoNotesForView(notesByIdx[i], 'sheet'));
        if(noteText) noteText.split('\n').forEach(line=>{
          notesMax = Math.max(notesMax, measureTextPx(line, false));
        });
      }
      // Second pass: a spanned label only needs the columns it covers to ADD UP to its width,
      // so top up the shortfall evenly rather than pushing any one column out on its own.
      spans.forEach(({slot, colspan, px})=>{
        let have = 0;
        for(let k=slot; k<slot+colspan; k++) have += labelMax[k] || 0;
        if(have < px){
          const add = (px - have) / colspan;
          for(let k=slot; k<slot+colspan; k++) labelMax[k] = (labelMax[k] || 0) + add;
        }
      });
      maxByBlock.push({ labelMax, dateMax, notesMax });
    });

    // 8.43 is Excel's default column width and what the reference export uses for its date
    // column; measured need is a little under that, so it acts as the floor.
    // A hand-dragged override wins over the measurement outright -- that is the whole point of
    // dragging -- and double-clicking the handle deletes the override to get autofit back.
    const pick = (k, auto) => (colWidths[k] !== undefined ? colWidths[k] : auto);
    const out = yearBlocks.map((b, bi)=>{
      const m = maxByBlock[bi];
      const kd = 'y' + b.year + ':date';
      const kn = 'y' + b.year + ':notes';
      const date  = pick(kd, clampChars(pxToChars(m.dateMax), 8.43));
      const notes = pick(kn, clampChars(pxToChars(m.notesMax), 8, COL_MAX_CHARS_NOTES));
      // Phase columns within a block are all the SAME width. Two phases running side by side
      // each get one column, and columns that differ by 15% make an even split look like a
      // mistake -- so the block's phase columns are sized together, to whatever the widest of
      // them needs. A hand-dragged width still overrides its own column outright.
      const slotAuto = clampChars(pxToChars(Math.max(0, ...m.labelMax)), 8);
      const labels = m.labelMax.map((px, s)=> pick('y' + b.year + ':s' + s, slotAuto));
      // `cols` is the flat left-to-right list the renderer and the drag handles both walk, so
      // neither has to re-derive which key belongs to which column.
      const cols = [{ key:kd, chars:date }]
        .concat(labels.map((c, s)=>({ key:'y' + b.year + ':s' + s, chars:c })))
        .concat([{ key:kn, chars:notes }]);
      return { date, labels, notes, cols };
    });

    // ⛔ FROZEN EDIT W1 (owner sign-off, 22 Oct 2026, HIDE-NOTES-PLAN.md §6): a hidden Notes column leaves
    // `cols`, so everything that walks `cols` -- the screen's <colgroup>, the grid metrics and with them the
    // page orientation and the PDF's fit, the PDF's columns and frame, the side boxes, the custom heading
    // runs -- loses it at once. `notes` keeps its measured width: Excel keeps the column, hidden (E1), so
    // unhiding it there brings the width back. Runs BEFORE the single-column post-pass, which then fills the
    // page with the columns that are left. Skipped outright with nothing hidden.
    if(Object.keys(hiddenNotesCols).length){
      out.forEach((bk, bi)=>{
        if(!notesHiddenFor(yearBlocks[bi].year)) return;
        bk.cols = bk.cols.slice(0, -1);
        bk.notesHidden = true;
      });
    }

    // ⭐ SINGLE-COLUMN MODE: GROW THE COLUMNS TO FILL THE PAGE WIDTH (owner, 10 Sep 2026: "how
    // would you make adjustments such that the collumn fills the vertical page as shown in the
    // example").
    //
    // ⛔ FROZEN EDIT, and it is a post-pass on purpose -- everything above is untouched and this
    // cannot run at all while singleColumn is false, so every other calendar gets byte-identical
    // widths. The PDF/Excel byte-compare is the proof, not this comment.
    //
    // THE PROBLEM IT SOLVES. One column is tall and narrow, so BOTH writers -- which fit the whole
    // grid onto one page -- end up HEIGHT-constrained. Measured on the owner's reference: the grid
    // is 416 x 810pt against a printable 576 x 698, so the scale is 698/810 = 0.86 and the grid
    // prints 416*0.86 = 358pt wide, leaving 38% of the page empty at the sides. It already filled
    // the page vertically; it was the width that was wasted.
    //
    // THE FACTOR. At a height-bound scale the grid fills the width when
    // gridW' = availW / scale = availW * gridH / availH, so f = (availW*gridH)/(availH*gridW).
    // ⚠️ gridH does NOT depend on column widths -- sheetGridMetrics computes it from the row COUNT
    // -- so there is no feedback loop and one pass is exact.
    if(singleColumn){
      const M = SHEET_PAGE_MARGIN_PT, PP = SHEET_PAPER_PT.portrait;
      const availW = PP.w - M.l - M.r, availH = PP.h - M.t - M.b - M.hdr - M.ftr;
      const rows = sheetRowCount(schedule, yearBlocks);
      const gridH = (rows + 1) * ROW_DEFAULT_PX * ROW_PX_TO_PT;
      let gridW = 0;
      out.forEach(bk => bk.cols.forEach(c => { gridW += charsToScreenPx(c.chars); }));
      // ⚠️ Portrait deliberately: with one block sheetPageOrientation prefers portrait and only
      // flips if landscape prints 15% larger, which a tall narrow grid never does. Sizing against
      // the orientation that will actually be chosen keeps this one pass rather than two.
      let f = (gridW > 0 && gridH > 0) ? (availW * gridH) / (availH * gridW) : 1;
      // ⛔ FROZEN EDIT (L-2, 29 Sep 2026): cap f so the widest AUTO column stops at Excel's 255
      // characters. gridH grows with the row count, so a long calendar sent f -- and every column --
      // far past the limit (the audit measured 370.4 on ~5 years). Capping the FACTOR, not each column,
      // keeps the columns' proportions; the grid then simply stops filling the page's width.
      let widestAuto = 0;
      out.forEach(bk => bk.cols.forEach(c => { if(colWidths[c.key] === undefined) widestAuto = Math.max(widestAuto, c.chars); }));
      if(widestAuto > 0) f = Math.min(f, EXCEL_MAX_COL_CHARS / widestAuto);
      // ⚠️ Only GROW, and only when it is worth doing: f <= 1 means the grid is already
      // width-bound, and shrinking it here would fight the fit that is about to happen anyway.
      if(f > 1.02){
        out.forEach(bk => {
          // ⛔ A hand-dragged column keeps EXACTLY the width it was dropped at. Stretching it too
          // would move the user's own drag out from under them, and there would be no way to set
          // a width that stayed set. The auto columns take up the remaining slack instead.
          const grow = (k, v) => (colWidths[k] === undefined ? v * f : v);
          bk.cols.forEach(c => { c.chars = grow(c.key, c.chars); });
          // The three named fields are a SECOND view of the same numbers -- exportExcel reads
          // widths.labels/notes while the renderer walks cols -- so they have to move together or
          // the workbook and the screen disagree about the same column.
          bk.date  = bk.cols[0].chars;
          // ⛔ FROZEN EDIT W2 (owner sign-off, 22 Oct 2026, HIDE-NOTES-PLAN.md §6): with its Notes column
          // hidden (W1) the block's last column is a phase column, so it is a label and `notes` stays the
          // measured width. Without `notesHidden` these are the two lines that always ran.
          if(bk.notesHidden){
            bk.labels = bk.cols.slice(1).map(c => c.chars);
          } else {
          bk.notes = bk.cols[bk.cols.length - 1].chars;
          bk.labels = bk.cols.slice(1, -1).map(c => c.chars);
          }
        });
      }
    }
    return out;
  }
  // ⛔ The two colour getters are what the frozen renderers read for style="background:${…}", so a
  // colour that is not #rrggbb falls back to the default here, whatever put it in the store (H-1).
  function noteColorFor(weekKey){ const c = noteColors[weekKey]; return isHexColor(c) ? c : MILESTONE_COLOR; }
  // undefined means "auto" -- the caller falls back to fitting the text to the row's line budget.
  function noteFontSizeFor(weekKey){ return noteFontSize[weekKey]; }
  function hiatusFontSizeFor(weekKey){ return hiatusFontSize[weekKey]; }
  function hiatusTextFor(weekKey){ return (weekKey in hiatusTexts) ? hiatusTexts[weekKey] : HIATUS_DEFAULT_LABEL; }
  function hiatusColorFor(weekKey){ const c = hiatusColors[weekKey]; return isHexColor(c) ? c : HIATUS_COLOR; }

  // True if the user has made ANY manual edit to comments/holidays/hiatus (edited text,
  // cleared a note, or changed a highlight color / hiatus label). It decides whether a Region or
  // holiday change ASKS FIRST (countryChangeWouldClobber). It used to decide the Region LOCK, which
  // owner ruling 6 (relayed 30 Sep 2026) replaced with that question -- this predicate, day notes
  // included, is unchanged, so 4.7's L-23 fix stands.
  function hasNoteEdits(){
    return Object.keys(userNotes).length > 0
      || Object.keys(noteColors).length > 0
      || Object.keys(hiatusTexts).length > 0
      || Object.keys(hiatusColors).length > 0
      // ⛔ AUDIT L-23: month-view DAY notes too. They sit on absolute days exactly as waterfall
      // notes sit on weeks, so a Region change that re-skips a different country's holidays moves
      // Production out from under them: measured, a note on the wrap day was left one day off when
      // the Region went to London (wrap 10/20 -> 10/19). A day counts only while it still holds a
      // note with text -- a key a delete left behind must not make a Region change ask.
      || Object.keys(dayNotes).some(iso => dayNoteList(iso).some(nt => nt && String(nt.text || '').trim()));
  }

  // Changing the shooting country only moves DATES when Production is actually scheduled --
  // holidays are skipped shoot days, so with no shoot there's nothing to shift. When Production
  // isn't scheduled a country switch merely swaps which (unanchored) holiday auto-notes show,
  // and every manual edit is keyed to an absolute week that doesn't move -- so it's safe to allow
  // the switch freely. We only ask when a switch could genuinely misplace edits: there are manual
  // edits AND Production is scheduled (so its dates could recompute under them).
  function productionIsScheduled(){
    const startEl = document.getElementById('start-production');
    return !!(startEl && startEl.value) && showInfoStatus().complete;
  }
  function countryChangeWouldClobber(){
    return hasNoteEdits() && productionIsScheduled();
  }
  // Anything that changes WHICH HOLIDAYS APPLY moves Production when a note could be misplaced, and
  // asks this one question first: resolves true to go ahead. ONE function, so the checkbox, the bulk
  // toggle and the custom-holiday Add button cannot drift apart -- the Add button never asked at all
  // (audit L-23), which is how a duplicated copy of this rule goes missing.
  async function confirmHolidayRecompute(){
    if(!countryChangeWouldClobber()) return true;
    return !!(await uiConfirm('Changing which holidays apply recomputes Production\u2019s dates, which can misplace the comment/hiatus edits you\u2019ve made.\n\nContinue?', { title: 'Recompute the schedule?' }));
  }
  // The same warning for the two holiday actions that already ask a question of their OWN -- owner
  // ruling 7 (relayed 30 Sep 2026) and the picker that settled its shape the same day: ONE dialog.
  // Removing a custom holiday and "Reset holidays" change which holidays apply exactly as the Enable
  // checkbox does, so they warn under the same rule (countryChangeWouldClobber) -- as a sentence
  // inside their own confirm, never as a second dialog after it. '' when nothing can be misplaced,
  // which leaves each confirm exactly as it read before.
  function holidayRecomputeSentence(lead){
    return countryChangeWouldClobber()
      ? '\n\n' + lead + ' recomputes Production\u2019s dates, which can misplace the comment/hiatus edits you\u2019ve made.'
      : '';
  }
  // The Region's version of the same question -- owner ruling 6 (relayed 30 Sep 2026; built after
  // v1.4.1), which replaced the Region LOCK with it. The lock refused the change until "Reset Notes
  // & Hiatus" had wiped every note, although only notes and note colours can be misplaced: hiatus
  // bands sit on absolute dates the Region never moves. Same predicate, same title and buttons as
  // confirmHolidayRecompute(), so the two questions cannot drift apart. Resolves true to go ahead.
  async function confirmRegionChange(){
    if(!countryChangeWouldClobber()) return true;
    return !!(await uiConfirm('Changing the Production Region recomputes Production\u2019s dates (its shoot skips that region\u2019s holidays), which can misplace the comment/hiatus edits you\u2019ve made.\n\nContinue?', { title: 'Recompute the schedule?' }));
  }

  // Per-line header overrides. Keys: left, c1 (title), c2 ("Planning Calendar"),
  // Header mode: 'auto' (lines mirror the inputs, not editable) or 'manual' (a snapshot of
  // the auto values that the user can freely edit; stops auto-updating). headerManual holds
  // the seven editable lines when in manual mode.
  let headerMode = 'auto';
  let headerManual = {}; // { left, c1, c2, c3, r1, r2, r3 }
  // ⛔ THE THIRD MODE, AND WHY IT IS A FLAG RATHER THAN A THIRD VALUE OF headerMode (decision H3).
  // Frozen renderSpreadsheetView gates editability and the format toolbar on
  // `const manual = headerMode === 'manual'`. That gate is NOT edited, so headerMode keeps its two
  // values -- on disk and in memory -- and Template mode is `manual` PLUS this flag. A `let` the
  // frozen function can read at call time is the pattern CLAUDE.md sanctions ("change the
  // DECLARATION, not the call sites"), and it is what SHEET_GRIDLINES already does.
  //
  // headerManual holds RAW TEMPLATES while this is true and LITERAL TEXT while it is false. One
  // store, one flag. headerLine() resolves only when it is true, so Manual behaves byte-for-byte as
  // it always has -- a legacy manual header containing "{today}" prints {today}, because no file
  // written before this feature carries the flag.
  //
  // ⛔ Do not turn this into a const, do not copy it into a local at load, and do not let the frozen
  // `manual` gate read it. The one authorised frozen edit (H3b) is the mode button's label
  // expression and nothing else.
  let headerTemplates = false;
  // ⛔ HEADER: OFF (owner ruling 10, 20 Oct 2026; HEADER-ROW-PLAN.md §2): no title block on screen,
  // in Excel or in the waterfall PDF. A FLAG ON TOP of the mode, for the same reason headerTemplates
  // is one (H3): the frozen renderer's `manual` gate keeps its two values. Off hides whatever mode is
  // underneath without touching it, so choosing Manual or Template again brings back the lines you had.
  //   * headerLine() returns '' while it is set -- the one choke point all three outputs read, so the
  //     PDF writer's `if(hdrLines)` draws nothing with no edit inside it (sanctioned pattern 1).
  //   * SHEET_PAGE_MARGIN_PT's top and header margins read it (owner's picker, "Reclaim it"): the grid
  //     starts 18pt down like the sides, and sheetPageOrientation turns both outputs the same way.
  //   * the screen and the print fallback hide .cal-header-bar off a <body> class (reflectHeaderOff).
  // ⛔ CALENDAR DATA: captureSnapshot()'s `headerOff`, written only as `true`, so a calendar that never
  // turns it off saves byte for byte as before. The month view's header has no Off (the ruling names
  // the waterfall).
  let headerOff = false;
  // The month view has its own header with its own auto/manual switch. It's deliberately
  // INDEPENDENT of the waterfall header above: the two documents are printed separately and
  // often want different wording, so taking one manual never touches the other.
  let mvHeaderMode = 'auto';
  let mvHeaderManual = {}; // { tleft, title, subtitle, today }
  // ⛔ THE MONTH'S THIRD MODE, AND IT IS A FLAG FOR THE SAME REASON headerTemplates IS ONE (H3).
  // Frozen renderMonthView gates editability on `const mvManual = mvHeaderMode === 'manual'`. That
  // gate keeps its two values -- on disk and in memory -- and Template mode is `manual` PLUS this
  // flag, so no calendar saved before this feature can reach the new branch and Manual behaves
  // byte-for-byte as it always has. A legacy month header containing "{today}" still prints the
  // literal {today}, because no file written before today carries the flag.
  //
  // mvHeaderManual holds RAW TEMPLATES while this is true and LITERAL TEXT while it is false.
  // One store, one flag. mvHeaderLine() resolves only when it is true.
  let mvHeaderTemplates = false;

  // ---------- Header text formatting (owner, 31 Aug 2026) ----------
  // Per-LINE formatting, not per-character. Each header line is already its own element, and --
  // the reason it has to be per line -- Excel's header/footer string and the PDF writer both
  // format per SECTION, not per run of characters. Storing inline markup would produce a screen
  // that the two exports could not reproduce, which for a tool whose product IS the export is a
  // defect rather than a limitation.
  //
  // Shape: headerFormat[id] = { size, bold, italic, color, highlight, align }
  //   size      number, pt-ish screen px at 1x (absent = the line's stylesheet default)
  //   bold      bool        italic bool
  //   color     '#rrggbb'   highlight '#rrggbb'
  //   align     'left'|'center'|'right'
  // Every key is OPTIONAL and absent means "inherit the default" -- so an untouched calendar
  // serialises `{}` and renders exactly as it did before this feature existed.
  let headerFormat = {};    // waterfall, keyed by hid  (left, l2, c1..c4, r1..r3)
  let mvHeaderFormat = {};  // month view, keyed by mvhid (title, today)

  // The nine waterfall header lines, in visual order per column. l2 and c4 are the two added
  // 31 Aug 2026 ("middle left" and "middle bottom"); they default to EMPTY and are hidden unless
  // manual mode is on, so auto mode renders byte-identically to before.
  // ⚠️ ORDER IS NOT COSMETIC: this is the order the slots are written and read in, and l3 is
  // appended to the LEFT group rather than to the end of the array so the list still reads
  // column-by-column. Nothing keys off the index -- headerManual and headerFormat are keyed by id --
  // but a reader who assumes the array is grouped should stay right.
  const HDR_IDS = ['left','l2','l3','c1','c2','c3','c4','r1','r2','r3'];
  // Slots that carry no auto value and are hidden when empty. l2 and c4 arrived 31 Aug 2026; l3
  // arrived 9 Sep 2026 (owner: "left, centre, and right should have 3 each"), by the same argument
  // and with the same guarantee -- empty by default, so every calendar ever saved renders unchanged.
  const HDR_NEW_SLOTS = ['l2','l3','c4'];

  // The built-in Default preset: the auto header, written as templates. It is what Auto -> Template
  // seeds from, and (Step 4) the read-only first entry in the preset list.
  //
  // ⚠️ IT IS A SECOND STATEMENT OF THE AUTO HEADER AND THE TWO CAN DRIFT. computeHeaderDefaults()
  // stays hand-coded -- its strings are the byte-identical baseline the gate compares against -- so
  // this is a duplicate guarded by a test rather than a single source. The `hdrdefault` assertion in
  // the hdrtemplate leg resolves all nine of these against the live calendar and requires them to
  // equal computeHeaderDefaults() exactly, byte for byte, on a calendar with data and on an empty
  // one. ⛔ Do not "simplify" by making Auto read this template: Auto's hand-coded strings are what
  // every existing calendar renders, and routing them through the resolver puts the byte-identical
  // baseline at risk for no user-visible gain.
  //
  // Note r3: `[{episodes} Episodes]` rather than `{episodes} Episodes`. The auto r3 is EMPTY when
  // there is no episode count, and only the conditional group reproduces that -- without the
  // brackets an empty count would render the bare word "Episodes".
  const DEFAULT_HEADER_TEMPLATE = {
    left: '{today}',      l2: '{version}',        l3: '',
    c1:   '{titleSeason}', c2: 'Planning Calendar', c3: '{writersRoom.line}', c4: '',
    r1:   '{production.summary}', r2: '{production.dates}', r3: '[{episodes} Episodes]',
  };


  // ---------- The month header's slots (MONTH-HEADER-PLAN.md, owner rulings 21 Sep 2026) ----------
  //
  // The month header was two slots and a toggle. It is now four slots and the same three modes the
  // waterfall has, sharing ONE resolver and ONE token catalogue -- separate stores, shared grammar.
  //
  // ⚠️ ORDER IS VISUAL, left to right, with `subtitle` under `title`. Nothing keys off the index
  // (mvHeaderManual and mvHeaderFormat are keyed by id) but a reader should stay right.
  const MV_HDR_IDS = ['tleft','title','subtitle','today'];
  // Slots added 21 Sep 2026. ⛔ ONLY `subtitle` is an MV_NEW_SLOT, and leaving `tleft` OUT of this
  // list is load-bearing rather than an oversight. .hdr-slot.hdr-empty is display:none, and the
  // LEFT slot replaces `.mv-titlebar::before` -- an 84px blank box that exists to balance the date
  // so the title reads centred. Hiding it when empty would collapse that reservation and shift the
  // title in EVERY month PDF ever printed. .mv-tleft therefore keeps its box whether or not it has
  // text, which is exactly why the left slot costs no height: it fills space already reserved.
  // `subtitle` is a real new LINE, so it hides when empty and costs height only when someone fills
  // it -- the same guarantee l2/l3/c4 give the waterfall.
  const MV_NEW_SLOTS = ['subtitle'];
  const MV_HDR_SLOT_NAMES = {
    tleft: 'Top left', title: 'Title', subtitle: 'Subtitle', today: 'Date (top right)',
  };
  // The built-in month Default, written as templates. What Auto -> Template seeds from.
  //
  // ⚠️ IT IS A SECOND STATEMENT OF computeMvHeaderDefaults() AND THE TWO CAN DRIFT -- the same
  // deliberate duplication DEFAULT_HEADER_TEMPLATE carries, guarded the same way: the `mvhdrdefault`
  // assertion resolves these against a live calendar and requires them to equal
  // computeMvHeaderDefaults() byte for byte, on a calendar with data and on an empty one.
  //
  // Note `[{titleSeason} ]` rather than `{titleSeason} `: the auto title is "Full Prelim Production
  // Calendar" with NO leading space when there is no show title, and only the conditional group
  // reproduces that -- the group collapses its literal text and the space inside the brackets along
  // with the empty token. Same reason r3 is written `[{episodes} Episodes]`.
  //
  // ⛔ `{today:dotpad}`, NOT `{today}`. They are not the same string. {today} renders M.D.YY and the
  // month header has always rendered M.DD.YY -- they agree on 279 days a year and DIFFER on the
  // other 121 (every 1st to 9th). Verified by enumerating 400 consecutive days, not by looking at
  // one. Using {today} here would have silently changed the printed date on a third of the days in
  // the year, and would have passed a same-day browser check.
  const DEFAULT_MV_TEMPLATE = {
    tleft: '', title: '[{titleSeason} ]Full Prelim Production Calendar',
    subtitle: '', today: '{today:dotpad}',
  };

  // The month header's auto values -- the ONE definition of what it says by default.
  //
  // ⭐ THIS DELETES A LIVE DUPLICATION. These two strings were built in frozen renderMonthView AND
  // rebuilt verbatim in the #mv-hdr-mode-btn handler so that switching to Manual could snapshot
  // them. Two copies of one rule, one of them frozen and therefore unfixable if they drifted. Both
  // call this now.
  //
  // ⚠️ __ctx is attached ONLY when templates are on, and that is a cost decision, not tidiness:
  // exportMonthPdf calls renderMonthView once per month (15 times on the reference fixture), and
  // buildHeaderCtx walks every phase and reads the DOM. With the flag off the print path pays
  // exactly what it paid before this feature existed.
  function computeMvHeaderDefaults(schedule){
    const rawTitle = (document.getElementById('show-title').value || '').trim();
    const seasonVal = (document.getElementById('season-num').value || '').trim();
    const t = rawTitle + (seasonVal ? (rawTitle ? ' ' : '') + 'S' + seasonVal : '');
    // LOCAL date, not UTC: this is "today" for the person reading it, unlike the schedule dates.
    const now = new Date();
    const out = {
      tleft: '',
      title: (t ? t + ' ' : '') + 'Full Prelim Production Calendar',
      subtitle: '',
      today: (now.getMonth()+1) + '.' + String(now.getDate()).padStart(2,'0')
             + '.' + String(now.getFullYear()).slice(2),
    };
    // Non-enumerable so it cannot reach a saved file, an Object.assign or the undo stack -- the
    // same guard computeHeaderDefaults() uses and for the same reason.
    if(mvHeaderTemplates){
      Object.defineProperty(out, '__ctx', { value: buildHeaderCtx(schedule), enumerable: false });
    }
    return out;
  }

  // Effective text for one month header line. The month's twin of headerLine(), and the choke point
  // the whole feature hangs off: frozen renderMonthView calls it, so resolving HERE is what keeps
  // the screen and the month PDF unable to disagree.
  //
  // ⛔ Byte-for-byte what the old inline expression returned while mvHeaderTemplates is false --
  // including the `=== undefined` test rather than `in`, which is what the frozen code used to do.
  function mvHeaderLine(id, defaults){
    const d = (defaults && defaults[id]) || '';
    if(mvHeaderMode !== 'manual') return d;
    if(mvHeaderManual[id] === undefined) return d;
    const raw = mvHeaderManual[id];
    return mvHeaderTemplates ? resolveHeaderTemplate(raw, defaults && defaults.__ctx) : raw;
  }

  function headerFmt(id, mv){ return (mv ? mvHeaderFormat : headerFormat)[id] || {}; }

  // Which way a line sits when it has no explicit align -- i.e. what its column already does.
  // Needed because a highlight makes the line shrink to its text (see headerFormatCss), and a
  // shrunk block has to be re-positioned by margins or it jumps to the left of its column.
  function headerDefaultAlign(id, mv){
    if(mv) return id === 'today' ? 'right' : 'center';
    if(id === 'left' || id === 'l2' || id === 'l3') return 'left';
    if(id[0] === 'r') return 'right';
    return 'center';
  }

  // Format -> inline CSS, for the two on-screen renderers.
  function headerFormatCss(f, id, mv){
    if(!f) return '';
    const out = [];
    // ⛔ Every value below is interpolated into style="…" by the frozen renderers, so each one is
    // checked HERE, at the one place they all pass through (audit H-1). A header format can come
    // from a file (sanitizeSnapshot), from a .spthdr preset, or from a preset stored in this
    // browser before these checks existed -- this line covers all three. For every value the
    // toolbar can produce the output is unchanged.
    const sizeN = finiteNum(f.size);
    const color = isHexColor(f.color) ? f.color : '';
    const highlight = isHexColor(f.highlight) ? f.highlight : '';
    const align = (f.align === 'left' || f.align === 'center' || f.align === 'right') ? f.align : '';
    if(sizeN && sizeN > 0 && sizeN <= 400) out.push('font-size:' + sizeN + 'px');
    // Tri-state on purpose: undefined = inherit the stylesheet, true = force on, false = force
    // OFF. The title line is font-weight:700 by DEFAULT (.hdr-line.hdr-title), so without an
    // explicit 400 the Bold button could never un-bold it -- it looked broken because nothing
    // visibly changed either way (owner, 31 Aug 2026).
    if(f.bold === true)        out.push('font-weight:700');
    else if(f.bold === false)  out.push('font-weight:400');
    if(f.italic === true)      out.push('font-style:italic');
    else if(f.italic === false) out.push('font-style:normal');
    if(color)       out.push('color:' + color);
    if(align)       out.push('text-align:' + align);
    if(highlight){
      out.push('background-color:' + highlight);
      // The highlight must cover the TEXT, not the whole column (owner, 31 Aug 2026). .hdr-line is
      // a block filling its column, so a background on it painted a full-width band. Shrinking to
      // the text and re-positioning with auto margins keeps the line where its column puts it
      // while the background hugs what was typed -- and it tracks the text as it is edited,
      // because fit-content is recomputed on every keystroke.
      // Only applied WITH a highlight: without one, a full-width line is the bigger click target
      // for putting the caret in, and that is worth keeping.
      const al = align || headerDefaultAlign(id, mv);
      out.push('width:fit-content');
      out.push('padding-left:4px', 'padding-right:4px');
      if(al === 'center') out.push('margin-left:auto', 'margin-right:auto');
      else if(al === 'right') out.push('margin-left:auto');
      else out.push('margin-right:auto');
    }
    return out.join(';') + (out.length ? ';' : '');
  }

  // Format -> Excel header/footer control codes, prefixed to the line's text.
  // ⚠️ These cost characters against Excel's 255-CHARACTER TOTAL for the whole header string --
  // the limit that makes Excel report the file as corrupt when exceeded (see exportExcel's
  // HF_MAX). A colour alone is 9 characters. exportExcel's existing trimmer still runs after
  // this, so a formatted header degrades by dropping trailing LINES exactly as an unformatted
  // long one does -- it does not silently truncate mid-code.
  // ⚠️ HIGHLIGHT IS DELIBERATELY ABSENT: an Excel header/footer has no text-background code at
  // all. It applies on screen and in the PDF and cannot apply here; that gap is documented in
  // README rather than faked.

  // The header formatting toolbar. Shown only in manual mode -- in auto mode the lines mirror the
  // inputs and are not editable, so formatting controls would be offering something that cannot
  // be done.
  //
  // ⛔ NOT ONE CONTROL IN HERE HAS AN id. collectFieldValues() sweeps every input[id]/select[id]/
  // textarea[id] in the document into saved files AND into the undo stack, so an id here would
  // bake the toolbar's own transient position into every calendar and add phantom undo steps.
  // Classes only -- the same reason the note editor's day/size selects use classes.

  // ---------- Header formatting: behaviour ----------
  // Delegated on #table-wrap, so it survives every render() rebuild without re-binding -- the
  // toolbar and the header lines are both destroyed and recreated on each one.
  //
  // The toolbar acts on the LAST-FOCUSED header line, not the currently-focused one: clicking a
  // toolbar button necessarily blurs the contenteditable, so "currently focused" is always the
  // button by the time the handler runs.
  let hdrFmtTarget = null;   // { id, mv } or null

  // A press inside the formatting toolbar, recorded in the CAPTURE phase so it is known before the
  // edited line's blur runs: a colour well is a <label> around an <input type=color>, and the blur it
  // causes carries no relatedTarget, so relatedTarget alone cannot tell "going to the toolbar".
  // Cleared a tick after release, so it cannot leak into a later keyboard-driven blur.
  let hdrFmtPressing = false;
  // A header-text render the waterfall line's blur deferred, because focus was going to a toolbar
  // control and a render would have detached it (see that handler).
  let hdrRenderPending = false;
  document.addEventListener('pointerdown', e=>{
    hdrFmtPressing = !!(e.target && e.target.closest && e.target.closest('.hdr-fmt'));
  }, true);
  document.addEventListener('pointerup', ()=>{ setTimeout(()=>{ hdrFmtPressing = false; }, 0); }, true);
  // The deferred render runs once focus leaves the toolbar for anywhere but another toolbar control
  // or a header line -- the same moment a plain line-to-elsewhere blur has always rendered at.
  document.getElementById('table-wrap').addEventListener('focusout', e=>{
    if(!hdrRenderPending) return;
    if(!(e.target && e.target.closest && e.target.closest('.hdr-fmt'))) return;
    const to = e.relatedTarget;
    if(to && to.closest && (to.closest('.hdr-fmt') || to.closest('.cal-header-bar .hdr-line'))) return;
    hdrRenderPending = false;
    render(currentSchedule);
  });
  // Every render() rebuilds both toolbars from markup that knows nothing about the current target, so
  // a rebuilt bar read as INERT -- "pick a line first" -- while the last-focused line was still the
  // target the next click would format. Re-reflect it after each rebuild. Observing #table-wrap
  // mutates nothing (CLAUDE.md, sanctioned pattern 3); any render also satisfies a pending one.
  new MutationObserver(()=>{
    hdrRenderPending = false;
    if(hdrFmtTarget && document.querySelector('#table-wrap .hdr-fmt')) syncHdrFmtToolbar();
  }).observe(document.getElementById('table-wrap'), { childList: true });

  function hdrLineFromEvent(t){
    const el = t && t.closest ? t.closest('.hdr-line') : null;
    if(!el) return null;
    if(el.dataset.hid) return { id: el.dataset.hid, mv: false, el };
    if(el.dataset.mvhid) return { id: el.dataset.mvhid, mv: true, el };
    return null;
  }
  function hdrFmtStore(mv){ return mv ? mvHeaderFormat : headerFormat; }
  // What a header line LOOKS like right now -- bold and italic as rendered -- which is what a Bold or
  // Italic toggle has to flip FROM. The stored format says nothing about lines the stylesheet
  // already styles: the waterfall title (.hdr-title, 700) and r1 (inline 600), and in the month view
  // the title, the date and the left slot (all 700). A toggle that read only the store turned an
  // already-bold line "bold" and nothing visibly happened (owner report, 24 Sep 2026: the builder's
  // Bold looked dead on the month title). The live line on the calendar is the authority; when its
  // view is not showing there is none, and the stored value is all there is.
  function hdrLiveLook(id, mv){
    const f = headerFmt(id, mv);
    const el = document.querySelector('#table-wrap ' + (mv ? `[data-mvhid="${id}"]` : `[data-hid="${id}"]`));
    const cs = el ? getComputedStyle(el) : null;
    return {
      bold:   f.bold   !== undefined ? f.bold   : !!(cs && parseInt(cs.fontWeight, 10) >= 600),
      italic: f.italic !== undefined ? f.italic : !!(cs && cs.fontStyle === 'italic'),
    };
  }
  // The inline style a header line is BORN with, before any user format. Only r1 has one: frozen
  // renderSpreadsheetView calls hline('r1','cal-subtitle','font-weight:600;') and APPENDS the user
  // format after it. The live repaint below replaces the whole style attribute, so without this
  // formatting r1 in any way -- a colour, a size -- visibly un-bolded it until the next render.
  // ⚠️ A mirror of that call site; if the renderer ever passes another line an extraStyle, add it.
  function hdrLineBaseCss(id, mv){ return (!mv && id === 'r1') ? 'font-weight:600;' : ''; }
  // Reflect the target line's current formatting back into the controls, so the toolbar shows
  // the state of what you are about to change rather than stale values from the last line.
  function syncHdrFmtToolbar(){
    document.querySelectorAll('.hdr-fmt').forEach(bar=>{
      const mv = bar.dataset.mv === '1';
      const active = hdrFmtTarget && hdrFmtTarget.mv === mv;
      bar.classList.toggle('has-target', !!active);
      const f = active ? (hdrFmtStore(mv)[hdrFmtTarget.id] || {}) : {};
      const q = sel => bar.querySelector(sel);
      q('.hf-size').value = f.size ? String(f.size) : '';
      // Lit from what the line LOOKS like, not the store: an unstyled month title is bold, and a B
      // that reads "off" over a bold line invites the click that then appears to do nothing.
      const look = active ? hdrLiveLook(hdrFmtTarget.id, mv) : { bold:false, italic:false };
      q('.hf-b').classList.toggle('is-on', look.bold);
      q('.hf-i').classList.toggle('is-on', look.italic);
      q('.hf-color').value = f.color || '#000000';
      q('.hf-hl').value = f.highlight || '#ffff00';
      const effAlign = f.align || (active ? headerDefaultAlign(hdrFmtTarget.id, mv) : 'left');
      const toggle = q('.hf-al-toggle');
      if(toggle){
        // The toggle wears the CURRENT alignment, so the toolbar answers "how is this line set?"
        // without opening anything.
        toggle.innerHTML = alignIcon(effAlign) + '<span class="hf-caret">\u25BE</span>';
        toggle.classList.toggle('is-on', !!f.align);
      }
      bar.querySelectorAll('.hf-al-opt').forEach(b=>{
        const on = effAlign === b.dataset.align;
        b.classList.toggle('is-on', on);
        b.setAttribute('aria-checked', on ? 'true' : 'false');
      });
    });
    syncStyleBar();   // the text style bar shows the same line (TEXT-STYLE-BAR-PLAN.md)
  }
  // Apply to state, then paint the live element directly. Deliberately NOT a full update():
  // re-rendering would destroy the contenteditable mid-edit and throw away the caret, and the
  // exports read headerFormat at export time anyway, so state is what has to be right.
  function applyHdrFmt(patch){
    if(!hdrFmtTarget) return;
    const store = hdrFmtStore(hdrFmtTarget.mv);
    const cur = Object.assign({}, store[hdrFmtTarget.id] || {}, patch);
    // Drop only EMPTY keys, never `false`. `bold:false` is meaningful -- it means "not bold even
    // though the stylesheet says otherwise", which is the only way to un-bold the title line.
    // Deleting it was the bug that made the Bold button look dead on the title.
    Object.keys(cur).forEach(k=>{ if(cur[k] === '' || cur[k] == null) delete cur[k]; });
    if(Object.keys(cur).length) store[hdrFmtTarget.id] = cur; else delete store[hdrFmtTarget.id];
    const sel = hdrFmtTarget.mv ? `[data-mvhid="${hdrFmtTarget.id}"]` : `[data-hid="${hdrFmtTarget.id}"]`;
    const el = document.querySelector('#table-wrap ' + sel);
    if(el) el.setAttribute('style', hdrLineBaseCss(hdrFmtTarget.id, hdrFmtTarget.mv) +
                                    headerFormatCss(cur, hdrFmtTarget.id, hdrFmtTarget.mv));
    syncHdrFmtToolbar();
    markDirty();
  }

  // Clear the target line's format. One function since the text style bar (TEXT-STYLE-BAR-PLAN.md) clears
  // a header line too; it was inline in the strip's click handler below.
  function clearHdrFmt(){
    if(hdrFmtTarget) delete hdrFmtStore(hdrFmtTarget.mv)[hdrFmtTarget.id];
    const sel = hdrFmtTarget ? (hdrFmtTarget.mv ? `[data-mvhid="${hdrFmtTarget.id}"]` : `[data-hid="${hdrFmtTarget.id}"]`) : null;
    const el = sel ? document.querySelector('#table-wrap ' + sel) : null;
    if(el) el.setAttribute('style', hdrLineBaseCss(hdrFmtTarget.id, hdrFmtTarget.mv));
    syncHdrFmtToolbar(); markDirty();
  }

  document.getElementById('table-wrap').addEventListener('focusin', e=>{
    const line = hdrLineFromEvent(e.target);
    if(line && line.el.classList.contains('hdr-editable')){
      hdrFmtTarget = { id: line.id, mv: line.mv };
      setStyleTarget('hdr');
      syncHdrFmtToolbar();
    }
  });
  // Keep the edited line focused when a toolbar BUTTON is pressed: preventDefault on mousedown
  // stops the contenteditable being blurred before the click lands, so the caret stays put.
  //
  // ⛔ BUTTONS ONLY. Preventing mousedown's default over a <select> SUPPRESSES THE NATIVE POPUP
  // in Chromium -- the exact behaviour SelectPop relies on deliberately (HANDOFF row 30) -- so a
  // blanket preventDefault across the toolbar meant the size dropdown could never open. It was
  // scoped by excluding the colour inputs, which quietly left the select broken. Naming the
  // buttons is the correct test: anything that is not a button here is a native control that
  // needs its own default behaviour.
  document.getElementById('table-wrap').addEventListener('mousedown', e=>{
    if(e.target.closest && e.target.closest('.hdr-fmt .hf-btn')) e.preventDefault();
  });
  document.getElementById('table-wrap').addEventListener('click', e=>{
    const bar = e.target.closest && e.target.closest('.hdr-fmt');
    if(!bar) return;
    // Insert ▾ opens the token palette. Handled FIRST and returned, because everything below this
    // point is about FORMATTING the target line and would otherwise run pointlessly on the way past.
    if(e.target.closest('.hf-insert')){ openHdrTokenPop(e.target.closest('.hf-insert')); return; }
    const store = hdrFmtTarget ? hdrFmtStore(hdrFmtTarget.mv) : null;
    const cur = (store && hdrFmtTarget) ? (store[hdrFmtTarget.id] || {}) : {};
    // Toggle from what the line ACTUALLY looks like right now, not from the stored value: the
    // title is bold by default, so an unset `cur.bold` there means "currently bold" and the first
    // click has to turn it OFF. Reading the live computed style is the only way to know which
    // lines the stylesheet has already bolded.
    // hdrLiveLook() is the one statement of this rule; the builder's toggles use it too.
    const look = hdrFmtTarget ? hdrLiveLook(hdrFmtTarget.id, hdrFmtTarget.mv) : { bold:false, italic:false };
    if(e.target.closest('.hf-b'))     return applyHdrFmt({ bold: !look.bold });
    if(e.target.closest('.hf-i'))     return applyHdrFmt({ italic: !look.italic });
    if(e.target.closest('.hf-clear')) return clearHdrFmt();
    const toggle = e.target.closest('.hf-al-toggle');
    if(toggle){
      const menu = bar.querySelector('.hf-al-menu');
      const open = menu.hidden;
      menu.hidden = !open;
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      return;
    }
    const opt = e.target.closest('.hf-al-opt');
    if(opt){
      const menu = bar.querySelector('.hf-al-menu');
      menu.hidden = true;
      bar.querySelector('.hf-al-toggle').setAttribute('aria-expanded','false');
      // Picking the alignment a line already has clears the override rather than pinning it, so
      // a line can be returned to following its column.
      return applyHdrFmt({ align: cur.align === opt.dataset.align ? '' : opt.dataset.align });
    }
  });
  // A body-level click closes the alignment menu. Registered on document, not #table-wrap: a
  // click anywhere else in the app should dismiss it, and the engine's own closeAllPops() does
  // not know about this menu.
  document.addEventListener('click', e=>{
    if(e.target.closest && e.target.closest('.hf-align-wrap')) return;
    document.querySelectorAll('.hf-al-menu').forEach(m=>{ m.hidden = true; });
    document.querySelectorAll('.hf-al-toggle').forEach(t=> t.setAttribute('aria-expanded','false'));
  });
  document.addEventListener('keydown', e=>{
    if(e.key !== 'Escape') return;
    document.querySelectorAll('.hf-al-menu:not([hidden])').forEach(m=>{ m.hidden = true; });
  });
  document.getElementById('table-wrap').addEventListener('input', e=>{
    if(!e.target.closest || !e.target.closest('.hdr-fmt')) return;
    if(e.target.classList.contains('hf-color')) return applyHdrFmt({ color: e.target.value });
    if(e.target.classList.contains('hf-hl'))    return applyHdrFmt({ highlight: e.target.value });
  });
  document.getElementById('table-wrap').addEventListener('change', e=>{
    if(!e.target.closest || !e.target.closest('.hdr-fmt')) return;
    if(e.target.classList.contains('hf-size')) return applyHdrFmt({ size: e.target.value ? Number(e.target.value) : '' });
  });

  // Ragged-rule glyphs for the three alignments. Drawn rather than taken from a font because no
  // dependable unicode character exists for these -- the nearest ones render as boxes in some
  // fonts -- and because a <select> cannot show an icon at all, which is why this is a button and
  // a small menu rather than a native dropdown.
  function alignIcon(a){
    const rows = {
      left:   ['M2 4h12', 'M2 8h7',  'M2 12h10'],
      center: ['M2 4h12', 'M4.5 8h7', 'M3 12h10'],
      right:  ['M2 4h12', 'M7 8h7',  'M4 12h10'],
    }[a];
    return `<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6"
      stroke-linecap="round" aria-hidden="true" focusable="false">${rows.map(d=>`<path d="${d}"/>`).join('')}</svg>`;
  }
  function alignMenuHtml(){
    const opts = ['left','center','right'].map(a=>
      `<button type="button" class="hf-al-opt" data-align="${a}" role="menuitemradio" aria-checked="false"
        title="Align ${a}" aria-label="Align ${a}">${alignIcon(a)}<span>${a[0].toUpperCase()+a.slice(1)}</span></button>`).join('');
    return `<span class="hf-align-wrap">
      <button type="button" class="hf-ctl hf-btn hf-al-toggle" aria-haspopup="menu" aria-expanded="false"
        title="Alignment" aria-label="Alignment">${alignIcon('left')}<span class="hf-caret">&#9662;</span></button>
      <span class="hf-al-menu" role="menu" hidden>${opts}</span>
    </span>`;
  }

  // The nine slots have ids, not names. The palette has to tell a user WHERE a token is about to
  // land, and "l2" is not an answer -- so give them the names a person would use looking at the
  // header. ⚠️ Display only; nothing keys off these.
  const HDR_SLOT_NAMES = {
    left: 'Left 1',  l2: 'Left 2',   l3: 'Left 3',
    c1: 'Centre 1',  c2: 'Centre 2', c3: 'Centre 3', c4: 'Centre 4',
    r1: 'Right 1',   r2: 'Right 2',  r3: 'Right 3',
  };
  // The three columns, in the order they sit on the page. ⛔ c4 IS DELIBERATELY NOT HERE.
  //
  // The header editor offers three slots per column (owner, 9 Sep 2026). c4 is the fourth centre
  // slot, added 31 Aug 2026 and already part of the save format -- so it is KEPT AND HIDDEN rather
  // than removed: it still renders, still exports, still restores, and a calendar that has text in
  // it loses nothing. The editor simply does not offer it as a new place to type, and reveals it
  // only for a calendar that is already using it. Deleting it outright would silently drop a line
  // from someone's header, which is the one thing the save-format contract forbids.
  const HDR_EDITOR_COLUMNS = [
    { key:'left',  label:'Left',   ids:['left','l2','l3'] },
    { key:'mid',   label:'Centre', ids:['c1','c2','c3'] },
    { key:'right', label:'Right',  ids:['r1','r2','r3'] },
  ];
  const HDR_LEGACY_SLOTS = ['c4'];

  function headerFmtToolbarHtml(mv){
    // The month header gained 10, 11 and 12 (owner, 20 Oct 2026, LABELS-SETUP-PLAN.md item 7: "10"):
    // a long "Revised as of …" line needs room. headerFormatCss() already takes 1-400.
    // ⚠️ This markup is printed into a MANUAL month header's document, so the option list moves gate
    // 10's mvheaderlegacy capture; the owner signed off the A/B before it was re-cut.
    const sizes = mv ? [10,11,12,14,16,18,20,22,26,30] : [8,9,10,11,12,13,14,16,18,22];
    return `<div class="hdr-fmt" role="toolbar" aria-label="Header text formatting" data-mv="${mv?1:0}">
      <select class="hf-ctl hf-size" title="Text size" aria-label="Text size">
        <option value="">Size</option>
        ${sizes.map(s=>`<option value="${s}">${s}</option>`).join('')}
      </select>
      <button type="button" class="hf-ctl hf-btn hf-b" title="Bold" aria-label="Bold"><b>B</b></button>
      <button type="button" class="hf-ctl hf-btn hf-i" title="Italic" aria-label="Italic"><i>I</i></button>
      <label class="hf-ctl hf-swatch" title="Text color">
        <span class="hf-swatch-ink">A</span>
        <input type="color" class="hf-color" value="#000000" aria-label="Text color">
      </label>
      <label class="hf-ctl hf-swatch hf-swatch-hl" title="Highlight color">
        <span class="hf-swatch-ink">A</span>
        <input type="color" class="hf-hl" value="#ffff00" aria-label="Highlight color">
      </label>
      ${alignMenuHtml()}
      <button type="button" class="hf-ctl hf-btn hf-clear" title="Clear formatting on this line" aria-label="Clear formatting">&#8709;</button>
      ${(!mv && headerTemplates) ? '<button type="button" class="hf-ctl hf-btn hf-insert" title="Insert live data into this line" aria-label="Insert token">Insert &#9662;</button>' : ''}
    </div>`;
  }

  // ---------- THE TEXT STYLE BAR (TEXT-STYLE-BAR-PLAN.md; owner rulings D1–D5, 21 Oct 2026) ----------
  // One bar, always on screen under the preview toolbar, that styles ANY text in the waterfall: what is
  // highlighted in the grid (Excel's highlight, ruling D2), a header line in either view and in every header
  // mode (D3, D4), or a side box's line. It does the jobs of the header's in-calendar strip and of the side
  // boxes' floating bar, which both retire (legacy.css), and it does them THROUGH THEIR OWN CODE --
  // applyHdrFmt / clearHdrFmt and applySideFmt -- so header and box styles are stored exactly as before.
  //
  // ⛔ NO CONTROL IN HERE HAS AN id. collectFieldValues() sweeps every input[id]/select[id]/textarea[id] in
  // the document into saved files and the undo stack; the bar is outside .prefs-card and .tools-menu, where
  // the class exclusions reach. Classes only, like the two bars it replaces. (And no Mantine Select: its
  // generated ids would land in fields.byId, PreviewToolbar.jsx's lead comment.)
  //
  // ⛔ THE HOST IS INSIDE .view-toggle-row (PreviewToolbar.jsx renders it, empty, last), so
  // .view-toggle-row -> #table-wrap stays the sibling pair the contracts need. A new sibling between them
  // would break it.
  //
  // ⭐ It names nothing. The owner had the header strip's readout of the selected line removed (31 Aug
  // 2026): the highlight on the grid, or the caret, already says what is picked. Only the empty state
  // speaks ("Highlight any text to style it", legacy.css), as the header strip's does.
  let styleTarget = null;      // 'grid' | 'hdr' | 'side' | null
  let styleBar = null;
  let styleBarLive = false;    // a colour well being dragged on grid text: banked as ONE undo step on change
  // Sizes each target offers. Header and boxes keep their own lists (headerFmtToolbarHtml, buildSideFmt);
  // grid text gets 6–12 (owner ruling D1: "6–12, grid never moves").
  const STYLE_BAR_SIZES = {
    grid: TEXT_STYLE_SIZES,
    hdr: [8, 9, 10, 11, 12, 13, 14, 16, 18, 22],
    hdrMonth: [10, 11, 12, 14, 16, 18, 20, 22, 26, 30],
    side: [8, 9, 10, 11, 12, 13, 14, 16, 18, 22],
  };

  // ---- The highlight (ruling D2: "just like excel"; plan §2a) ----
  // Every grid text in it, as '<kind>:<key>' -- the text style store's own kind and key, so the highlight
  // and the store can never disagree about which text a key names.
  // ⛔ SESSION UI, like gridSel: never saved, never in an undo step. ⛔ AND SEPARATE FROM gridSel, on purpose:
  // gridSel (phase cells only) is what fill-across, the column swap and moving a run read, and none of them
  // may ever receive a date or a note. A gesture that starts on a phase cell builds both, the same way.
  let textSel = new Set();
  let textSelAnchor = null;    // the key a Shift-click extends from
  let textSelActive = null;    // the key Enter or typing opens (D5): the last cell clicked
  // The keyboard's half (WATERFALL-KEYS-PLAN.md, 22 Oct 2026). textSelFocus is the far corner Shift+arrow moves
  // (Excel's: the anchor stays, the corner travels); navCursor is the slot the last arrow landed on inside its
  // cell, so crossing a wide cell comes back out in the column it went in by. wfNoteDrag is a note being dragged.
  let textSelFocus = null;
  let navCursor = null;
  let wfNoteDrag = null;
  function splitTextKey(k){ const i = k.indexOf(':'); return [k.slice(0, i), k.slice(i + 1)]; }
  // The week a row of one year block shows: the first data-week after that block's date cell. A row's
  // cells carry it (phase cells, bands, the note cell) except the date cell itself and Sim Post.
  function blockRowWeek(td){
    let d = td;
    while(d && !(d.classList && d.classList.contains('sheet-date'))) d = d.previousElementSibling;
    if(!d) return null;
    for(let c = d.nextElementSibling; c && !c.classList.contains('sheet-date'); c = c.nextElementSibling){
      if(c.dataset && c.dataset.week) return splitWeekKey(c.dataset.week).iso;
    }
    return null;
  }
  // A heading's first column, from the colgroup -- the same key for a default heading and a custom one.
  function headingColKey(th){
    const tr = th.parentElement, table = th.closest('table');
    if(!tr || !table) return null;
    let ci = 0;
    for(const c of tr.cells){ if(c === th) break; ci += c.colSpan || 1; }
    const col = table.querySelectorAll('colgroup col')[ci];
    return (col && col.dataset.ckey && HDR_ROW_KEY.test(col.dataset.ckey)) ? col.dataset.ckey : null;
  }
  // Sim Post's cell has no class and no data: frozen renderSpreadsheetView writes only its fill and ink.
  function isSimPostTd(td){
    const st = (td.getAttribute('style') || '').toUpperCase();
    return !td.className && st.startsWith('BACKGROUND:' + SIMPOST_COLOR.toUpperCase());
  }
  // The '<kind>:<key>' of a grid cell, or null for one with no text of its own (an empty slot, a padding row).
  function textCellKey(cell){
    if(!cell || !cell.closest || !cell.closest('#table-wrap table.sheet-table')) return null;
    if(cell.tagName === 'TH'){ const ck = headingColKey(cell); return ck ? 'heading:' + ck : null; }
    if(cell.tagName !== 'TD' || cell.classList.contains('sheet-empty')) return null;
    const wk = cell.dataset.week;
    if(cell.classList.contains('sheet-date')){ const w = blockRowWeek(cell); return w ? 'date:' + w : null; }
    if(cell.classList.contains('sheet-note-cell')) return wk ? 'note:' + wk : null;
    if(cell.classList.contains('sheet-hiatus-cell')) return wk ? 'hiatus:' + (cell.dataset.pkey ? wk + '|' + cell.dataset.pkey : wk) : null;
    if(cell.classList.contains('sheet-phase-cell')) return (wk && cell.dataset.pkey) ? 'phase:' + wk + '|' + cell.dataset.pkey : null;
    if(isSimPostTd(cell)){ const w = blockRowWeek(cell); return w ? 'simpost:' + w : null; }
    return null;
  }
  // Every keyed text cell in the live grid. ⛔ #table-wrap only: both print paths render a second grid into
  // #print-root, with the same keys (allPhaseTds' reason).
  function textCellIndex(){
    const out = new Map();
    const table = document.querySelector('#table-wrap table.sheet-table');
    if(!table) return out;
    table.querySelectorAll('thead th, tbody td').forEach(c=>{ const k = textCellKey(c); if(k && !out.has(k)) out.set(k, c); });
    return out;
  }
  // Does this cell show text? (An empty note cell shows only its "+" hint, which is not text.)
  function textCellHasText(cell, kind){
    if(kind === 'note') return cell.classList.contains('has-note');
    return !!(cell.textContent || '').trim();
  }
  // The keys the bar would style: highlighted AND showing text. ("Only text is styled", plan §2a.)
  function textSelTargets(){
    const idx = textCellIndex();
    return [...textSel].filter(k=>{ const c = idx.get(k); return !!c && textCellHasText(c, splitTextKey(k)[0]); });
  }

  // The cell under a point. Walks the hit stack past the resize handles (they cover ~29% of a cell, hitCell's
  // reason), and stops at any body-level panel or the swap controls, as hitCell does.
  function hitTextCell(x, y){
    for(const el of document.elementsFromPoint(x, y)){
      if(el.closest && el.closest(OVER_PANEL)) return null;
      if(el.classList && (el.classList.contains('grid-swap-knob') || el.classList.contains('grid-stint-btn'))) return null;
      const cell = el.closest && el.closest('#table-wrap table.sheet-table td, #table-wrap table.sheet-table th');
      if(cell) return cell;
      if(el.id === 'table-wrap') return null;
    }
    return null;
  }

  // ---- Drawing the highlight ----
  // Body cells on a layer like .grid-sel-layer (a sibling inside .sheet-grid-wrap: the grid's own coordinate
  // space, scrolled and clipped with it, absent from both print paths). Headings on a STICKY strip at the
  // wrap's top, because the heading row is sticky (frozen `.sheet-table th`) and a box on the scrolling layer
  // would slide away from it. Both pointer-events:none, so nothing here can take a click.
  function ensureTextSelLayers(){
    const wrap = document.querySelector('#table-wrap .sheet-grid-wrap');
    if(!wrap) return null;
    let body = wrap.querySelector(':scope > .text-sel-layer');
    if(!body){ body = document.createElement('div'); body.className = 'text-sel-layer'; wrap.appendChild(body); }
    let head = wrap.querySelector(':scope > .text-sel-head');
    if(!head){ head = document.createElement('div'); head.className = 'text-sel-head'; wrap.insertBefore(head, wrap.firstChild); }
    return { wrap, body, head };
  }
  function redrawTextSel(marquee){
    const idx = textCellIndex();
    // Prune against the live grid, gridSel's one cleanup rule: a render that retired a cell drops its key.
    textSel = new Set([...textSel].filter(k => idx.has(k)));
    if(textSelAnchor && !idx.has(textSelAnchor)) textSelAnchor = null;
    if(textSelActive && !idx.has(textSelActive)) textSelActive = null;
    if(textSelFocus && !idx.has(textSelFocus)) textSelFocus = null;
    const L = ensureTextSelLayers();
    if(!L){ if(styleTarget === 'grid' && !textSel.size) setStyleTarget(null); return; }
    L.body.textContent = ''; L.head.textContent = '';
    const z = gridZoom(L.wrap) || 1;
    const wr = L.wrap.getBoundingClientRect(), hr = L.head.getBoundingClientRect();
    // Every rect READ first, then every box WRITTEN: reading a rect after appending a box forces a layout
    // per cell, which Cmd+A over a few hundred cells turns into seconds.
    const boxes = [...textSel].map(k=>{ const c = idx.get(k); return { k, head: c.tagName === 'TH', r: c.getBoundingClientRect() }; });
    const fragBody = document.createDocumentFragment(), fragHead = document.createDocumentFragment();
    boxes.forEach(({k, head, r})=>{
      const o = head ? hr : wr;
      const d = document.createElement('div');
      d.className = 'text-sel-cell' + (k === textSelActive ? ' is-active' : '');
      d.style.left = (r.left - o.left) / z + 'px';
      d.style.top = (r.top - o.top) / z + 'px';
      d.style.width = Math.max(1, r.width / z) + 'px';
      d.style.height = Math.max(1, r.height / z) + 'px';
      (head ? fragHead : fragBody).appendChild(d);
    });
    L.body.appendChild(fragBody); L.head.appendChild(fragHead);
    if(marquee){
      const m = document.createElement('div');
      m.className = 'text-sel-marquee';
      m.style.left = (marquee.l - wr.left) / z + 'px';
      m.style.top = (marquee.t - wr.top) / z + 'px';
      m.style.width = (marquee.r - marquee.l) / z + 'px';
      m.style.height = (marquee.b - marquee.t) / z + 'px';
      L.body.appendChild(m);
    }
    drawWfNoteOverlay(L, idx, wr, z);
    if(styleTarget === 'grid' && !textSel.size) setStyleTarget(null); else syncStyleBar();
  }
  function clearTextSel(){
    if(!textSel.size && !textSelAnchor && !textSelActive) return;
    textSel.clear(); textSelAnchor = null; textSelActive = null; textSelFocus = null; navCursor = null;
    const L = ensureTextSelLayers();
    if(L){ L.body.textContent = ''; L.head.textContent = ''; }
  }
  // Every render replaces .sheet-grid-wrap, so redraw after it (childList only -- the layers are written
  // inside the wrap, a descendant, so this cannot observe its own paint; the gridSel observer's rule).
  new MutationObserver(()=>{
    if(viewMode !== 'sheet'){ if(textSel.size){ clearTextSel(); if(styleTarget === 'grid') setStyleTarget(null); } return; }
    if(textSel.size) redrawTextSel(null);
  }).observe(document.getElementById('table-wrap'), { childList: true });
  let _textSelFrame = 0;
  window.addEventListener('resize', ()=>{
    if(_textSelFrame || !textSel.size) return;
    _textSelFrame = requestAnimationFrame(()=>{ _textSelFrame = 0; redrawTextSel(null); });
  });

  // Cells whose box meets a screen rectangle. Membership by the cell's whole box (Excel's rule for a merged
  // cell: touch any part of it and it is in).
  function textCellsInRect(rect){
    const out = [];
    textCellIndex().forEach((c, k)=>{
      const b = c.getBoundingClientRect();
      if(b.right > rect.l && b.left < rect.r && b.bottom > rect.t && b.top < rect.b) out.push(k);
    });
    return out;
  }
  function textCellRect(c){ const b = c.getBoundingClientRect(); return { l:b.left, r:b.right, t:b.top, b:b.bottom }; }

  // ---- The gesture: click, drag, Shift-click, ⌘-click (D2) ----
  // Capture phase, registered after gridSel's: on a phase cell both run, and both build their own set from
  // the same pointer. ⛔ No preventDefault, for gridSel's reason (it would suppress click and dblclick).
  document.addEventListener('pointerdown', e=>{
    if(e.button !== 0 || viewMode !== 'sheet' || e.pointerType === 'touch') return;
    if(e.target.closest && e.target.closest('.grid-resize, .grid-sel-layer, .grid-swap-layer')) return;
    const cell = hitTextCell(e.clientX, e.clientY);
    if(!cell) return;
    const startKey = textCellKey(cell);
    // ONE selection on screen, as in Excel. A plain press that starts OFF a phase cell retires the phase
    // selection (gridSel), whose own handler only ever reacts to presses ON phase cells -- so before this, a
    // click on a date left the purple phase selection, its count chip and the swap knob showing beside the new
    // highlight (seen on the first screenshot of the bar, 21 Oct 2026). A ⌘- or Shift-press keeps it: that
    // is adding to what is selected. A press on a phase cell is gridSel's own business, untouched.
    const onPhase = cell.tagName === 'TD' && cell.classList.contains('sheet-phase-cell') && hasSpanContract(cell);
    if(!onPhase && !e.shiftKey && !(e.metaKey || e.ctrlKey) && (gridSel.size || gridSelAnchor)){
      gridSel.clear(); gridSelAnchor = null; redrawGridOverlay(null);
    }
    // Native text selection would paint over a sweep; suppressed for this gesture only, and never inside an
    // editable header line or a form field (gridSel's killSel, widened to every grid cell).
    const killSel = ev=>{
      const n = ev.target && ev.target.nodeType === 3 ? ev.target.parentElement : ev.target;
      if(!n || !n.closest || n.closest('.hdr-line, [contenteditable], input, textarea')) return;
      if(n.closest('#table-wrap table.sheet-table')) ev.preventDefault();
    };
    document.addEventListener('selectstart', killSel, true);
    const x0 = e.clientX, y0 = e.clientY;
    const shiftKey = e.shiftKey, metaKey = e.metaKey || e.ctrlKey;
    const base = (shiftKey || metaKey) ? new Set(textSel) : new Set();
    let sweeping = false;
    // A press on a note that is ALREADY highlighted, and shows text, drags it to another week (WATERFALL-KEYS-PLAN
    // §1) once it moves past the sweep's own thresholds; a press on anything else sweeps exactly as before. So
    // the highlight is never re-picked by the drag, and a click on it (no movement) still re-picks just it.
    const dragNotes = !shiftKey && !metaKey && !activeNoteEditor && !!startKey && splitTextKey(startKey)[0] === 'note' &&
                      textSel.has(startKey) && cell.classList.contains('has-note');
    let dragging = false;
    const onMove = ev=>{
      if(ev.buttons === 0){ onUp(ev); return; }
      if(dragging){ wfNoteDragMove(ev.clientX, ev.clientY); return; }
      if(!sweeping){
        // gridSel's thresholds, so one press never sweeps in one set and clicks in the other.
        const dist = Math.hypot(ev.clientX - x0, ev.clientY - y0);
        if(dist < 10) return;
        if(dist < 24 && hitTextCell(ev.clientX, ev.clientY) === cell) return;
        if(dragNotes && wfNoteDragBegin(cell, startKey, x0, y0)){
          dragging = true;
          wfNoteDragMove(ev.clientX, ev.clientY);
          return;
        }
        sweeping = true;
      }
      const rect = { l:Math.min(x0, ev.clientX), r:Math.max(x0, ev.clientX), t:Math.min(y0, ev.clientY), b:Math.max(y0, ev.clientY) };
      textSel = new Set(base);
      textCellsInRect(rect).forEach(k => textSel.add(k));
      textSelAnchor = startKey; textSelActive = startKey;
      redrawTextSel(rect);
    };
    const onUp = ev=>{
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onUp);
      document.removeEventListener('selectstart', killSel, true);
      if(dragging){ wfNoteDragEnd(!ev || ev.type === 'pointercancel'); return; }
      // The far corner Shift+arrow moves next: where a sweep ended, or the cell pressed.
      const endCell = (sweeping && ev && ev.clientX !== undefined) ? hitTextCell(ev.clientX, ev.clientY) : null;
      textSelFocus = (endCell && textCellKey(endCell)) || startKey;
      navCursor = null;
      if(!sweeping){
        if(shiftKey && textSelAnchor){
          const a = textCellIndex().get(textSelAnchor);
          if(a){
            const ra = textCellRect(a), rb = textCellRect(cell);
            const rect = { l:Math.min(ra.l, rb.l) + 1, r:Math.max(ra.r, rb.r) - 1, t:Math.min(ra.t, rb.t) + 1, b:Math.max(ra.b, rb.b) - 1 };
            textSel = new Set(base);
            textCellsInRect(rect).forEach(k => textSel.add(k));
          }
          if(startKey) textSelActive = startKey;
        } else if(metaKey){
          if(startKey){
            if(textSel.has(startKey)) textSel.delete(startKey); else textSel.add(startKey);
            textSelAnchor = textSelActive = startKey;
          }
        } else {
          textSel = new Set(startKey ? [startKey] : []);
          textSelAnchor = textSelActive = startKey;
        }
      }
      if(textSel.size) setStyleTarget('grid');
      redrawTextSel(null);
    };
    document.addEventListener('pointermove', onMove);
    document.addEventListener('pointerup', onUp);
    document.addEventListener('pointercancel', onUp);
  }, true);

  // ---- D5: a double-click, Enter or typing opens a note's or a band's editor ----
  // Owner, 21 Oct 2026: "double-click (or Enter, or typing) opens a note or hiatus band's editor; a single
  // click highlights it, like Excel." And for a band inside one phase's column, which double-click used to
  // fill across (1 Sep 2026), the owner's picker the same day: "Double-click edits".
  // Opens the cell's editor, committing any other one first (that re-renders, so the cell is found again in
  // the fresh grid by its week and kind). The switching logic the old click opener had, unchanged.
  function openNoteCellEditor(td){
    if(activeNoteEditor && activeNoteEditor.td === td) return activeNoteEditor;
    if(activeNoteEditor){
      const targetWeek = td.dataset.week, targetPkey = td.dataset.pkey;
      const targetSel = td.classList.contains('sheet-hiatus-cell') ? 'td.sheet-hiatus-cell' : 'td.sheet-note-cell';
      commitActiveNoteEditor();
      const fresh = document.querySelector(`#table-wrap ${targetSel}[data-week="${targetWeek}"]${targetPkey ? `[data-pkey="${targetPkey}"]` : ''}`);
      if(fresh) openNoteEditor(fresh);
      return activeNoteEditor;
    }
    openNoteEditor(td);
    return activeNoteEditor;
  }
  const NOTE_TD = 'td.sheet-note-cell, td.sheet-hiatus-cell';
  // Capture, so it runs before frozen dblclick fill-across (a document BUBBLE listener) and can stop it for a
  // band. The batch fill's capture listener (registered earlier) skips bands for the same reason.
  document.addEventListener('dblclick', e=>{
    if(viewMode !== 'sheet') return;
    if(e.target.closest && e.target.closest('.grid-resize')) return;   // a handle's dblclick is autofit
    let td = e.target.closest ? e.target.closest('#table-wrap ' + NOTE_TD.split(', ').join(', #table-wrap ')) : null;
    if(!td){ const c = hitTextCell(e.clientX, e.clientY); td = c && c.matches && c.matches(NOTE_TD) ? c : null; }
    if(!td) return;
    e.preventDefault();
    e.stopPropagation();
    openNoteCellEditor(td);
  }, true);
  // Enter and typing, once something is highlighted. Capture, so Enter on a note never also reaches the
  // batch fill's Enter. Only with focus on <body> (the gridSel keyboard rule: a focused control owns its
  // keys) and never with ⌘, Ctrl or Alt held, which belong to the shortcuts and the column swap.
  document.addEventListener('keydown', e=>{
    // (A note being dragged takes Escape for itself: it cancels the drag and keeps the highlight.)
    if(viewMode !== 'sheet' || !textSel.size || activeNoteEditor || wfNoteDrag) return;
    const a = document.activeElement;
    if(a && a !== document.body) return;
    if(e.metaKey || e.ctrlKey || e.altKey) return;
    if(e.key === 'Escape'){ clearTextSel(); setStyleTarget(null); return; }
    const active = textSelActive;
    if(!active) return;
    const [kind] = splitTextKey(active);
    if(kind !== 'note' && kind !== 'hiatus') return;
    const typed = e.key.length === 1 ? e.key : null;
    if(e.key !== 'Enter' && !typed) return;
    if(e.key === 'Enter' && e.shiftKey) return;
    const td = textCellIndex().get(active);
    if(!td) return;
    e.preventDefault();
    e.stopPropagation();
    const ed = openNoteCellEditor(td);
    // Typing ADDS the key at the end (plan §1 D5): Excel replaces the cell, but a stray key must never wipe
    // a note. The editor opened with its text selected; this puts the caret at the end instead.
    if(typed && ed && ed.textarea){
      const ta = ed.textarea;
      ta.value += typed;
      ta.setSelectionRange(ta.value.length, ta.value.length);
      ta.dispatchEvent(new Event('input', { bubbles: true }));
    }
  }, true);
  // ⌘A over a live highlight takes in the whole grid -- only while something is highlighted, so ⌘A anywhere
  // else in the app still selects text as it always has.
  document.addEventListener('keydown', e=>{
    if(viewMode !== 'sheet' || !textSel.size || !(e.metaKey || e.ctrlKey) || e.altKey || e.key.toLowerCase() !== 'a') return;
    const a = document.activeElement;
    if(a && a !== document.body) return;
    e.preventDefault();
    textSel = new Set(textCellIndex().keys());
    redrawTextSel(null);
  });

  // ---------- EXCEL'S EDITING KEYS (WATERFALL-KEYS-PLAN.md; owner rulings Q1–Q4, 22 Oct 2026) ----------
  // Items 2 and 3 of the owner's "what Excel features are we missing" list: the arrow keys, Tab and Delete on the
  // highlight; copy, cut and paste notes; and drag a note to another week. All of it acts on the highlight above
  // (textSel), writes only the stores the note editor writes, through its own saveNoteEdit(), and then calls
  // frozen render(). Nothing here draws in a cell: a pasted or moved note is drawn exactly as the same note typed,
  // which is the freeze's line (what a cell looks like, how much text fits in it).
  // ⛔ No setting, no snapshot key, no id (collectFieldValues sweeps ids). The drop outlines and the one message
  // are drawn on the highlight's own layer, which neither print path has.
  // ⭐ FOR THE WATERFALL'S RIGHT-CLICK MENU (mocked up 22 Oct 2026, not built): wfNotesCopy / wfNotesCut /
  // wfNotesPaste / wfNotesClear do the whole job and the listeners below only call them. A menu's Copy or Cut can
  // hand `.text` of what they return to navigator.clipboard.writeText(); its Paste can hand
  // navigator.clipboard.readText()'s text to wfNotesPaste(text), and wfNoteClip brings the look back with it.

  // ---- The grid as Excel sees it ----
  // Every slot (row, column) of the live table, heading row first, mapped to the keyed text cell covering it, or
  // null for a blank gap or a padding row; and each key's slot range. Built from rowSpan/colSpan, so a band across
  // four columns, or a cell dragged across the empty ones beside it, is ONE cell, as a merged cell is in Excel.
  // Read off the DOM after every render, like textCellIndex(): it is the frozen table's own shape.
  function textSelMatrix(){
    const table = document.querySelector('#table-wrap table.sheet-table');
    if(!table) return null;
    const grid = [], pos = new Map();
    let nc = 0;
    Array.from(table.rows).forEach((tr, r)=>{
      const row = grid[r] || (grid[r] = []);
      let c = 0;
      for(const cell of tr.cells){
        while(row[c] !== undefined) c++;
        const rs = Math.max(1, cell.rowSpan || 1), cs = Math.max(1, cell.colSpan || 1);
        const k = textCellKey(cell);
        for(let dr = 0; dr < rs; dr++){
          const g = grid[r + dr] || (grid[r + dr] = []);
          for(let dc = 0; dc < cs; dc++) g[c + dc] = k;     // null still marks the slot as taken
        }
        if(k && !pos.has(k)) pos.set(k, { r0: r, r1: r + rs - 1, c0: c, c1: c + cs - 1 });
        c += cs;
        nc = Math.max(nc, c);
      }
    });
    return { grid, pos, nr: grid.length, nc };
  }
  // One step from `key` toward `dir`. A blank gap is stepped over (it can hold no highlight), and so is the cell
  // itself where it spans rows or columns. ⭐ An EMPTY Notes cell is a stop, not a gap: it is keyed, and it is
  // where a new note gets typed. Starts from the slot the keyboard last stood on inside the cell (navCursor), so
  // a move down through a band comes out in the column it went in by. Null at the grid's edge.
  function textSelStep(M, key, dir){
    const p = M.pos.get(key);
    if(!p) return null;
    const cur = (navCursor && navCursor.key === key) ? navCursor : { r: p.r0, c: p.c0 };
    const dr = dir === 'down' ? 1 : dir === 'up' ? -1 : 0;
    const dc = dir === 'right' ? 1 : dir === 'left' ? -1 : 0;
    let r = dr > 0 ? p.r1 + 1 : dr < 0 ? p.r0 - 1 : cur.r;
    let c = dc > 0 ? p.c1 + 1 : dc < 0 ? p.c0 - 1 : cur.c;
    while(r >= 0 && r < M.nr && c >= 0 && c < M.nc){
      const k = (M.grid[r] || [])[c];
      if(k && k !== key) return { key: k, r, c };
      r += dr; c += dc;
    }
    return null;
  }
  // Every keyed cell touching the rectangle that spans two cells' slots (Shift+arrow's highlight).
  function textSelRectKeys(M, a, b){
    const pa = M.pos.get(a), pb = M.pos.get(b);
    if(!pa || !pb) return [];
    const r0 = Math.min(pa.r0, pb.r0), r1 = Math.max(pa.r1, pb.r1);
    const c0 = Math.min(pa.c0, pb.c0), c1 = Math.max(pa.c1, pb.c1);
    const out = [];
    M.pos.forEach((p, k)=>{ if(p.r1 >= r0 && p.r0 <= r1 && p.c1 >= c0 && p.c0 <= c1) out.push(k); });
    return out;
  }
  // The bottom of the heading row as it is DRAWN. ⛔ Read off a heading cell, never the <thead>: the sticky rule is
  // on the cells (frozen `.sheet-table th`), so once the pane scrolls the <thead> box itself has gone off the top and
  // its rect says the heading takes no room (found by the leg: rows parked under the heading on the way back up).
  function sheetHeadBottom(sc){
    const th = sc.querySelector('table.sheet-table thead th');
    return th ? th.getBoundingClientRect().bottom : sc.getBoundingClientRect().top;
  }
  // Scroll the grid's own pane so a cell is in view, below the sticky heading row. ⛔ Not scrollIntoView(): that
  // also scrolls every overflow:hidden ancestor, and the app shell's window must never scroll (UI-CONVENTIONS §7).
  function scrollTextCellIntoView(cell){
    const sc = cell && cell.closest('.sheet-scroll');
    if(!sc) return;
    const z = sc.currentCSSZoom || 1;
    const s = sc.getBoundingClientRect(), r = cell.getBoundingClientRect();
    const top = cell.tagName === 'TH' ? s.top : Math.max(s.top, sheetHeadBottom(sc));
    const bottom = s.top + sc.clientHeight * z, right = s.left + sc.clientWidth * z;
    if(r.top < top) sc.scrollTop -= (top - r.top) / z;
    else if(r.bottom > bottom) sc.scrollTop += (r.bottom - bottom) / z;
    if(r.left < s.left) sc.scrollLeft -= (s.left - r.left) / z;
    else if(r.right > right) sc.scrollLeft += (r.right - right) / z;
  }
  // The arrow keys and Tab. A plain move takes the highlight to the one cell next to the active one; Shift keeps
  // the anchor and moves the far corner, highlighting the rectangle between them, as Excel does.
  function moveTextSel(dir, extend){
    const M = textSelMatrix();
    if(!M) return false;
    const live = k => !!k && M.pos.has(k);
    const active = live(textSelActive) ? textSelActive : [...textSel].find(live);
    if(!active) return false;
    if(!extend){
      const s = textSelStep(M, active, dir);
      if(!s) return false;
      textSel = new Set([s.key]);
      textSelAnchor = textSelActive = textSelFocus = s.key;
      navCursor = s;
    } else {
      const anchor = live(textSelAnchor) ? textSelAnchor : active;
      const s = textSelStep(M, live(textSelFocus) ? textSelFocus : active, dir);
      if(!s) return false;
      textSelAnchor = anchor;
      textSelFocus = s.key;
      navCursor = s;
      textSel = new Set(textSelRectKeys(M, anchor, s.key));
      if(!textSel.has(textSelActive)) textSelActive = anchor;
    }
    // One selection on screen (the pointer gesture's rule): a key move leaves the phase selection behind.
    if(gridSel.size || gridSelAnchor){ gridSel.clear(); gridSelAnchor = null; redrawGridOverlay(null); }
    setStyleTarget('grid');
    redrawTextSel(null);
    scrollTextCellIntoView(textCellIndex().get(extend ? textSelFocus : textSelActive));
    return true;
  }

  // ---- The notes in the highlight ----
  // Weeks of the highlighted Notes cells, oldest first ('YYYY-MM-DD' sorts as dates do).
  function wfSelNoteWeeks(keys){
    const out = new Set();
    (keys || [...textSel]).forEach(k=>{ const [kind, wk] = splitTextKey(k); if(kind === 'note' && wk) out.add(wk); });
    return [...out].sort();
  }
  // The Notes cells on screen, in week order: what "the next week down" means for a paste and a drop. An
  // all-phase hiatus row has no Notes cell (its band runs across the column), so it is not in here and is stepped
  // over; and with a calendar range set, only the weeks the waterfall shows are.
  function wfNoteSeq(){
    return Array.from(document.querySelectorAll('#table-wrap table.sheet-table td.sheet-note-cell[data-week]'), td => td.dataset.week).sort();
  }
  function wfNoteShows(wk){ return !!effectiveNoteText(wk, sheetAutoNotesFor(wk)); }
  // Ruling Q1 ("Empty the Notes cells"): the cell goes blank whatever it showed. An automatic note is stored as
  // the note editor's explicit clear (text:''), so it stays blank until typed in or undone; the note's highlight,
  // size and style go with it, the editor's own rule for a note left empty (commitActiveNoteEditor).
  function wfClearNote(wk){
    saveNoteEdit(wk, '', sheetAutoNotesFor(wk), '');
    delete noteColors[wk]; delete noteFontSize[wk]; delete textStyle.note[wk];
  }
  // A note as it travels: its text as the cell shows it and (ruling Q2, "Text and its look") its highlight, size
  // and style-bar style. A note pinned to a day (the editor's Day picker) keeps its weekday, `dow`; `stamp` is the
  // date the picker wrote at the end of its text, re-stamped where the note lands.
  function wfNoteItem(wk){
    const text = effectiveNoteText(wk, sheetAutoNotesFor(wk));
    const it = { text };
    if(!text) return it;
    const u = userNotes[wk];
    const d = (u && typeof u === 'object' && typeof u.date === 'string') ? parseDateUTC(u.date) : null;
    const w = parseDateUTC(wk);
    if(d && w){
      const dow = Math.round((d - w) / DAY_MS);
      if(dow >= 0 && dow <= 6){ it.dow = dow; if(text.endsWith(fmtShort(d))) it.stamp = fmtShort(d); }
    }
    if(noteColors[wk]) it.color = noteColors[wk];
    if(noteFontSize[wk] !== undefined) it.size = noteFontSize[wk];
    if(textStyle.note[wk]) it.style = Object.assign({}, textStyle.note[wk]);
    return it;
  }
  // Write one travelling note into a week. `look` (an item copied inside SPTCal) replaces the week's look with
  // the note's own; text from anywhere else lands in the look the cell already has, as typing into it would.
  // Through saveNoteEdit(), so a note equal to its week's automatic text goes back to automatic, and an empty one
  // is the explicit clear (ruling Q3: a blank line in a paste empties its week, as Delete does).
  function wfPutNote(wk, it, look){
    const auto = sheetAutoNotesFor(wk);
    let text = it.text, date = '';
    const w = parseDateUTC(wk);
    if(text && it.dow !== undefined && w){
      const d = addDays(w, it.dow);
      date = isoOf(d);
      if(it.stamp && text.endsWith(it.stamp)) text = text.slice(0, text.length - it.stamp.length) + fmtShort(d);
    }
    saveNoteEdit(wk, text, auto, date);
    if(look){
      if(it.color && it.color.toUpperCase() !== MILESTONE_COLOR.toUpperCase()) noteColors[wk] = it.color; else delete noteColors[wk];
      if(it.size !== undefined && it.size !== 11) noteFontSize[wk] = it.size; else delete noteFontSize[wk];
      if(it.style) textStyle.note[wk] = Object.assign({}, it.style); else delete textStyle.note[wk];
    }
    if(!effectiveNoteText(wk, auto)){ delete noteColors[wk]; delete noteFontSize[wk]; delete textStyle.note[wk]; }
  }
  // ⛔ ONE GESTURE, ONE UNDO STEP (the month note drag's pattern): flush whatever came before into its own step,
  // change the stores, render, and bank this step now, so a Delete and a paste a moment later can never merge in
  // the 500 ms debounce. Returns false, changing nothing and dirtying nothing, when the stores did not move.
  function wfNoteStep(fn){
    const sig = ()=> JSON.stringify([userNotes, noteColors, noteFontSize, textStyle.note]);
    const before = sig();
    pushUndoSnapshot();
    fn();
    if(sig() === before) return false;
    render(currentSchedule);
    pushUndoSnapshot();
    markDirty();
    return true;
  }
  // The highlight after a paste or a drop: the cells written, the first active (Excel selects what it pasted).
  function wfHighlightWeeks(weeks, activeWk){
    if(!weeks.length) return;
    textSel = new Set(weeks.map(w => 'note:' + w));
    textSelAnchor = textSelActive = 'note:' + (activeWk || weeks[0]);
    textSelFocus = 'note:' + weeks[weeks.length - 1];
    navCursor = null;
    setStyleTarget('grid');
    redrawTextSel(null);
  }

  // ---- Clear, copy, cut, paste (the right-click menu's entry points too) ----
  function wfNotesClear(keys){
    const weeks = wfSelNoteWeeks(keys);
    return weeks.length ? wfNoteStep(()=> weeks.forEach(wfClearNote)) : false;
  }
  // The last copy, so pasting the same text back carries the look (Q2) even through navigator.clipboard, which
  // only reads plain text. Session UI: never saved.
  let wfNoteClip = null;
  const WF_CLIP_TYPE = 'application/x-sptcal-notes';
  // Excel's text form: every cell's line ENDS in a line break (so an empty last week survives the trip), and a
  // cell holding a line break (or a tab) is in double quotes with its quotes doubled, so a two-line note pastes
  // back into ONE week -- here, or in Excel.
  function tsvCell(s){ return /[\t\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }
  function wfNotesCopy(keys){
    const weeks = wfSelNoteWeeks(keys);
    if(!weeks.length) return null;
    const items = weeks.map(wfNoteItem);
    wfNoteClip = { text: items.map(it => tsvCell(it.text) + '\n').join(''), items };
    return wfNoteClip;
  }
  // Cut is Copy, then Delete (Q1): the cells empty now, and the notes travel on the clipboard.
  function wfNotesCut(keys){
    const clip = wfNotesCopy(keys);
    if(clip) wfNotesClear(keys);
    return clip;
  }
  // Clipboard text as this file compares it: one line ending, and Excel's trailing line break dropped.
  function wfClipNormal(text){
    const s = String(text || '').replace(/\r\n?/g, '\n');
    return s.endsWith('\n') ? s.slice(0, -1) : s;
  }
  // Plain text into one note per line. A field that opens with a quote and closes cleanly (a quote, then a tab,
  // a line break or the end) is Excel's quoted cell; any other quote is just a character. Several cells on one
  // line (a row copied from Excel) become one note, joined by spaces. Characters XML forbids are removed, as for
  // anything typed or pasted into the app (stripXmlIllegal's reason: the workbook would not open).
  function parseClipText(s){
    if(!s) return [];
    const rows = [];
    let row = [], i = 0;
    const n = s.length;
    for(;;){
      let field;
      if(s[i] === '"'){
        let j = i + 1, buf = '', ok = false;
        while(j < n){
          if(s[j] === '"'){
            if(s[j + 1] === '"'){ buf += '"'; j += 2; continue; }
            ok = j + 1 === n || s[j + 1] === '\t' || s[j + 1] === '\n';
            break;
          }
          buf += s[j++];
        }
        if(ok){ field = buf; i = j + 1; }
      }
      if(field === undefined){
        let j = i;
        while(j < n && s[j] !== '\t' && s[j] !== '\n') j++;
        field = s.slice(i, j);
        i = j;
      }
      row.push(field);
      if(i >= n){ rows.push(row); break; }
      if(s[i] === '\n'){ rows.push(row); row = []; }
      i++;
    }
    return rows.map(r => stripXmlIllegal(r.map(c => c.trim()).filter(Boolean).join(' '), '\n'));
  }
  // A travelling note read back from the clipboard's own SPTCal data, which another window (or anything that can
  // write a clipboard) may have written: held to what a saved file may hold (sanitizeSnapshot's rules).
  function wfCleanClipItem(it){
    if(!isPlainObj(it) || typeof it.text !== 'string') return null;
    const out = { text: stripXmlIllegal(it.text, '\n') };
    if(Number.isInteger(it.dow) && it.dow >= 0 && it.dow <= 6) out.dow = it.dow;
    if(typeof it.stamp === 'string' && /^\d{1,2}\/\d{1,2}\/\d{2}$/.test(it.stamp)) out.stamp = it.stamp;
    if(isHexColor(it.color)) out.color = it.color;
    const size = finiteNum(it.size);
    if(size !== null && size >= 1 && size <= 400) out.size = size;
    if(it.style !== undefined){ const f = cleanTextStyleEntry('note', it.style, { n: 0 }); if(f) out.style = f; }
    return out;
  }
  // Paste into the Notes column from the earliest highlighted Notes cell down, one Notes cell per line; one line
  // over several highlighted Notes cells fills each of them (Excel). Ruling Q3: it replaces what is there. Lines
  // past the last week shown are not pasted, and the grid says so.
  function wfNotesPaste(text, rich, keys){
    const weeks = wfSelNoteWeeks(keys);
    if(!weeks.length){ flashTextSel('Paste goes into the Notes column'); return false; }
    const norm = wfClipNormal(text);
    const own = (rich && typeof rich.text === 'string' && wfClipNormal(rich.text) === norm) ? rich
              : (wfNoteClip && wfClipNormal(wfNoteClip.text) === norm ? wfNoteClip : null);
    let items = (own && Array.isArray(own.items) && own.items.length) ? own.items.map(wfCleanClipItem) : null;
    if(items && items.some(it => !it)) items = null;
    const look = !!items;
    if(!items) items = parseClipText(norm).map(t => ({ text: t }));
    if(!items.length) return false;
    const seq = wfNoteSeq();
    let pairs = [], dropped = 0;
    if(items.length === 1 && weeks.length > 1) pairs = weeks.map(w => [w, items[0]]);
    else {
      const s = seq.indexOf(weeks[0]);
      items.forEach((it, i)=>{ if(s >= 0 && s + i < seq.length) pairs.push([seq[s + i], it]); else dropped++; });
    }
    if(!pairs.length) return false;
    wfNoteStep(()=> pairs.forEach(([w, it]) => wfPutNote(w, it, look)));
    wfHighlightWeeks(pairs.map(p => p[0]));
    if(dropped) flashTextSel(dropped === 1 ? '1 line did not fit after the last week' : dropped + ' lines did not fit after the last week');
    return true;
  }

  // ---- The one message: why a paste or a drop did not do everything ----
  // A move that works says nothing (the swap chip's rule, owner 21 Oct 2026); only a refusal speaks. Drawn by
  // redrawTextSel on the highlight's layer, above the active cell, so the next render cannot orphan it.
  let textSelFlash = '';
  let _textSelFlashTimer = 0;
  function flashTextSel(msg, ms){
    if(_textSelFlashTimer) clearTimeout(_textSelFlashTimer);
    textSelFlash = msg || '';
    _textSelFlashTimer = textSelFlash ? setTimeout(()=>{ _textSelFlashTimer = 0; textSelFlash = ''; redrawTextSel(null); }, ms || 4200) : 0;
    redrawTextSel(null);
  }
  // Drawn into the highlight's layer after its boxes: where a dragged note would land, and the message.
  function drawWfNoteOverlay(L, idx, wr, z){
    const box = (c, cls)=>{
      const r = c.getBoundingClientRect(), d = document.createElement('div');
      d.className = cls;
      d.style.left = (r.left - wr.left) / z + 'px';
      d.style.top = (r.top - wr.top) / z + 'px';
      d.style.width = Math.max(1, r.width / z) + 'px';
      d.style.height = Math.max(1, r.height / z) + 'px';
      L.body.appendChild(d);
      return r;
    };
    const drop = wfNoteDrag && wfNoteDrag.drop;
    if(drop && drop.ok && drop.off){
      drop.to.forEach(w=>{ const c = idx.get('note:' + w); if(c) box(c, 'text-sel-drop'); });
    }
    if(!textSelFlash) return;
    const at = idx.get(textSelActive) || idx.get([...textSel][0]);
    if(!at) return;
    const r = at.getBoundingClientRect();
    const chip = document.createElement('div');
    chip.className = 'text-sel-chip';
    chip.textContent = textSelFlash;
    chip.style.left = Math.max(0, (r.left - wr.left) / z) + 'px';
    L.body.appendChild(chip);
    const h = chip.offsetHeight;
    const top = (r.top - wr.top) / z - h - 4;
    chip.style.top = (top >= 2 ? top : (r.bottom - wr.top) / z + 4) + 'px';
  }

  // ---- Dragging notes to another week ----
  // Begun by the highlight's own pointer gesture (above) on a highlighted note that shows text. Every
  // highlighted note with text moves, by the same number of Notes cells, so a block keeps its spacing. A shield
  // owns the cursor (the month drag's), and the copy in the hand is the month drag's ghost.
  function wfNoteDragBegin(cell, startKey, x, y){
    const grab = splitTextKey(startKey)[1];
    const weeks = wfSelNoteWeeks().filter(wfNoteShows);
    if(!weeks.includes(grab)) return false;
    const shield = document.createElement('div');
    shield.className = 'mv-drag-shield';
    document.body.appendChild(shield);
    const sel = window.getSelection && window.getSelection();
    if(sel) sel.removeAllRanges();
    wfNoteDrag = { weeks, grab, x0: x, y0: y, x, y, ghost: mvDragGhost(cell), shield, drop: null, raf: 0 };
    return true;
  }
  // Where the notes would land with the pointer here: only on a Notes cell, every note on a week shown.
  function wfDropAt(x, y){
    const d = wfNoteDrag;
    const cell = hitTextCell(x, y);
    if(!d || !cell || !cell.matches('td.sheet-note-cell[data-week]')) return null;
    const seq = wfNoteSeq(), off = seq.indexOf(cell.dataset.week) - seq.indexOf(d.grab);
    const to = d.weeks.map(w => seq[seq.indexOf(w) + off]);
    return { off, to, ok: to.every(Boolean) };
  }
  function wfNoteDragMove(x, y){
    const d = wfNoteDrag;
    if(!d) return;
    d.x = x; d.y = y;
    d.ghost.moveBy(x - d.x0, y - d.y0);
    d.drop = wfDropAt(x, y);
    redrawTextSel(null);
    wfDragAutoScroll();
  }
  // Held near the top or bottom of the grid's pane, the pane scrolls, faster the further past the edge (the
  // shield takes the wheel, so this is how a note reaches a week out of sight). One frame at a time.
  function wfDragAutoScroll(){
    const d = wfNoteDrag;
    if(!d || d.raf) return;
    const tick = ()=>{
      d.raf = 0;
      if(wfNoteDrag !== d) return;
      const sc = document.querySelector('#table-wrap .sheet-scroll');
      if(!sc) return;
      const s = sc.getBoundingClientRect(), z = sc.currentCSSZoom || 1;
      const top = Math.max(s.top, sheetHeadBottom(sc));
      const bottom = s.top + sc.clientHeight * z, EDGE = 28;
      const v = d.y < top + EDGE ? -Math.min(24, Math.ceil((top + EDGE - d.y) / 3))
              : d.y > bottom - EDGE ? Math.min(24, Math.ceil((d.y - bottom + EDGE) / 3)) : 0;
      if(!v) return;
      const was = sc.scrollTop;
      sc.scrollTop += v / z;
      if(sc.scrollTop === was) return;
      d.drop = wfDropAt(d.x, d.y);
      redrawTextSel(null);
      d.raf = requestAnimationFrame(tick);
    };
    d.raf = requestAnimationFrame(tick);
  }
  // Let go: the notes move, one undo step. Ruling Q4 ("Ask before replacing"): weeks that already show a note,
  // other than the moving notes' own, are named in ONE question first; Cancel leaves everything as it was. A drop
  // off the Notes column, on the notes' own place, or with Escape (`cancel`) changes nothing and banks nothing.
  async function wfNoteDragEnd(cancel){
    const d = wfNoteDrag;
    if(!d) return;
    wfNoteDrag = null;
    if(d.raf) cancelAnimationFrame(d.raf);
    d.ghost.remove();
    d.shield.remove();
    const drop = cancel ? null : d.drop;
    redrawTextSel(null);
    if(!drop || !drop.off) return;
    if(!drop.ok){ flashTextSel('Not enough weeks below for all of those notes'); return; }
    const from = d.weeks, to = drop.to, items = from.map(wfNoteItem);
    const leaving = new Set(from);
    const hit = to.filter(w => !leaving.has(w) && wfNoteShows(w));
    if(hit.length){
      const ok = await uiConfirm(hit.length === 1 ? 'That week already has a note. Replace it?'
                                 : hit.length + ' of those weeks already have a note. Replace them?',
                                 { title: 'Replace notes?', confirmLabel: 'Replace' });
      // Under the question the calendar can change (an undo is held off, but a Load is not): move only onto
      // weeks still shown, and only notes still as they were when the drag began.
      if(!ok) return;
      const seq = new Set(wfNoteSeq());
      if(!to.every(w => seq.has(w)) || from.some((w, i) => wfNoteItem(w).text !== items[i].text)) return;
    }
    wfNoteStep(()=>{
      from.forEach(wfClearNote);
      to.forEach((w, i) => wfPutNote(w, items[i], true));
    });
    wfHighlightWeeks(to, to[from.indexOf(d.grab)]);
  }

  // ---- The keys ----
  // Focus on <body> only (the gridSel keyboard rule: a focused control owns its keys), the note editor closed, no
  // dialog up, and never with ⌘, Ctrl or Alt held: ⌘/Ctrl+arrow belongs to the browser, Alt+arrow to the column
  // swap. Capture, beside the Enter/typing listener above, which never claims these keys.
  document.addEventListener('keydown', e=>{
    if(wfNoteDrag && e.key === 'Escape'){ e.preventDefault(); wfNoteDragEnd(true); return; }
    if(viewMode !== 'sheet' || !textSel.size || activeNoteEditor || wfNoteDrag) return;
    const a = document.activeElement;
    if(a && a !== document.body) return;
    if(e.metaKey || e.ctrlKey || e.altKey || appDialogOpen()) return;
    const ARROWS = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
    if(ARROWS[e.key] || e.key === 'Tab'){
      // ⛔ Tab is claimed while something is highlighted, at the grid's edge too, so it never jumps focus out to
      // the toolbar mid-move. Escape clears the highlight and gives Tab back to the page.
      e.preventDefault();
      if(e.key === 'Tab') moveTextSel(e.shiftKey ? 'left' : 'right', false);
      else moveTextSel(ARROWS[e.key], e.shiftKey);
      return;
    }
    if(e.key === 'Delete' || e.key === 'Backspace'){
      if(!wfSelNoteWeeks().length) return;
      e.preventDefault();
      wfNotesClear();
    }
  }, true);

  // ---- The clipboard ----
  // Through the browser's own copy / cut / paste events, which need no permission prompt (navigator.clipboard's
  // read does). Only while the highlight would take them: the waterfall showing, focus on the page itself, the
  // note editor closed, no dialog up, and no text selected anywhere (text selected in the app copies as it always
  // has).
  function wfClipReady(){
    if(viewMode !== 'sheet' || !textSel.size || activeNoteEditor || wfNoteDrag || appDialogOpen()) return false;
    const a = document.activeElement;
    if(a && a !== document.body) return false;
    const s = window.getSelection && window.getSelection();
    return !(s && !s.isCollapsed && String(s).trim());
  }
  // The "before" events: how a page says it takes Copy / Cut / Paste with nothing selected and nothing editable,
  // which is what makes Chrome call those commands ENABLED. ⚠️ MEASURED NOT NEEDED FOR THE KEYS: Chrome runs a key
  // binding's Copy, Cut and Paste even while they are disabled, precisely so the clipboard events fire
  // (wfkeysreal.mjs passes, trusted ⌘C / ⌘X / ⌘V, with these three removed). Kept as insurance for what reads the
  // ENABLED state -- the installed app's native Edit menu, NOT measured (headless Chrome has no menus) -- and
  // cancelled exactly when the event after it would be handled.
  document.addEventListener('beforecopy', e=>{ if(wfClipReady() && wfSelNoteWeeks().length) e.preventDefault(); });
  document.addEventListener('beforecut', e=>{ if(wfClipReady() && wfSelNoteWeeks().length) e.preventDefault(); });
  document.addEventListener('beforepaste', e=>{ if(wfClipReady()) e.preventDefault(); });
  function wfClipWrite(e, clip){
    e.preventDefault();
    e.clipboardData.setData('text/plain', clip.text);
    try { e.clipboardData.setData(WF_CLIP_TYPE, JSON.stringify(clip)); } catch(_){}
  }
  document.addEventListener('copy', e=>{
    if(!wfClipReady() || !e.clipboardData) return;
    const clip = wfNotesCopy();
    if(clip) wfClipWrite(e, clip);
  });
  document.addEventListener('cut', e=>{
    if(!wfClipReady() || !e.clipboardData) return;
    const clip = wfNotesCut();
    if(clip) wfClipWrite(e, clip);
  });
  document.addEventListener('paste', e=>{
    if(!wfClipReady() || !e.clipboardData) return;
    e.preventDefault();
    let rich = null;
    try { rich = JSON.parse(e.clipboardData.getData(WF_CLIP_TYPE) || 'null'); } catch(_){ rich = null; }
    wfNotesPaste(e.clipboardData.getData('text/plain'), isPlainObj(rich) ? rich : null);
  });

  // ---- Header lines as a target (D3: every mode; D4: the month header too) ----
  // A Manual line takes the caret, and the strip's own focusin sets hdrFmtTarget (above). An Auto or Template
  // line is not editable, so a click picks it. ⛔ The ring is a class on the line, an outline (no layout), and
  // re-applied after every render; #print-root renders its own lines and a shareable copy empties #table-wrap,
  // so it can never print.
  function markHdrTarget(){
    document.querySelectorAll('#table-wrap .hdr-line.is-style-target').forEach(el => el.classList.remove('is-style-target'));
    if(styleTarget !== 'hdr' || !hdrFmtTarget) return;
    const el = document.querySelector('#table-wrap ' + (hdrFmtTarget.mv ? `[data-mvhid="${hdrFmtTarget.id}"]` : `[data-hid="${hdrFmtTarget.id}"]`));
    if(el && !el.isContentEditable) el.classList.add('is-style-target');
  }
  document.getElementById('table-wrap').addEventListener('click', e=>{
    const line = hdrLineFromEvent(e.target);
    if(!line) return;
    if((line.mv && viewMode !== 'month') || (!line.mv && viewMode !== 'sheet')) return;
    hdrFmtTarget = { id: line.id, mv: line.mv };
    setStyleTarget('hdr');
  });
  // The target line must still be on screen, in the view showing.
  function hdrTargetLive(){
    if(!hdrFmtTarget) return false;
    if(hdrFmtTarget.mv !== (viewMode === 'month')) return false;
    return !!document.querySelector('#table-wrap ' + (hdrFmtTarget.mv ? `[data-mvhid="${hdrFmtTarget.id}"]` : `[data-hid="${hdrFmtTarget.id}"]`));
  }
  new MutationObserver(()=>{
    if(styleTarget === 'hdr' && !hdrTargetLive()) setStyleTarget(null);
    else { markHdrTarget(); syncStyleBar(); }
  }).observe(document.getElementById('table-wrap'), { childList: true });

  // ---- The target, and the bar ----
  function setStyleTarget(kind){
    if(kind !== 'grid' && textSel.size) clearTextSel();
    if(kind !== 'side' && sideFmtTarget) sideFmtTarget = null;
    styleTarget = kind;
    markHdrTarget();
    syncStyleBar();
  }
  // What the target looks like now, as the controls must show it. Grid text reads its own style over each
  // kind's default look (dates and headings are bold, everything centred); a mixed highlight reports which
  // looks are mixed, so the bar can half-light them.
  const TEXT_DEFAULT_BOLD = { date: true, heading: true };
  function textEffective(kind, key){
    const f = textStyleOf(kind, key) || {};
    const size = (kind === 'note') ? noteFontSizeFor(key) : (kind === 'hiatus') ? hiatusFontSizeFor(key) : f.size;
    return {
      size: size,
      bold: f.bold !== undefined ? f.bold : !!TEXT_DEFAULT_BOLD[kind],
      italic: !!f.italic,
      color: f.color || '',
      align: f.align || 'center',
      styled: !!(textStyleOf(kind, key) || size !== undefined),
    };
  }
  function styleBarLook(){
    if(styleTarget === 'hdr' && hdrTargetLive()){
      const f = headerFmt(hdrFmtTarget.id, hdrFmtTarget.mv), look = hdrLiveLook(hdrFmtTarget.id, hdrFmtTarget.mv);
      return { sizes: hdrFmtTarget.mv ? STYLE_BAR_SIZES.hdrMonth : STYLE_BAR_SIZES.hdr, highlight: true,
               size: f.size, bold: look.bold, italic: look.italic, color: f.color || '', hl: f.highlight || '',
               align: f.align || headerDefaultAlign(hdrFmtTarget.id, hdrFmtTarget.mv), alignSet: !!f.align, mixed: {} };
    }
    if(styleTarget === 'side' && sideFmtTarget){
      const t = sideTargetFmt();
      if(!t) return null;
      const eff = Object.assign({}, t.base, t.f);
      return { sizes: STYLE_BAR_SIZES.side, highlight: true, size: t.f.size, bold: !!eff.bold, italic: !!eff.italic,
               color: t.f.color || '', hl: t.f.highlight || '', align: eff.align || 'left', alignSet: !!t.f.align, mixed: {} };
    }
    if(styleTarget === 'grid'){
      const keys = textSelTargets();
      if(!keys.length) return null;
      const looks = keys.map(k => textEffective(...splitTextKey(k)));
      const same = p => looks.every(l => l[p] === looks[0][p]);
      const mixed = { size: !same('size'), bold: !same('bold'), italic: !same('italic'), color: !same('color'), align: !same('align') };
      return { sizes: STYLE_BAR_SIZES.grid, highlight: false,
               size: mixed.size ? undefined : looks[0].size, bold: looks.every(l => l.bold), italic: looks.every(l => l.italic),
               color: mixed.color ? '' : looks[0].color, hl: '', align: mixed.align ? '' : looks[0].align,
               alignSet: looks.some(l => l.align !== 'center'), mixed };
    }
    return null;
  }
  function buildStyleBar(){
    const bar = document.createElement('div');
    bar.className = 'style-bar';
    bar.setAttribute('role', 'toolbar');
    bar.setAttribute('aria-label', 'Text style');
    bar.innerHTML = `<select class="hf-ctl hf-size" title="Text size" aria-label="Text size"><option value="">Size</option></select>
      <button type="button" class="hf-ctl hf-btn hf-b" title="Bold" aria-label="Bold"><b>B</b></button>
      <button type="button" class="hf-ctl hf-btn hf-i" title="Italic" aria-label="Italic"><i>I</i></button>
      <label class="hf-ctl hf-swatch" title="Text color"><span class="hf-swatch-ink">A</span>
        <input type="color" class="hf-color" value="#000000" aria-label="Text color"></label>
      <label class="hf-ctl hf-swatch hf-swatch-hl" title="Highlight color"><span class="hf-swatch-ink">A</span>
        <input type="color" class="hf-hl" value="#ffff00" aria-label="Highlight color"></label>
      ${alignMenuHtml()}
      <button type="button" class="hf-ctl hf-btn hf-clear" title="Clear formatting" aria-label="Clear formatting">&#8709;</button>`;
    // A press on the bar must not end a side box's edit (onSideFocusout, the outside-mousedown hide).
    bar.addEventListener('pointerdown', ()=>{ sideFmtPressing = true; }, true);
    // Buttons keep the caret where it is (a Manual header line, a box line); the select and the colour wells
    // need their own default behaviour, the header strip's rule.
    bar.addEventListener('mousedown', e=>{ if(e.target.closest('.hf-btn')) e.preventDefault(); });
    bar.addEventListener('click', e=>{
      const look = styleBarLook();
      if(!look) return;
      if(e.target.closest('.hf-b')) return styleBarApply({ bold: !look.bold });
      if(e.target.closest('.hf-i')) return styleBarApply({ italic: !look.italic });
      if(e.target.closest('.hf-clear')) return styleBarClear();
      const toggle = e.target.closest('.hf-al-toggle');
      if(toggle){
        const menu = bar.querySelector('.hf-al-menu');
        menu.hidden = !menu.hidden;
        toggle.setAttribute('aria-expanded', menu.hidden ? 'false' : 'true');
        return;
      }
      const opt = e.target.closest('.hf-al-opt');
      if(opt){
        bar.querySelector('.hf-al-menu').hidden = true;
        bar.querySelector('.hf-al-toggle').setAttribute('aria-expanded', 'false');
        // Picking the alignment a text already has returns it to its default, as both old bars did.
        return styleBarApply({ align: (look.alignSet && look.align === opt.dataset.align) ? '' : opt.dataset.align });
      }
    });
    bar.addEventListener('input', e=>{
      if(e.target.classList.contains('hf-color')) styleBarApply({ color: e.target.value }, true);
      if(e.target.classList.contains('hf-hl')) styleBarApply({ highlight: e.target.value }, true);
    });
    bar.addEventListener('change', e=>{
      if(e.target.classList.contains('hf-size')) return styleBarApply({ size: e.target.value ? Number(e.target.value) : '' });
      if(e.target.classList.contains('hf-color') || e.target.classList.contains('hf-hl')){
        // The drag is over: bank it. The side boxes do this inside applySideFmt's own live mode.
        if(styleTarget === 'side'){ sideFmtLive = false; cancelPendingUndoPush(); pushUndoSnapshot(); }
        if(styleTarget === 'grid' && styleBarLive){ styleBarLive = false; cancelPendingUndoPush(); pushUndoSnapshot(); }
      }
    });
    return bar;
  }
  function syncStyleBar(){
    if(!styleBar) return;
    const look = styleBarLook();
    styleBar.classList.toggle('has-target', !!look);
    const q = s => styleBar.querySelector(s);
    const sel = q('.hf-size');
    const sizes = look ? look.sizes.slice() : STYLE_BAR_SIZES.grid.slice();
    // A size the list does not offer (a note sized 14 in the note editor before the bar) still shows.
    if(look && look.size && !sizes.includes(look.size)) sizes.push(look.size);
    sizes.sort((a, b) => a - b);
    const want = '<option value="">Size</option>' + sizes.map(s => `<option value="${s}">${s}</option>`).join('');
    if(sel.dataset.opts !== want){ sel.innerHTML = want; sel.dataset.opts = want; }
    sel.value = (look && look.size) ? String(look.size) : '';
    const m = (look && look.mixed) || {};
    q('.hf-b').classList.toggle('is-on', !!(look && look.bold));
    q('.hf-b').classList.toggle('is-mixed', !!m.bold);
    q('.hf-i').classList.toggle('is-on', !!(look && look.italic));
    q('.hf-i').classList.toggle('is-mixed', !!m.italic);
    q('.hf-color').value = (look && look.color) || '#000000';
    q('.hf-swatch-hl').hidden = !(look && look.highlight);
    q('.hf-hl').value = (look && look.hl) || '#ffff00';
    const al = (look && look.align) || 'center';
    const toggle = q('.hf-al-toggle');
    toggle.innerHTML = alignIcon(al) + '<span class="hf-caret">▾</span>';
    toggle.classList.toggle('is-on', !!(look && look.alignSet));
    toggle.classList.toggle('is-mixed', !!m.align);
    styleBar.querySelectorAll('.hf-al-opt').forEach(o=>{
      const on = !!look && !m.align && o.dataset.align === al;
      o.classList.toggle('is-on', on);
      o.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  }
  function styleBarApply(patch, live){
    if(styleTarget === 'hdr' && hdrTargetLive()){ applyHdrFmt(patch); markHdrTarget(); return; }
    if(styleTarget === 'side' && sideFmtTarget){ applySideFmt(patch, live); return; }
    if(styleTarget === 'grid') applyGridTextStyle(patch, live);
  }
  function styleBarClear(){
    if(styleTarget === 'hdr' && hdrTargetLive()){ clearHdrFmt(); markHdrTarget(); return; }
    if(styleTarget === 'side' && sideFmtTarget){ applySideFmt(null); return; }
    if(styleTarget === 'grid') applyGridTextStyle(null);
  }
  // Grid text: write each highlighted text's style (patch === null clears it, size included), then ONE render
  // and ONE undo step -- batchFill's shape (a flush push, the writes, a trailing push). A colour well being
  // dragged writes and renders on each move and is banked once, on its change (styleBarLive).
  function applyGridTextStyle(patch, live){
    const keys = textSelTargets();
    if(!keys.length) return;
    if(live){ if(!styleBarLive){ styleBarLive = true; cancelPendingUndoPush(); pushUndoSnapshot(); } }
    else pushUndoSnapshot();
    keys.forEach(k=>{
      const [kind, key] = splitTextKey(k);
      const sizeStore = kind === 'note' ? noteFontSize : kind === 'hiatus' ? hiatusFontSize : null;
      if(patch === null){
        delete textStyle[kind][key];
        if(sizeStore) delete sizeStore[key];
        return;
      }
      const rest = Object.assign({}, patch);
      // A note's or a band's size lives in its own store (§5), where 11, the default, is stored as nothing.
      if(sizeStore && 'size' in rest){
        if(rest.size === '' || rest.size == null || rest.size === 11) delete sizeStore[key]; else sizeStore[key] = rest.size;
        delete rest.size;
      }
      if('size' in rest && rest.size === 11) rest.size = '';
      // A bold that matches the kind's own look is no override (dates and headings are bold already).
      if('bold' in rest && rest.bold === !!TEXT_DEFAULT_BOLD[kind]) rest.bold = '';
      if('italic' in rest && rest.italic === false) rest.italic = '';
      if('align' in rest && rest.align === 'center') rest.align = '';
      if(!Object.keys(rest).length) return;
      const cur = Object.assign({}, textStyle[kind][key] || {}, rest);
      Object.keys(cur).forEach(p=>{ if(cur[p] === '' || cur[p] == null) delete cur[p]; });
      if(Object.keys(cur).length) textStyle[kind][key] = cur; else delete textStyle[kind][key];
    });
    render(currentSchedule);
    if(!live){ pushUndoSnapshot(); }
    markDirty();
    if(!live) cancelPendingUndoPush();
    syncStyleBar();
  }
  if(document.querySelector('.style-bar-host')){
    styleBar = buildStyleBar();
    document.querySelector('.style-bar-host').appendChild(styleBar);
    syncStyleBar();
  }
  // The bar's alignment menu closes on any press elsewhere, as the strip's does (registered on document).
  document.addEventListener('click', e=>{
    if(!styleBar || (e.target.closest && e.target.closest('.style-bar .hf-align-wrap'))) return;
    const menu = styleBar.querySelector('.hf-al-menu');
    if(menu && !menu.hidden){ menu.hidden = true; styleBar.querySelector('.hf-al-toggle').setAttribute('aria-expanded', 'false'); }
  });

  // ---------- The header template EDITOR (owner request, 9 Sep 2026) ----------
  //
  // A dedicated pop-up for BUILDING a header, as opposed to tweaking one. The in-place editing on
  // the calendar stays and is still the right tool for changing one line; this is for laying out all
  // of them, which the header bar cannot do -- it shows one line at a time, in a cramped strip, with
  // the raw/resolved swap happening under you, so you can never see the shape of what you are making.
  //
  // ⭐ THE LIVE HEADER IS THE CANVAS, not a preview. Click a line to select it, type in it, style it
  // with the bar above. That is the owner's ask and it is also the right model: a preview you cannot
  // touch makes you edit in one place and judge in another.
  //
  // ⛔ NOT ONE id ON ANYTHING IN HERE. collectFieldValues() sweeps every input[id]/select[id]/
  // textarea[id] in the DOCUMENT into every saved calendar and adds an undo step per change. This
  // panel is body-level -- outside .prefs-card, where the class exclusion does not reach -- and it
  // contains ten text inputs and a select. With ids, every one of them would be baked into every
  // .sptcal from the moment this shipped. Classes only, and the hdreditor leg asserts it.
  //
  // ⛔ IT IS NOT A SECOND RENDERER. Every value on screen comes from buildHeaderCtx() +
  // resolveHeaderTemplate() -- the same pair headerLine() uses for the screen, the workbook and the
  // PDF. If this panel resolved its own way it would eventually disagree with what prints, which is
  // exactly the divergence the one-choke-point design exists to prevent.
  //
  // ⛔ IT WRITES THROUGH THE SAME STORES. headerManual and headerFormat, then render() -- no private
  // copy of the header, so the panel and the calendar behind it cannot drift.

  // A token with nothing to say renders as a bracketed stand-in HERE ONLY, so a header can be laid
  // out on a calendar that has no dates in it yet. ⛔ It never reaches the real header: the trick is
  // a modified CTX rather than a modified resolver, so resolveHeaderTemplate stays untouched and
  // one-pass, and a [group] full of placeholders correctly does NOT collapse in the editor while
  // still collapsing for real.
  const HDR_PH_OPEN = String.fromCharCode(0xE000), HDR_PH_CLOSE = String.fromCharCode(0xE001);   // private-use, cannot occur in user text
  const HDR_PH_NAMES = {
    title:'Show Title', season:'Season', titleSeason:'Show Title S#', version:'Version',
    episodes:'##', shootDaysPerEp:'#', shootDays:'##',
    'production.summary':'Production Span / Shooting Schedule',
    'production.dates':'Principal Photography — / Wrap: —',
    'writersRoom.line':"Writer's Room Opens: —",
  };
  function hdrPlaceholderFor(name, ctx){
    if(HDR_PH_NAMES[name]) return HDR_PH_NAMES[name];
    const base = String(name).split(':')[0];
    if(HDR_PH_NAMES[base]) return HDR_PH_NAMES[base];
    const bits = base.split('.');
    if(bits.length === 2){
      const phase = (ctx.tokens[bits[0] + '.name'] || bits[0]);
      const what = { open:'Opens', close:'Closes', wrap:'Wrap', weeks:'# wks', name:'Phase' }[bits[1]] || bits[1];
      return phase + ' ' + what;
    }
    return base;
  }
  function hdrCtxWithPlaceholders(ctx){
    const t = {};
    Object.keys(ctx.tokens).forEach(k=>{
      const v = ctx.tokens[k];
      t[k] = (v === '' || v == null) ? (HDR_PH_OPEN + hdrPlaceholderFor(k, ctx) + HDR_PH_CLOSE) : v;
    });
    return { tokens: t };
  }
  // Escape for innerHTML, then mark the placeholders. Two steps, because the marker has to survive
  // escaping and the text must not.
  function hdrEditorHtml(s){
    const esc = String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    return esc.split(HDR_PH_OPEN).map((chunk, i)=>{
      if(!i) return chunk;
      const end = chunk.indexOf(HDR_PH_CLOSE);
      if(end < 0) return chunk;
      return '<span class="hde-ph">' + chunk.slice(0, end) + '</span>' + chunk.slice(end + 1);
    }).join('');
  }

  // ⛔ EMPTY IS A VALID ANSWER HERE, and that is the point. This used to always say something --
  // "Empty lines show a dotted box so you can click them" -- which explained a dotted box that
  // already looks exactly like a thing you click. Removed 9 Sep 2026 at the owner's request. What
  // survives is the one line that explains something genuinely unguessable: why words the user
  // never typed are appearing in their header. It shows ONLY when such a word is on screen.
  function hdrEditorFootText(sawPh){
    return sawPh ? 'Dashed words are placeholders — they are not printed.' : '';
  }
  // The <p> keeps its margin when empty, so hide it rather than blanking it.
  function setHdrEditorFoot(root, sawPh){
    const p = root.querySelector('.hde-stage-foot');
    const t = hdrEditorFootText(sawPh);
    p.textContent = t;
    p.hidden = !t;
  }

  let hdrEditor = null;   // { root, selected, editing, placeholders }

  function closeHeaderEditor(){
    if(!hdrEditor) return;
    document.removeEventListener('keydown', onHeaderEditorKey, true);
    hdrEditor.root.remove();
    hdrEditor = null;
    closeHdrTokenPop();
  }
  function onHeaderEditorKey(e){
    // Escape closes -- unless a line is being edited, where it should abandon that edit first.
    if(e.key !== 'Escape' || !hdrEditor) return;
    if(hdrEditor.editing){ hdrEditor.editing = null; paintHeaderEditor(); e.stopPropagation(); return; }
    closeHeaderEditor();
    e.stopPropagation();
  }

  // ---------- The editor is ONE editor, retargeted by view (owner ruling 3, 21 Sep 2026) ----------
  //
  // Not a second editor. Its Insert rail is token-driven and the tokens are already view-agnostic,
  // so the only things that differ between the two headers are WHICH STORES it reads and writes and
  // WHICH SLOTS it lays out. These four accessors are that difference, in full -- every other line
  // of the editor is shared. ⭐ The same shape headerFmt(id, mv) / headerFormatCss(f, id, mv) /
  // headerFmtToolbarHtml(mv) already use, so the `mv` flag threads all the way through.
  function hdeMv(){ return !!(hdrEditor && hdrEditor.mv); }
  function hdeLines(){ return hdeMv() ? mvHeaderManual : headerManual; }
  function hdeIds(){ return hdeMv() ? MV_HDR_IDS : HDR_IDS; }
  function hdeFormats(){ return hdeMv() ? mvHeaderFormat : headerFormat; }

  // The month's slot layout. Its header is one row -- a fixed left box, a centred title with an
  // optional subtitle under it, and the date -- so "columns" here is Left / Centre / Right with the
  // subtitle grouped under the title it belongs to.
  const MV_HDR_EDITOR_COLUMNS = [
    { key:'left',  label:'Left',   ids:['tleft'] },
    { key:'mid',   label:'Centre', ids:['title','subtitle'] },
    { key:'right', label:'Right',  ids:['today'] },
  ];

  // Which slots the editor shows. Three per column, plus any LEGACY slot that this particular
  // calendar is actually using -- see HDR_EDITOR_COLUMNS for why c4 is handled that way.
  function hdrEditorSlots(){
    if(hdeMv()) return MV_HDR_EDITOR_COLUMNS.map(c=>({ key:c.key, label:c.label, ids:c.ids.slice() }));
    const cols = HDR_EDITOR_COLUMNS.map(c=>({ key:c.key, label:c.label, ids:c.ids.slice() }));
    HDR_LEGACY_SLOTS.forEach(id=>{
      if((headerManual[id] || '').trim()){
        const mid = cols.find(c=>c.key === 'mid');
        if(mid) mid.ids.push(id);
      }
    });
    return cols;
  }

  function paintHeaderEditor(){
    if(!hdrEditor) return;
    const root = hdrEditor.root;
    const ctx = buildHeaderCtx(currentSchedule);
    const phCtx = hdrCtxWithPlaceholders(ctx);
    const usePh = hdrEditor.placeholders;
    let sawPh = false;

    // ---- the live header ----------------------------------------------------------------------
    const stage = root.querySelector('.hde-sheet');
    stage.innerHTML = '';
    hdrEditorSlots().forEach(col=>{
      const host = document.createElement('div');
      host.className = 'hde-col hde-col-' + col.key;
      col.ids.forEach(id=>{
        const raw = (id in hdeLines()) ? hdeLines()[id] : '';
        const real = resolveHeaderTemplate(raw, ctx);
        const shown = usePh ? resolveHeaderTemplate(raw, phCtx) : real;
        if(shown !== real) sawPh = true;
        const el = document.createElement('div');
        el.className = 'hde-line' + (hdrEditor.selected === id ? ' is-sel' : '') +
                       (real ? '' : ' is-blank') + (HDR_LEGACY_SLOTS.indexOf(id) >= 0 ? ' is-legacy' : '');
        el.dataset.hid = id;
        el.contentEditable = 'true';
        el.spellcheck = false;
        el.setAttribute('style', headerFormatCss(headerFmt(id, hdeMv()), id, hdeMv()));
        if(hdrEditor.editing === id){ el.classList.add('is-editing'); el.textContent = raw; }
        else el.innerHTML = shown ? hdrEditorHtml(shown) : '';
        host.appendChild(el);
      });
      stage.appendChild(host);
    });
    setHdrEditorFoot(root, sawPh);

    // ---- the template list ----------------------------------------------------------------------
    const list = root.querySelector('.hde-slots');
    list.innerHTML = '';
    hdrEditorSlots().forEach(col=>{
      const g = document.createElement('div');
      g.className = 'hde-group';
      const gl = document.createElement('div');
      gl.className = 'hde-glabel'; gl.textContent = col.label;
      g.appendChild(gl);
      col.ids.forEach((id, i)=>{
        const row = document.createElement('div');
        row.className = 'hde-row';
        const lab = document.createElement('div');
        lab.className = 'hde-rlabel';
        lab.textContent = HDR_LEGACY_SLOTS.indexOf(id) >= 0 ? (String(i + 1) + '*') : String(i + 1);
        if(HDR_LEGACY_SLOTS.indexOf(id) >= 0) lab.title = 'A fourth centre line this calendar already uses. It is kept so nothing is lost.';
        if(hdeMv()) lab.title = MV_HDR_SLOT_NAMES[id] || id;
        const inp = document.createElement('input');
        inp.type = 'text';
        inp.className = 'hde-tpl' + (hdrEditor.selected === id ? ' is-sel' : '');
        inp.value = (id in hdeLines()) ? hdeLines()[id] : '';
        inp.setAttribute('aria-label', (hdeMv() ? MV_HDR_SLOT_NAMES[id] : HDR_SLOT_NAMES[id]) || id);
        inp.dataset.hid = id;
        row.appendChild(lab); row.appendChild(inp);
        g.appendChild(row);
      });
      list.appendChild(g);
    });

    syncHeaderEditorBar();
    const bud = root.querySelector('.hde-budget');
    // ⛔ THE EXCEL BUDGET IS A WATERFALL FACT AND IT IS HIDDEN IN THE MONTH VIEW, not zeroed.
    // Excel's 255-character cap applies to the WORKBOOK's page header, which only the waterfall
    // writes; the month view's only export is a PDF and it has no such limit. Showing a budget
    // here would be inventing a constraint, and showing "0 of 255" would be worse -- it reads as
    // headroom for a thing that does not exist.
    if(hdeMv()){
      bud.textContent = '';
      bud.classList.remove('is-over');
    } else {
      const b = estimateExcelHeaderLength();
      bud.textContent = 'Excel header: about ' + b.total + ' of ' + b.max + ' characters' +
        (b.over ? ' — too long, the last lines will be dropped' : '.');
      bud.classList.toggle('is-over', !!b.over);
    }
  }

  // The bar REFLECTS the selected line rather than holding state of its own, the same contract
  // syncHdrFmtToolbar() has for the toolbar on the calendar.
  function syncHeaderEditorBar(){
    if(!hdrEditor) return;
    const root = hdrEditor.root, id = hdrEditor.selected;
    const f = id ? headerFmt(id, hdeMv()) : {};
    root.querySelector('.hde-fmt').classList.toggle('is-idle', !id);
    // ⛔ The month's own slot names in the month editor -- HDR_SLOT_NAMES has none of its ids, so the
    // label read "Styling title" (a raw id) instead of "Styling Title".
    const slotName = id ? ((hdeMv() ? MV_HDR_SLOT_NAMES[id] : HDR_SLOT_NAMES[id]) || id) : '';
    root.querySelector('.hde-target').innerHTML = id
      ? 'Styling <b>' + escHtml(slotName) + '</b>'
      : 'Select a header line to style it';
    root.querySelector('.hde-size').value = f.size ? String(f.size) : '';
    // Lit from what the line LOOKS like (hdrLiveLook), the rule the toggles below now flip from.
    const look = id ? hdrLiveLook(id, hdeMv()) : { bold:false, italic:false };
    root.querySelector('.hde-b').classList.toggle('is-on', look.bold);
    root.querySelector('.hde-i').classList.toggle('is-on', look.italic);
    const ink = f.color || '#000000';
    root.querySelector('.hde-ink').value = ink;
    root.querySelector('.hde-ink-bar').style.background = ink;
    const hl = f.highlight || '#FFFF00';
    root.querySelector('.hde-hl').value = hl;
    root.querySelector('.hde-hl-bar').style.background = hl;
    // ⛔ hdeMv(), not false -- the fourth site of the 22 Sep hardcoded-view slip. With `false` the
    // month's alignment buttons lit the WATERFALL's defaults for those ids, so the bar told you a
    // month line was aligned one way while the header showed another.
    const al = f.align || (id ? headerDefaultAlign(id, hdeMv()) : null);
    root.querySelectorAll('.hde-align').forEach(btn=>{
      btn.classList.toggle('is-on', !!id && btn.dataset.align === al);
    });
  }

  // One place that changes a line's FORMAT, and one that changes its TEXT. Both write the same
  // stores the calendar reads, then render() -- so the header behind the panel updates too.
  function hdrEditorFormat(patch){
    if(!hdrEditor || !hdrEditor.selected) return;
    const id = hdrEditor.selected;
    const cur = Object.assign({}, headerFmt(id, hdeMv()), patch);
    Object.keys(cur).forEach(k=>{ if(cur[k] === undefined || cur[k] === null || cur[k] === '') delete cur[k]; });
    // Mutated IN PLACE, never reassigned: hdeFormats() hands back a reference to the live store,
    // and `hdeFormats() = {...}` is not a thing. Same reason hdrEditorSetText writes into hdeLines().
    const fstore = hdeFormats();
    if(Object.keys(cur).length) fstore[id] = cur; else delete fstore[id];
    render(currentSchedule);
    markDirty();
    paintHeaderEditor();
  }
  function hdrEditorSetText(id, text){
    const clean = String(text == null ? '' : text).replace(/\u00a0/g,' ').trim();
    const store = hdeLines();
    if((store[id] || '') === clean) return false;
    store[id] = clean;
    render(currentSchedule);
    markDirty();
    return true;
  }

  // `initialId` selects a slot on the way in -- used when the click came from that very line on the
  // calendar, so the editor opens with the thing you pointed at already selected.
  function openHeaderEditor(initialId, mv){
    if(hdrEditor){ closeHeaderEditor(); return; }
    mv = !!mv;
    // The editor edits TEMPLATES, so it puts the header in Template mode on the way in. From Auto
    // that seeds the built-in default; from Manual it keeps the literal strings, which are valid
    // templates with no tokens. Either way it is the existing transition, and therefore one undo
    // step -- opening the editor is never a silent, unrepeatable change.
    if(mv){
      if(!(mvHeaderMode === 'manual' && mvHeaderTemplates)) setMvHeaderMode('template');
    } else {
      // headerOff too: editing lines that stay hidden would be editing blind. From Off over a
      // Template this only clears the flag (setHeaderMode).
      if(headerOff || !(headerMode === 'manual' && headerTemplates)) setHeaderMode('template');
    }

    const root = document.createElement('div');
    // is-mv lets the stage draw each slot at its own header's default size and weight (legacy.css).
    root.className = 'hde-overlay' + (mv ? ' is-mv' : '');
    root.innerHTML =
      '<div class="hde-panel" role="dialog" aria-modal="true" aria-label="' +
          (mv ? 'Month header template' : 'Header template') + '">' +
        '<div class="hde-head">' +
          // Named by view, because both are reachable and a header that says only "Header template"
          // cannot tell you which of the two documents you are about to change.
          '<h2 class="hde-title">' + (mv ? 'Month header template' : 'Waterfall header template') + '</h2>' +
          '<span class="hde-ctx"></span>' +
          '<button type="button" class="hde-close" aria-label="Close">✕</button>' +
        '</div>' +
        '<div class="hde-fmt is-idle">' +
          '<select class="hde-ctl hde-size" aria-label="Text size" title="Text size">' +
            '<option value="">Size</option>' +
            // The two headers are set at very different sizes -- the month title is 22px where the
            // waterfall's is 13px -- so they offer different ladders. Same list headerFmtToolbarHtml
            // already uses for each view; taken from there rather than restated.
            (mv ? [14,16,18,20,22,26,30] : [8,9,10,11,12,13,14,16,18,22]).map(n=>'<option>' + n + '</option>').join('') +
          '</select>' +
          '<button type="button" class="hde-ctl hde-btn hde-b" title="Bold"><b>B</b></button>' +
          '<button type="button" class="hde-ctl hde-btn hde-i" title="Italic"><i>I</i></button>' +
          '<label class="hde-well" title="Text colour"><span>A</span>' +
            '<i class="hde-ink-bar"></i><input type="color" class="hde-ink" aria-label="Text colour"></label>' +
          '<label class="hde-well" title="Highlight"><span>A</span>' +
            '<i class="hde-hl-bar"></i><input type="color" class="hde-hl" aria-label="Highlight colour"></label>' +
          '<span class="hde-sep"></span>' +
          '<button type="button" class="hde-ctl hde-btn hde-align" data-align="left" title="Align left">⮨</button>' +
          '<button type="button" class="hde-ctl hde-btn hde-align" data-align="center" title="Align centre">≡</button>' +
          '<button type="button" class="hde-ctl hde-btn hde-align" data-align="right" title="Align right">⮩</button>' +
          '<span class="hde-sep"></span>' +
          '<button type="button" class="hde-ctl hde-btn hde-clear" title="Clear formatting on this line">∅</button>' +
          '<span class="hde-target"></span>' +
        '</div>' +
        '<div class="hde-stage">' +
          // ⚠️ "Live header — click a line to edit it" was removed 9 Sep 2026 (owner: "you can get
          // rid of" it). It labelled the most self-evident thing on the screen -- a header, with a
          // cursor, directly under a formatting toolbar -- and every line of chrome here competes
          // with the thing it is describing. The row is kept for the checkbox alone.
          '<div class="hde-stage-label">' +
            '<span class="hde-grow"></span>' +
            '<label class="hde-ph-toggle">'
            // ⛔ NOT .hde-ph -- that is the placeholder MARKER on the canvas. One class for both
            // meant root.querySelector('.hde-ph') found this box only by markup order, and the
            // marker's dashed underline was landing on the checkbox.
            + '<input type="checkbox" class="hde-phbox" checked>' +
            ' Show placeholders for data you have not entered</label></div>' +
          '<div class="hde-sheet-scroll"><div class="hde-sheet"></div></div>' +
          '<p class="hde-stage-foot"></p>' +
        '</div>' +
        '<div class="hde-body">' +
          '<div class="hde-slots-wrap"><div class="hde-slots-head">Templates</div>' +
            '<div class="hde-slots"></div></div>' +
          '<aside class="hde-rail"><div class="hde-rail-head">Insert' +
            '<span>Drops into the line you have selected.</span></div>' +
            '<div class="hde-rail-list"></div></aside>' +
        '</div>' +
        // ⚠️ REWRITTEN 9 Sep 2026: the owner read the old wording and said "im confused what this
        // means", which is the only review that matters for a help string. Three problems, and the
        // third was the worst:
        //   1. It led with the MECHANISM ("square brackets hide everything inside them when a token
        //      in them is empty") -- an abstract conditional, stated before you know why you would
        //      ever want one. It now leads with a concrete before/after and names the rule second.
        //   2. It documented <code>{{</code> / <code>}}</code>, the literal-brace escape. Still
        //      SUPPORTED, still covered by prove-header-template, still specified in
        //      HEADER-PRESETS-PLAN §3.1 -- just not worth a third of the only sentence most people
        //      will read, for a case almost nobody hits.
        //   3. "Anything unrecognised stays exactly as you typed it" is reassurance about a failure
        //      that has not happened yet. It answered a question nobody had while crowding out the
        //      one rule they actually need.
        '<p class="hde-grammar"><code>[{episodes} Episodes]</code> prints “10 Episodes” — or ' +
          'nothing at all, if you haven’t entered an episode count. That’s what the square ' +
          'brackets do: hide the whole chunk when the data inside it is missing.</p>' +
        '<div class="hde-foot">' +
          '<span class="hde-budget"></span><span class="hde-grow"></span>' +
          '<button type="button" class="hde-ctl hde-wide" data-hdrpreset="import">Import preset file…</button>' +
          '<button type="button" class="hde-ctl hde-wide hde-saveas">Save as preset…</button>' +
          '<button type="button" class="hde-ctl hde-wide hde-primary hde-done">Done</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(root);
    hdrEditor = {
      root: root,
      mv: mv,
      // The title line in both views: c1 for the waterfall, title for the month.
      selected: (initialId && (mv ? MV_HDR_IDS : HDR_IDS).indexOf(initialId) >= 0)
        ? initialId : (mv ? 'title' : 'c1'),
      editing: null,
      placeholders: true,
    };
    if(mv) root.classList.add('is-mv');

    const title = (document.getElementById('show-title') || {}).value || '';
    root.querySelector('.hde-ctx').textContent = title ? title : 'Untitled calendar';

    // ---- the canvas ---------------------------------------------------------------------------
    const sheet = root.querySelector('.hde-sheet');
    sheet.addEventListener('mousedown', e=>{
      const el = e.target.closest && e.target.closest('.hde-line');
      if(!el) return;
      if(hdrEditor.selected !== el.dataset.hid){
        hdrEditor.selected = el.dataset.hid; hdrEditor.editing = null; paintHeaderEditor();
      }
    });
    sheet.addEventListener('focusin', e=>{
      const el = e.target.closest && e.target.closest('.hde-line');
      if(!el) return;
      const id = el.dataset.hid;
      if(hdrEditor.editing === id) return;
      // ⭐ Swap to the RAW template while the line has focus, exactly as the header on the calendar
      // does. Without it the first keystroke commits resolved text and the token is gone.
      hdrEditor.selected = id; hdrEditor.editing = id;
      paintHeaderEditor();
      const fresh = sheet.querySelector('.hde-line[data-hid="' + id + '"]');
      if(fresh){
        fresh.focus();
        const r = document.createRange(); r.selectNodeContents(fresh); r.collapse(false);
        const s = window.getSelection(); s.removeAllRanges(); s.addRange(r);
      }
    });
    sheet.addEventListener('focusout', e=>{
      const el = e.target.closest && e.target.closest('.hde-line');
      if(!el || !hdrEditor) return;
      const id = el.dataset.hid;
      if(hdrEditor.editing !== id) return;
      hdrEditorSetText(id, el.textContent);
      hdrEditor.editing = null;
      paintHeaderEditor();
    });
    sheet.addEventListener('keydown', e=>{
      if(e.key === 'Enter'){ e.preventDefault(); if(e.target.blur) e.target.blur(); }
    });

    // ---- the styling bar ------------------------------------------------------------------------
    root.querySelector('.hde-size').addEventListener('change', function(){
      hdrEditorFormat({ size: this.value ? parseInt(this.value, 10) : undefined });
    });
    // ⛔ hdeMv(), not false: these read the CURRENT state to decide which way to flip, so with a
    // hardcoded waterfall lookup the month editor's Bold and Italic toggled against the WATERFALL's
    // format -- a month line already bold would un-bold on the first click only if the waterfall's
    // matching slot happened to be bold too. Same class of miss as the repaint's format store.
    // ⛔ AND FROM THE LIVE LOOK, not the store (owner report, 24 Sep 2026). `!stored.bold` turned the
    // month title -- bold by default -- "bold" on the first click, which changed nothing anyone could
    // see; only a second click un-bolded it. The calendar's own toolbar has always flipped from the
    // rendered weight; hdrLiveLook() is that rule, shared.
    root.querySelector('.hde-b').addEventListener('click', ()=>{
      if(!hdrEditor.selected) return;
      hdrEditorFormat({ bold: !hdrLiveLook(hdrEditor.selected, hdeMv()).bold });
    });
    root.querySelector('.hde-i').addEventListener('click', ()=>{
      if(!hdrEditor.selected) return;
      hdrEditorFormat({ italic: !hdrLiveLook(hdrEditor.selected, hdeMv()).italic });
    });
    root.querySelector('.hde-ink').addEventListener('input', function(){ hdrEditorFormat({ color: this.value }); });
    root.querySelector('.hde-hl').addEventListener('input', function(){ hdrEditorFormat({ highlight: this.value }); });
    root.querySelectorAll('.hde-align').forEach(btn=>{
      btn.addEventListener('click', ()=> hdrEditorFormat({ align: btn.dataset.align }));
    });
    root.querySelector('.hde-clear').addEventListener('click', ()=>{
      if(!hdrEditor.selected) return;
      delete hdeFormats()[hdrEditor.selected];
      render(currentSchedule); markDirty(); paintHeaderEditor();
    });

    // ---- the template list ------------------------------------------------------------------------
    const slots = root.querySelector('.hde-slots');
    slots.addEventListener('focusin', e=>{
      const inp = e.target.closest && e.target.closest('.hde-tpl');
      if(!inp) return;
      hdrEditor.selected = inp.dataset.hid; hdrEditor.editing = null;
      syncHeaderEditorBar();
      slots.querySelectorAll('.hde-tpl').forEach(o=>o.classList.toggle('is-sel', o === inp));
      sheet.querySelectorAll('.hde-line').forEach(o=>o.classList.toggle('is-sel', o.dataset.hid === inp.dataset.hid));
    });
    // ⚠️ Repaint on CHANGE, not on every keystroke. Repainting on input rebuilds the list and
    // therefore destroys the field being typed into.
    slots.addEventListener('input', e=>{
      const inp = e.target.closest && e.target.closest('.hde-tpl');
      if(!inp) return;
      hdeLines()[inp.dataset.hid] = String(inp.value).trim();
      render(currentSchedule);
      markDirty();
      repaintHeaderEditorStage();
    });

    // ---- palette, presets, close ------------------------------------------------------------------
    root.querySelector('.hde-rail-list').appendChild(buildHdrTokenList(tok=>{
      const id = hdrEditor.selected || (hdeMv() ? 'title' : 'c1');
      hdrEditor.selected = id;
      const store = hdeLines();
      store[id] = ((id in store) ? store[id] : '') + tok;
      render(currentSchedule); markDirty(); paintHeaderEditor();
    }));
    // Save-as opens an inline name field in the footer rather than a nested dialog -- the same
    // shape the Preferences block uses, and for the same reason: a modal inside a modal is a trap,
    // and any id'd input would be swept into every saved calendar.
    root.querySelector('.hde-saveas').addEventListener('click', ()=>{
      const foot = root.querySelector('.hde-foot');
      if(foot.querySelector('.hde-name')) return;
      const wrap = document.createElement('span');
      wrap.className = 'hde-naming';
      const inp = document.createElement('input');
      inp.type = 'text'; inp.className = 'hde-ctl hde-name'; inp.placeholder = 'Preset name';
      inp.setAttribute('aria-label', 'Preset name');
      const ok = document.createElement('button');
      ok.type = 'button'; ok.className = 'hde-ctl hde-wide hde-primary'; ok.textContent = 'Save';
      const no = document.createElement('button');
      no.type = 'button'; no.className = 'hde-ctl hde-wide'; no.textContent = 'Cancel';
      const done = ()=> wrap.remove();
      ok.addEventListener('click', ()=>{
        const res = saveHeaderPresetAs(inp.value);
        if(!res.ok){ uiAlert(res.reason); return; }
        done();
      });
      no.addEventListener('click', done);
      inp.addEventListener('keydown', e=>{ if(e.key === 'Enter'){ e.preventDefault(); ok.click(); } });
      wrap.appendChild(inp); wrap.appendChild(ok); wrap.appendChild(no);
      foot.appendChild(wrap);
      inp.focus();
    });
    root.querySelector('.hde-done').addEventListener('click', closeHeaderEditor);
    root.querySelector('.hde-close').addEventListener('click', closeHeaderEditor);
    root.addEventListener('mousedown', e=>{ if(e.target === root) closeHeaderEditor(); });
    root.querySelector('.hde-phbox').addEventListener('change', function(){
      hdrEditor.placeholders = this.checked; hdrEditor.editing = null; paintHeaderEditor();
    });
    document.addEventListener('keydown', onHeaderEditorKey, true);

    paintHeaderEditor();
  }
  // Repaint the canvas WITHOUT rebuilding the template inputs -- used while typing in one of them.
  function repaintHeaderEditorStage(){
    if(!hdrEditor) return;
    const ctx = buildHeaderCtx(currentSchedule);
    const phCtx = hdrCtxWithPlaceholders(ctx);
    let sawPh = false;
    hdrEditor.root.querySelectorAll('.hde-line').forEach(el=>{
      const id = el.dataset.hid;
      if(hdrEditor.editing === id) return;
      const raw = (id in hdeLines()) ? hdeLines()[id] : '';
      const real = resolveHeaderTemplate(raw, ctx);
      const shown = hdrEditor.placeholders ? resolveHeaderTemplate(raw, phCtx) : real;
      if(shown !== real) sawPh = true;
      el.innerHTML = shown ? hdrEditorHtml(shown) : '';
      el.classList.toggle('is-blank', !real);
      // ⛔ hdeMv(), not a hardcoded false. This is the FAST repaint that runs on every keystroke, and
      // it was reading the WATERFALL's format store while the month editor was open -- so a month
      // line's size/colour/highlight vanished from the live preview the moment you typed, and came
      // back only on a full paintHeaderEditor(). Found by driving the editor on production, not by
      // reading: the slow path had already been made view-aware and looked correct.
      el.setAttribute('style', headerFormatCss(headerFmt(id, hdeMv()), id, hdeMv()));
    });
    // ⚠️ The note has to move with the stage. Typing a token that has no data must flip it to the
    // placeholder wording immediately -- leaving the full-repaint version behind meant the panel
    // showed dashed placeholders under a note that said nothing about them.
    setHdrEditorFoot(hdrEditor.root, sawPh);
    // ⛔ The Excel budget is a WATERFALL fact and must stay hidden in the month view -- the same rule
    // paintHeaderEditor() follows. It was missed here, so the budget was correctly blank when the
    // month editor opened and then reappeared on the first keystroke, announcing a 255-character
    // limit that does not exist for the month PDF. Inventing a constraint is exactly what the
    // comment on the other site says not to do.
    const bud = hdrEditor.root.querySelector('.hde-budget');
    if(hdeMv()){
      bud.textContent = '';
      bud.classList.remove('is-over');
    } else {
      const b = estimateExcelHeaderLength();
      bud.textContent = 'Excel header: about ' + b.total + ' of ' + b.max + ' characters' +
        (b.over ? ' — too long, the last lines will be dropped' : '.');
      bud.classList.toggle('is-over', !!b.over);
    }
  }

  // ---------- The header preset library (HEADER-PRESETS-PLAN.md §3.5, Step 4) ----------
  //
  // A preset is a named set of nine TEMPLATES plus a sparse format map. It lives in `sptcal.prefs`
  // -- per user, per machine -- and never in captureSnapshot().
  //
  // ⛔ THAT SPLIT IS THE POINT, and it is the opposite of the version field's. A preset is *how this
  // person likes headers*; the applied header is *this calendar's header*. Applying a preset COPIES
  // its lines into headerManual/headerFormat, which do travel in the .sptcal -- so a calendar opened
  // on another machine renders correctly without that machine owning the preset, and a preset never
  // rides inside someone else's file.
  //
  // ⛔ PRESETS STORE TEMPLATES, NEVER VALUES (decision H8). A preset whose l2 said "v3" would stamp
  // v3 onto every calendar it was ever applied to. That is why Save-as is DISABLED in Manual mode:
  // Manual lines are literal text, and saving them is exactly the value-pinning H8 forbids.
  const HDR_PRESET_DEFAULT_ID = '__default';
  // Ids are GENERATED and never derived from the name -- a rename must not orphan anything, and two
  // presets may legitimately share a name.
  function newHeaderPresetId(){
    return 'hp_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
  }
  // ⭐ FORWARD-ONLY MIGRATION, in four lines, and it runs on READ rather than rewriting the store.
  // Every preset saved before 21 Sep 2026 -- in localStorage and in every .spthdr file already sent
  // to a colleague -- has top-level `lines`/`format` and no sections. Those ARE the waterfall, so
  // they fold into `sheet` and the month section is absent, which means "leave the month header
  // alone". Migrating on read rather than in place means a preset the user never opens is never
  // touched, and the migration cannot half-finish. Same shape migrateRegionSnapshot() models.
  function normalizeHeaderPreset(p){
    if(!p || typeof p !== 'object') return null;
    if(p.sheet || p.month){
      return { id:p.id, name:p.name, createdAt:p.createdAt,
               sheet: p.sheet || null, month: p.month || null };
    }
    return { id:p.id, name:p.name, createdAt:p.createdAt,
             sheet: p.lines ? { lines:p.lines, format:p.format || {} } : null, month: null };
  }
  function headerPresetsStore(){
    return (Array.isArray(prefs.headerPresets) ? prefs.headerPresets : [])
      .map(normalizeHeaderPreset).filter(Boolean);
  }
  function writeHeaderPresets(list){
    // ⛔ An empty list REMOVES the key rather than storing []. Same rule the gridlines preference
    // follows: the store never holds an entry that means nothing, so a later migration can read it
    // without guessing which entries were deliberate.
    if(list && list.length) prefs.headerPresets = list; else delete prefs.headerPresets;
    return savePrefs();
  }
  // ---------- A preset is ONE file with TWO sections (owner ruling 1, 21 Sep 2026) ----------
  //
  // `sheet` and `month`, each OPTIONAL. The two headers have structurally incompatible slots -- nine
  // against four, and the waterfall's are capped by Excel's 255-character page header -- so a preset
  // for one can never be APPLIED to the other. That argues for two SECTIONS and nothing more: the
  // unit a user thinks in is one look across both outputs, and two separate files drift until one
  // calendar prints two identities.
  const HDR_PRESET_SECTIONS = ['sheet','month'];
  function hdrSectionIds(sec){ return sec === 'month' ? MV_HDR_IDS : HDR_IDS; }
  function hdrSectionDefaults(sec){ return sec === 'month' ? DEFAULT_MV_TEMPLATE : DEFAULT_HEADER_TEMPLATE; }
  function hdrSectionLabel(sec){ return sec === 'month' ? 'month' : 'waterfall'; }

  // What Save-as would capture right now, and whether it may. RAW templates in every case.
  // ⚠️ A section is capturable in Auto and Template but NOT in Manual -- Manual is literal text a
  // user typed, not a template, and saving it as one would hand someone a preset that silently
  // never updates. That rule is unchanged; it now applies per SECTION rather than to the whole file,
  // so a calendar with a Template waterfall and a Manual month saves the half that means something.
  function headerPresetSection(sec){
    const mode = sec === 'month'
      ? (mvHeaderMode === 'auto' ? 'auto' : (mvHeaderTemplates ? 'template' : 'manual'))
      : (headerMode === 'auto' ? 'auto' : (headerTemplates ? 'template' : 'manual'));
    if(mode === 'manual') return null;
    const store = sec === 'month' ? mvHeaderManual : headerManual;
    const defs = hdrSectionDefaults(sec);
    const lines = {};
    hdrSectionIds(sec).forEach(id=>{
      // In Template the store IS the templates; a line the user has not touched has no entry yet, so
      // fall back to the built-in default for that slot. In Auto there is no store at all, and the
      // Default template is what the header currently means.
      lines[id] = (mode === 'template' && (id in store)) ? store[id] : (defs[id] || '');
    });
    const fmt = sec === 'month' ? mvHeaderFormat : headerFormat;
    return { lines, format: Object.assign({}, fmt) };
  }
  function headerPresetMode(sec){
    return sec === 'month'
      ? (mvHeaderMode === 'auto' ? 'auto' : (mvHeaderTemplates ? 'template' : 'manual'))
      : (headerMode === 'auto' ? 'auto' : (headerTemplates ? 'template' : 'manual'));
  }
  // ⛔ AT LEAST ONE SECTION MUST BE IN TEMPLATE, and that is decision H8 generalised rather than
  // relaxed. H8 refused Save-as in Manual because a preset holds TEMPLATES, never resolved values.
  // Sections made "is it Manual" ambiguous, and the first cut got it wrong: it offered Save-as
  // whenever ANY section was capturable, so a user with a MANUAL waterfall and an untouched month
  // could save a preset that silently omitted the header they were looking at and carried only the
  // month's built-in defaults. That is the half-imported-preset failure wearing a different coat --
  // caught by the hdrpreset leg, which is exactly what it is there for.
  //
  // An AUTO section still rides along with a Template one, because that is ruling 1's "one look
  // across both outputs". What it may not do is be the only thing in the file.
  function headerPresetCapture(){
    const sheetMode = headerPresetMode('sheet'), monthMode = headerPresetMode('month');
    if(sheetMode !== 'template' && monthMode !== 'template'){
      return { ok:false, reason: (sheetMode === 'manual' || monthMode === 'manual')
        ? 'Switch to Template to save this header as a preset. Manual lines are plain text, not templates.'
        : 'Switch to Template to save this header as a preset.' };
    }
    const sheet = headerPresetSection('sheet');
    const month = headerPresetSection('month');
    return { ok:true, sheet, month,
      // Named, not silent: a Manual section cannot be saved, so say which one is being left out
      // rather than handing over a file that is quietly missing half its job.
      omitted: HDR_PRESET_SECTIONS.filter(sec=>headerPresetMode(sec) === 'manual').map(hdrSectionLabel) };
  }
  // Default first, always, and read-only. It is the one preset every user has.
  function headerPresetList(){
    return [{ id: HDR_PRESET_DEFAULT_ID, name: 'Default', builtin: true }]
      .concat(headerPresetsStore().map(p=>({ id: p.id, name: p.name, builtin: false })));
  }
  function findHeaderPreset(id){
    if(id === HDR_PRESET_DEFAULT_ID){
      // The built-in carries BOTH sections, so "Default" means the default look everywhere rather
      // than the default waterfall and whatever the month happened to be wearing.
      return { id, name:'Default', builtin:true,
               sheet: { lines: DEFAULT_HEADER_TEMPLATE, format: {} },
               month: { lines: DEFAULT_MV_TEMPLATE, format: {} } };
    }
    return headerPresetsStore().find(p=>p.id === id) || null;
  }
  // Push names and ids only -- the chrome never needs the templates, and keeping them out means a
  // React re-render cannot become a place where preset content is edited.
  function pushHeaderPresets(){
    const cap = headerPresetCapture();
    let budget = null;
    try { budget = estimateExcelHeaderLength(); } catch(e){ budget = null; }
    chrome.headerPresets({
      items: headerPresetList(),
      canSave: !!cap.ok,
      saveHint: cap.ok ? '' : cap.reason,
      excelBudget: budget,
    });
  }
  // Applying is a CALENDAR edit: it changes what the header prints, so it marks dirty and lands as
  // ONE undo step covering all nine lines and their formats.
  // `want` names which section the caller is asking for: 'sheet', 'month', or undefined for "every
  // section this preset has". A view that asks for a section the preset does not carry is REFUSED
  // BY NAME rather than silently doing nothing -- a preset that appears to apply and changes nothing
  // is indistinguishable from a broken one.
  function applyHeaderPreset(id, want){
    const p = findHeaderPreset(id);
    if(!p) return false;
    const secs = (want ? [want] : HDR_PRESET_SECTIONS).filter(sec=>!!p[sec]);
    if(!secs.length){
      uiAlert(want
        ? 'This preset has no ' + hdrSectionLabel(want) + ' header, so there is nothing to apply here.'
        : 'That preset has no header lines in it.');
      return false;
    }
    // ⛔ ONE undo step for the WHOLE apply, both sections together. Applying a preset is one act to
    // the person doing it, and ⌘Z has to undo it as one -- not the month and then the waterfall.
    asOneHeaderStep(()=>{
      secs.forEach(sec=>{
        if(sec === 'month'){
          // Cleaned on the way in: a preset stored in this browser before the value checks existed
          // may carry anything (audit H-1), and the writers read these stores directly.
          mvHeaderManual = cleanHeaderLineMap(p.month.lines, { n: 0 });
          mvHeaderFormat = cleanHeaderFormatMap(p.month.format || {}, { n: 0 });
          mvHeaderTemplates = true;
          mvHeaderMode = 'manual';
        } else {
          headerManual = cleanHeaderLineMap(p.sheet.lines, { n: 0 });
          headerFormat = cleanHeaderFormatMap(p.sheet.format || {}, { n: 0 });
          headerTemplates = true;
          headerMode = 'manual';
          headerOff = false;   // applying a header shows it: a preset that changed nothing visible would read as broken
        }
      });
      render(currentSchedule);
      markDirty();
    });
    pushHeaderPresets();
    return true;
  }
  function saveHeaderPresetAs(name){
    const cap = headerPresetCapture();
    if(!cap.ok) return { ok:false, reason: cap.reason };
    const clean = String(name || '').trim();
    if(!clean) return { ok:false, reason:'Give the preset a name.' };
    const list = headerPresetsStore().slice();
    list.push({ id: newHeaderPresetId(), name: clean, createdAt: new Date().toISOString(),
                sheet: cap.sheet, month: cap.month });
    writeHeaderPresets(list);
    pushHeaderPresets();
    return { ok:true };
  }
  function renameHeaderPreset(id, name){
    const clean = String(name || '').trim();
    if(!clean || id === HDR_PRESET_DEFAULT_ID) return false;
    const list = headerPresetsStore().map(p => p.id === id ? Object.assign({}, p, { name: clean }) : p);
    writeHeaderPresets(list);
    pushHeaderPresets();
    return true;
  }
  function deleteHeaderPreset(id){
    if(id === HDR_PRESET_DEFAULT_ID) return false;   // the built-in cannot be deleted
    writeHeaderPresets(headerPresetsStore().filter(p=>p.id !== id));
    pushHeaderPresets();
    return true;
  }

  // ---------- The Excel header budget (HEADER-PRESETS-PLAN.md §3.8, Step 6) ----------
  //
  // Excel rejects a header/footer string over 255 characters IN TOTAL, codes included -- and it does
  // not fail gracefully: the workbook still writes and still validates as XML, but Excel refuses it
  // on open with "We found a problem with some content", which reads as a corrupt file rather than a
  // too-long header. exportExcel's trimmer drops trailing lines to stay under, so nothing breaks --
  // but the user loses lines without being told, and templates make long headers very easy to write.
  // So show the number before they hit it.
  //
  // ⚠️ THIS IS A SECOND COPY OF A FROZEN FUNCTION'S ARITHMETIC AND IT CAN DRIFT. exportExcel stays
  // authoritative -- it is the thing that actually writes the file and it is frozen. This is an
  // ESTIMATE and the UI says "about" for that reason. The `hdrexcel` gate leg is the guard: a header
  // this function scores near the limit must still produce a workbook check-xlsx.sh accepts.
  // ⛔ Do not "fix" the duplication by calling into exportExcel. It builds an entire workbook.
  function estimateExcelHeaderLength(){
    // Mirrors exportExcel's assembly exactly: three sections, each prefixed by HSIZE, lines joined
    // by a newline, per-line codes only when some line in that section is formatted.
    // ⭐ Since M-9 (29 Sep 2026) it ALSO mirrors exportExcel's trim, both passes, on the same
    // {code, text} lines -- detail lines first (right, centre, then left), then shave the longest
    // text, dropping a line whose text runs out -- so the sentence under the number can say what the
    // workbook will actually lose instead of "the last lines will be dropped". `total` stays the
    // UNTRIMMED length: that is the number the user is over by. The hdrcut leg holds this copy to
    // the workbook's real header.
    // Header: Off writes no page header at all (exportExcel), so there is no budget to show; null
    // hides the line, as a failed estimate already does.
    if(headerOff) return null;
    const HF_MAX = 255;
    const HSIZE_COST = '&B&12&"Calibri,Bold"'.length;      // 20, and there are three of them
    const hd = computeHeaderDefaults(currentSchedule);
    const safe = s => String(s).replace(/&/g, '').trim();  // hdrSafe
    const lineCode = id => {
      const f = headerFmt(id, false);
      const size = f.size ? Math.round(f.size) : 12;
      const bold = (f.bold === undefined) ? true : !!f.bold;
      const style = bold && f.italic ? 'Bold Italic' : bold ? 'Bold' : f.italic ? 'Italic' : 'Regular';
      const color = f.color ? String(f.color).replace('#','').toUpperCase() : '000000';
      return '&' + size + '&"Calibri,' + style + '"&K' + color;
    };
    const anyFmt = ids => ids.some(id => Object.keys(headerFmt(id, false)).length > 0);
    const lines = ids => {
      const on = anyFmt(ids);
      return ids.map(id => ({ id, text: safe(headerLine(id, hd)) })).filter(x => x.text)
        .map(x => ({ code: on ? lineCode(x.id) : '', text: x.text, cut: false }));
    };
    const L = lines(['left','l2','l3']), C = lines(['c1','c2','c3','c4']), R = lines(['r1','r2','r3']);
    const count = L.length + C.length + R.length;
    // ⚠️ &L is emitted even when its section is empty (exportExcel's `&L${HSIZE}...` is
    // unconditional, unlike the &C and &R branches), so charge for it either way.
    const secLen = (a, always) => (a.length || always)
      ? 2 + HSIZE_COST + a.reduce((n, x, i) => n + x.code.length + x.text.length + (i ? 1 : 0), 0) : 0;
    const len = () => secLen(L, true) + secLen(C) + secLen(R);
    const total = len();
    while(len() > HF_MAX && (R.length > 1 || C.length > 1 || L.length > 1)){
      if(R.length > 1) R.pop(); else if(C.length > 1) C.pop(); else L.pop();
    }
    let guard = 0;
    while(len() > HF_MAX && guard++ < 400){
      let arr = null, idx = -1, best = 0;
      [L, C, R].forEach(a => a.forEach((x, i) => { if(x.text.length > best){ arr = a; idx = i; best = x.text.length; } }));
      if(!arr) break;
      const keep = best - (len() - HF_MAX) - 1;
      if(keep <= 0) arr.splice(idx, 1);
      else arr[idx] = { code: arr[idx].code, text: arr[idx].text.slice(0, keep).replace(/\s+$/, '') + '…', cut: true };
    }
    const kept = L.length + C.length + R.length;
    const shortened = [L, C, R].reduce((n, a) => n + a.filter(x => x.cut).length, 0);
    return { total, max: HF_MAX, over: total > HF_MAX, dropped: count - kept, shortened };
  }
  function pushExcelBudget(){
    let b = null;
    try { b = estimateExcelHeaderLength(); } catch(e){ b = null; }
    chrome.headerPresets({ excelBudget: b });
  }

  // ---------- Preset FILES: .spthdr (HEADER-PRESETS-PLAN.md §3.6, Step 5) ----------
  //
  // "Save to your computer" was half the original ask: a preset should be sendable to a colleague,
  // not trapped in one browser's localStorage.
  //
  // ⛔ THIS IS NOT A CALENDAR FILE AND MUST NEVER GO THROUGH parseCalendarText(). That function is
  // the ONE reader of calendar files and is contract (CLAUDE.md §0 rule 3) -- teaching it a third
  // shape would put every saved calendar's restore path at risk to serve a preference file. A
  // preset gets its own small reader, below, and the two never meet.
  const HDR_PRESET_EXT = '.spthdr';
  const HDR_PRESET_MIME = 'application/json';
  const HDR_PRESET_KIND = 'spt-header-preset';
  const HDR_PRESET_TYPES = [{ description: 'Calendar header preset',
                              accept: { [HDR_PRESET_MIME]: [HDR_PRESET_EXT] } }];
  // The six format keys a line may carry. Anything else in an imported file is DROPPED rather than
  // trusted: a preset arrives from another machine, and headerFormat is read by both writers.
  const HDR_FMT_KEYS = ['size','bold','italic','color','highlight','align'];

  // ⛔ VERSION 2 (21 Sep 2026): two optional sections instead of one flat set of lines. `version: 1`
  // was put in the format with a comment saying it existed so a later shape could migrate rather
  // than guess -- this is that later shape, and the guess it avoids is real: a v1 file's flat
  // `lines` are WATERFALL slot ids, and read as month ids they would all be dropped.
  //
  // ⚠️ A v2 file cannot be read by a build older than today, and that is unfixable by design
  // (CLAUDE.md: old file into new app, forever; new file into old app, never). The blast radius is
  // small -- presets are niche and the deployed build is current -- but the older reader gates on
  // `kind` and would half-succeed, importing a preset with NO lines. Nothing can be done about
  // already-shipped readers; what this side can do is refuse cleanly in the other direction, which
  // parseHeaderPresetText() now does by checking `version` before it looks at anything else.
  const HDR_PRESET_VERSION = 2;
  function headerPresetToJson(p){
    const out = { kind: HDR_PRESET_KIND, version: HDR_PRESET_VERSION, name: p.name };
    // An ABSENT section is omitted entirely rather than written as null: "this preset has no month
    // header" and "this preset has an empty month header" are different claims, and the reader
    // distinguishes them by presence.
    HDR_PRESET_SECTIONS.forEach(sec=>{
      if(p[sec]) out[sec] = { lines: p[sec].lines, format: p[sec].format || {} };
    });
    return JSON.stringify(out, null, 1);
  }
  // A filename a person can find again. Punctuation that filesystems dislike becomes a space, and
  // an empty result still yields something openable rather than a bare extension.
  function headerPresetFileName(name){
    const safe = String(name || '').replace(/[\\/:*?"<>|]+/g, ' ').replace(/\s+/g, ' ').trim();
    return (safe || 'Header preset') + HDR_PRESET_EXT;
  }
  async function exportHeaderPreset(id){
    const p = findHeaderPreset(id);
    if(!p) return false;
    const text = headerPresetToJson(p);
    const name = headerPresetFileName(p.name);
    // Same two-branch shape as saveAsFile: the real picker where the File System Access API exists,
    // a plain download everywhere else.
    if(supportsFsAccess){
      let handle;
      try {
        handle = await window.showSaveFilePicker({ suggestedName: name, types: HDR_PRESET_TYPES });
      } catch(e){ if(e && e.name === 'AbortError') return false; throw e; }
      const w = await handle.createWritable();
      await w.write(text);
      await w.close();
      return true;
    }
    downloadTextFile(text, HDR_PRESET_MIME, name);
    return true;
  }

  // The reader. Small, strict, and total: it either returns a preset or says why not.
  //
  // ⛔ VALIDATE, DO NOT TRUST. This file came from someone else's machine. `kind` is the gate;
  // unknown line ids are dropped rather than stored (headerManual is keyed by hid and a stray key
  // would sit there forever); format values are filtered to the six known keys. A file that fails
  // is refused ENTIRELY -- never half-imported, because a half-imported preset is a preset the user
  // believes in and cannot see the holes in.
  //
  // ⚠️ Nothing here is executed or injected. Templates are strings resolved by the §3.1 scanner, and
  // the renderer escapes them with escH exactly as it escapes today's manual text.
  function parseHeaderPresetText(text){
    let o;
    try { o = JSON.parse(text); }
    catch(e){ return { ok:false, reason:'That file is not a header preset -- it is not readable as JSON.' }; }
    if(!o || typeof o !== 'object' || Array.isArray(o)){
      return { ok:false, reason:'That file is not a header preset.' };
    }
    if(o.kind !== HDR_PRESET_KIND){
      return { ok:false, reason:'That file is not a header preset. Header presets are ' + HDR_PRESET_EXT + ' files.' };
    }
    // ⛔ VERSION IS CHECKED UP FRONT, BEFORE ANY CONTENT IS READ (owner ruling 4, 21 Sep 2026).
    // A file from a NEWER build may put meaning in keys this reader does not know about, and a
    // reader that shrugs and takes the parts it recognises produces a preset the user believes in
    // and cannot see the holes in. Refuse the whole file and say which version it is.
    const ver = (o.version === undefined || o.version === null) ? 1 : o.version;
    if(typeof ver !== 'number' || !isFinite(ver) || ver < 1 || ver > HDR_PRESET_VERSION){
      return { ok:false, reason:'That preset was made by a newer version of this app (format ' +
               String(ver) + '; this build reads up to ' + HDR_PRESET_VERSION +
               '). Update the app, or ask for it to be saved again from this version.' };
    }
    // ⭐ ONE reader for both versions: a v1 file's flat lines/format ARE the waterfall section, so
    // it is normalised into v2's shape here and nothing downstream knows there were ever two shapes.
    const src = (ver >= 2) ? o : { sheet: { lines: o.lines, format: o.format } };
    const preset = { name: '', sheet: null, month: null };
    let dropped = 0;
    HDR_PRESET_SECTIONS.forEach(sec=>{
      const sIn = src[sec];
      if(!sIn || typeof sIn !== 'object') return;
      const ids = hdrSectionIds(sec);
      const srcLines = (sIn.lines && typeof sIn.lines === 'object') ? sIn.lines : {};
      const lines = {};
      Object.keys(srcLines).forEach(k=>{
        if(ids.indexOf(k) < 0){ dropped++; return; }          // an id this app has no slot for
        // A header line is TEXT. An object or array used to be stored as "[object Object]"
        // (audit L-8); null means an empty line, as it always did.
        const lv = srcLines[k];
        if(lv == null) lines[k] = '';
        else if(typeof lv === 'string' || (typeof lv === 'number' && isFinite(lv))) lines[k] = String(lv);
        else { dropped++; return; }
      });
      const srcFmt = (sIn.format && typeof sIn.format === 'object') ? sIn.format : {};
      const format = {};
      Object.keys(srcFmt).forEach(k=>{
        if(ids.indexOf(k) < 0){ dropped++; return; }
        const f = srcFmt[k];
        if(!f || typeof f !== 'object'){ dropped++; return; }
        // Each value held to what the toolbar writes (audit H-1 / L-8): a size that is not a number
        // put '&NaN' in the Excel header and 'NaN Tf' in the PDF; a colour could break out of the
        // header's style attribute. Shared with the file restore (cleanHeaderFormatEntry).
        const bad = { n: 0 };
        const clean = cleanHeaderFormatEntry(f, bad);
        dropped += bad.n;
        if(clean) format[k] = clean;
      });
      if(Object.keys(lines).length) preset[sec] = { lines, format };
    });
    if(!preset.sheet && !preset.month){
      return { ok:false, reason:'That preset has no header lines in it.' };
    }
    preset.name = String(o.name || '').trim() || 'Imported preset';
    return { ok:true, preset, dropped };
  }
  async function importHeaderPresetText(text){
    // A real preset is a few KB. Refuse anything that could not be one before parsing it, so a
    // huge file cannot stall the tab or fill this browser's storage (audit L-8).
    if(typeof text === 'string' && text.length > 262144){ uiAlert('That file is too large to be a header preset.'); return false; }
    const res = parseHeaderPresetText(text);
    if(!res.ok){ uiAlert(res.reason); return false; }
    const before = headerPresetsStore().slice();
    const list = headerPresetsStore().slice();
    // ⛔ A FRESH id, always. The file may carry one, and two machines can trivially mint the same
    // name -- but an imported preset is a NEW entry here, and reusing an id from a file would let
    // one import silently overwrite an existing preset.
    list.push({ id: newHeaderPresetId(), name: res.preset.name, createdAt: new Date().toISOString(),
                sheet: res.preset.sheet, month: res.preset.month });
    if(!writeHeaderPresets(list)){
      // localStorage full or blocked: say so and keep the in-memory list as it was, rather than
      // showing a preset that will be gone on the next reload.
      writeHeaderPresets(before);
      pushHeaderPresets();
      uiAlert('Could not store the preset in this browser (its storage is full or blocked).');
      return false;
    }
    pushHeaderPresets();
    if(res.dropped) uiAlert('Imported "' + res.preset.name + '". ' + res.dropped +
                            ' unrecognised entr' + (res.dropped === 1 ? 'y was' : 'ies were') + ' ignored.');
    return true;
  }
  async function importHeaderPresetViaPicker(){
    if(supportsFsAccess){
      let handle;
      try { [handle] = await window.showOpenFilePicker({ types: HDR_PRESET_TYPES, multiple: false }); }
      catch(e){ if(e && e.name === 'AbortError') return false; throw e; }
      const file = await handle.getFile();
      return importHeaderPresetText(await file.text());
    }
    // Fallback: a hidden file input, created on demand and removed again.
    // ⛔ NO id -- collectFieldValues() sweeps every input[id] in the document, and this one is not
    // calendar data. It also lives outside .prefs-card for the moment it exists, so the class
    // exclusion would not have covered it. Created, used, removed.
    return new Promise(resolve=>{
      const inp = document.createElement('input');
      inp.type = 'file';
      inp.accept = HDR_PRESET_EXT + ',' + HDR_PRESET_MIME;
      inp.style.display = 'none';
      inp.addEventListener('change', async ()=>{
        const f = inp.files && inp.files[0];
        document.body.removeChild(inp);
        resolve(f ? await importHeaderPresetText(await f.text()) : false);
      });
      document.body.appendChild(inp);
      inp.click();
    });
  }

  // ⛔ NOTHING HERE ADDS AN UNDO STEP OR A FIELD. Saving, renaming and deleting a preset are
  // PREFERENCE edits, not calendar edits: they must not markDirty(), must not push an undo
  // snapshot, and must not put an id'd control into the document. Only APPLY touches the calendar.
  document.addEventListener('click', async e=>{
    const btn = e.target && e.target.closest ? e.target.closest('[data-hdrpreset]') : null;
    if(!btn) return;
    const action = btn.dataset.hdrpreset;
    const id = btn.dataset.presetId || '';
    if(action === 'apply'){
      const sel = document.querySelector('.hdr-preset-select');
      const pick = sel ? sel.value : id;
      if(pick) applyHeaderPreset(pick);
    } else if(action === 'delete'){
      const p = findHeaderPreset(id);
      if(!p || p.builtin) return;
      if(!(await uiConfirm('Delete the preset "' + p.name + '"?\n\nCalendars you already applied it to keep their header.',
                           { title:'Delete preset', confirmLabel:'Delete', danger:true }))) return;
      deleteHeaderPreset(id);
    } else if(action === 'rename'){
      const p = findHeaderPreset(id);
      if(!p || p.builtin) return;
      const input = document.querySelector('.hdr-preset-rename-input');
      if(input) renameHeaderPreset(id, input.value);
    } else if(action === 'save'){
      const input = document.querySelector('.hdr-preset-name-input');
      const res = saveHeaderPresetAs(input ? input.value : '');
      if(!res.ok){ uiAlert(res.reason); return; }
      chrome.headerPresets({ naming:false });
    } else if(action === 'export'){
      try { await exportHeaderPreset(id); }
      catch(err){ console.error(err); uiAlert('Could not save that preset: ' + err.message); }
    } else if(action === 'edit'){
      // The header of the view you are LOOKING AT (owner report, 24 Sep 2026: in Month view this
      // opened the waterfall's builder -- and silently switched the waterfall header to Template
      // while leaving the month's alone). The month retarget of 22 Sep threaded `mv` through the
      // header-line click and the mode menu's "Open the template editor…" but missed this, the
      // button with no view in its label: the same hardcoded-view slip as that day's three
      // month-editor bugs. `grep -n "openHeaderEditor("` is the audit: every caller must open the
      // view it came from (a waterfall header line may omit the flag -- it can only be the waterfall).
      openHeaderEditor(null, viewMode === 'month');
    } else if(action === 'import'){
      try { await importHeaderPresetViaPicker(); }
      catch(err){ console.error(err); uiAlert('Could not read that preset file: ' + err.message); }
    }
  });

  // ---------- The token palette: Insert ▾ (HEADER-PRESETS-PLAN.md §3.7, Step 3) ----------
  //
  // Nobody can type `{production.summary}` without being told it exists. The palette is the
  // discovery surface for §3.2, and it inserts at the caret of the line the user is editing.
  //
  // ⛔ NOT ONE id IN HERE. collectFieldValues() sweeps every input[id]/select[id]/textarea[id] into
  // every saved calendar and adds an undo step per change; the whole toolbar follows that rule and
  // so does this. Buttons and classes only.
  // ⛔ Waterfall only, and only in Template mode. A token typed into a MANUAL line prints as braces
  // (headerLine only resolves when the flag is on), so offering the palette there would be offering
  // a feature that does nothing. headerFmtToolbarHtml() is non-frozen and reads the flag at call
  // time, so the control simply is not built unless it would work.
  // ⭐ EVERY ENTRY CARRIES ITS LIVE VALUE, not just its name. A list of {shootDaysPerEp} and
  // {production.summary} is jargon you have to decode before you can choose; the same list showing
  // "8" and "16-Week Production Span / 8-Day Shooting Schedule" is something you can shop from. A
  // token with nothing to say right now falls back to its description and is dimmed, which is
  // itself the useful signal -- it tells you the data is missing, not the token.
  function hdrTokenPreview(tok, ctx){
    try {
      const v = resolveHeaderTemplate(tok, ctx);
      return (v && v !== tok) ? v : '';
    } catch(e){ return ''; }
  }
  function hdrTokenGroups(){
    // LOCAL today, as {today} reads it (buildHeaderCtx), written as the token's YYYY-MM-DD.
    const now = new Date(), two = n=> String(n).padStart(2, '0');
    const todayIso = now.getFullYear() + '-' + two(now.getMonth() + 1) + '-' + two(now.getDate());
    const groups = [
      { name: 'Show', items: [
        ['{title}', 'Show title'],
        ['{season}', 'Season, as S2'],
        ['{titleSeason}', 'Title and season'],
        ['{version}', 'Version, as v3'],
        ['{episodes}', 'Episode count'],
        ['{shootDaysPerEp}', 'Shoot days per episode'],
        ['{shootDays}', 'Total shoot days'],
      ]},
      { name: 'Dates', items: [
        ['{today}', "Today, as 9.8.26"],
        ['{today:long}', 'Today, as September 8, 2026'],
        ['{today:slash}', 'Today, as 9/8/26'],
        ['{today:iso}', 'Today, as 2026-09-08'],
        // ⭐ A FIXED date (owner, 20 Oct 2026, item 7: "Revised as of <a date>" must be findable).
        // lookupHeaderToken() has resolved {date:YYYY-MM-DD[:fmt]} since 5 Oct 2026, but no menu offered
        // it. Inserted as TODAY'S date, which the user then edits; it never moves after that.
        ['{date:' + todayIso + '}', 'A fixed date, which never updates'],
      ]},
    ];
    // Every phase the calendar actually has, built-in and custom, under its CURRENT name -- so a
    // renamed phase offers tokens that read the way the sidebar reads.
    let defs = [];
    try { defs = getAllPhaseDefs(); } catch(e){ defs = []; }
    defs.forEach(p=>{
      groups.push({ name: p.label || p.key, items: [
        ['{' + p.key + '.open}',  'Opens'],
        ['{' + p.key + '.close}', p.key === 'production' ? 'Wrap (last shoot day)' : 'Closes (last weekday)'],
        ['{' + p.key + '.weeks}', 'Weeks'],
        ['{' + p.key + '.name}',  'Phase name'],
      ]});
    });
    groups.push({ name: 'Snippets', items: [
      ['Planning Calendar', 'Literal text'],
      ['{production.summary}', 'Span and shooting schedule'],
      ['{production.dates}', 'Principal photography and wrap'],
      ['{writersRoom.line}', "Writer's Room Opens: date"],
      // ⭐ TWO BRACKET FORMS, deliberately. The [ ] grammar is the non-obvious half of templates and
      // a menu that only inserts {tokens} never teaches it. Seeing a square-bracket entry disappear
      // from the preview when its data is missing explains the idea faster than any tooltip.
      ['[{episodes} Episodes]', 'Hidden when there is no count'],
      ['[{version}]', 'Hidden until a version is set'],
      ['Revised as of {date:' + todayIso + '}', 'A revision line with a fixed date'],
    ]});
    return groups;
  }

  // The token list itself, as a fragment -- shared by the toolbar popover and the header editor's
  // rail, so the two can never drift into offering different tokens or different previews.
  // `onPick` null means BROWSE: the same list, every entry disabled, for looking rather than using.
  function buildHdrTokenList(onPick){
    const frag = document.createDocumentFragment();
    // Built once per open, so every preview is this calendar's real data as of right now.
    let ctx = null;
    try { ctx = buildHeaderCtx(currentSchedule); } catch(e){ ctx = null; }
    hdrTokenGroups().forEach(g=>{
      const h = document.createElement('div');
      h.className = 'hdr-token-group';
      h.textContent = g.name;
      frag.appendChild(h);
      g.items.forEach(([tok, desc])=>{
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'hdr-token-item';
        const code = document.createElement('span');
        code.className = 'hdr-token-code';
        code.textContent = tok;
        const d = document.createElement('span');
        const live = ctx ? hdrTokenPreview(tok, ctx) : '';
        // The live value when there is one, the description when there is not -- and the empty case
        // is dimmed, because "this token has nothing to say on this calendar" is worth seeing.
        d.className = 'hdr-token-desc' + (live ? ' is-live' : '');
        d.textContent = live || desc;
        b.appendChild(code); b.appendChild(d);
        if(!onPick) b.disabled = true;
        else b.addEventListener('click', ev=>{ ev.stopPropagation(); onPick(tok); });
        frag.appendChild(b);
      });
    });
    return frag;
  }

  let activeHdrTokenPop = null;
  function closeHdrTokenPop(){
    if(activeHdrTokenPop){ activeHdrTokenPop.remove(); activeHdrTokenPop = null; }
    document.removeEventListener('mousedown', onHdrTokenPopOutside, true);
    window.removeEventListener('resize', closeHdrTokenPop);
    window.removeEventListener('scroll', onHdrTokenPopScroll, true);
  }
  function onHdrTokenPopOutside(e){
    if(activeHdrTokenPop && !activeHdrTokenPop.contains(e.target)) closeHdrTokenPop();
  }
  // ⛔ THE PALETTE SCROLLS, SO ITS OWN SCROLLING MUST NOT CLOSE IT. The other body-level popovers
  // close on any scroll -- correct for them, because a panel anchored to a moving element should
  // not be left pointing at nothing, and none of them is tall enough to scroll internally. This one
  // runs to forty-odd entries and has overflow-y:auto, and the listener is CAPTURE-phase, so a
  // wheel inside the list reached the window handler and shut the menu before it moved a pixel.
  // Reported as "I can't scroll in the Insert menu", and it was: every attempt closed it.
  // A scroll that starts inside the panel is the user reading it; anything else still closes.
  function onHdrTokenPopScroll(e){
    if(activeHdrTokenPop && e.target && e.target.nodeType &&
       (activeHdrTokenPop === e.target || activeHdrTokenPop.contains(e.target))) return;
    closeHdrTokenPop();
  }
  // Put `text` where the caret is, inside the line the toolbar is targeting.
  //
  // ⚠️ THE CARET IS THE WHOLE DIFFICULTY. The line is contenteditable and the palette is a
  // body-level panel, so a click in the panel would ordinarily blur the line and destroy the
  // selection before the insert runs. Two things prevent that: mousedown is preventDefault'ed over
  // the panel (below), and the range is re-validated here rather than trusted -- if the saved
  // selection is not inside the target line any more, the token goes at the END, which is the
  // predictable answer rather than a silent no-op.
  // Which line a token would land in. ⛔ NEVER null in Template mode: refusing to insert because
  // nothing is focused was a dead end at exactly the moment someone is exploring -- open the menu
  // to find out what tokens exist, and it told you to go away and click something first. Default to
  // the TITLE line, which is the one people edit, and say so in the menu so it is never a surprise.
  function hdrInsertTargetId(){
    if(hdrFmtTarget && !hdrFmtTarget.mv) return hdrFmtTarget.id;
    return 'c1';
  }
  function insertHdrToken(text){
    const id = hdrInsertTargetId();
    const line = document.querySelector('#table-wrap .hdr-line[data-hid="' + id + '"]');
    if(!line) return false;
    // Adopt the fallback as the real target, so the formatting toolbar and a second insert both
    // agree about which line is being worked on.
    hdrFmtTarget = { id, mv: false };
    line.focus();
    const sel = window.getSelection();
    let range = null;
    if(sel && sel.rangeCount){
      const r = sel.getRangeAt(0);
      if(line.contains(r.commonAncestorContainer)) range = r;
    }
    if(!range){
      range = document.createRange();
      range.selectNodeContents(line);
      range.collapse(false);            // the end
    }
    range.deleteContents();
    const node = document.createTextNode(text);
    range.insertNode(node);
    range.setStartAfter(node);
    range.collapse(true);
    if(sel){ sel.removeAllRanges(); sel.addRange(range); }
    // Commit through the SAME path a typed edit uses, so there is one definition of "a line
    // changed" -- storing raw, re-rendering resolved, and marking dirty exactly once.
    line.dispatchEvent(new FocusEvent('focusout', { bubbles: true }));
    return true;
  }
  // `browse` opens the same list with the previews but no insertion -- what the mode menu offers
  // before you commit to Template, so the tokens are visible while you are still deciding.
  function openHdrTokenPop(anchorEl, browse){
    closeHdrTokenPop();
    const pop = document.createElement('div');
    pop.className = 'hdr-token-pop';
    // Say where a token will go, always -- not only when falling back. "l2" is not an answer, so
    // this is the one place the nine slots get human names.
    const targetId = hdrInsertTargetId();
    const head = document.createElement('div');
    head.className = 'hdr-token-hint';
    head.textContent = browse
      ? 'Live data you can put in a header line. Switch to Template to use these.'
      : 'Inserting into: ' + (HDR_SLOT_NAMES[targetId] || targetId);
    pop.appendChild(head);
    pop.appendChild(buildHdrTokenList(browse ? null : (tok)=>{
      closeHdrTokenPop();
      insertHdrToken(tok);
    }));
    // ⚠️ Keep the caret. Without this the mousedown blurs the contenteditable line and the
    // selection is gone before the click handler above ever runs.
    pop.addEventListener('mousedown', ev=>{ ev.preventDefault(); });
    document.body.appendChild(pop);
    const r = anchorEl.getBoundingClientRect();
    pop.style.top = (window.scrollY + r.bottom + 5) + 'px';
    pop.style.left = (window.scrollX + r.left) + 'px';
    const pr = pop.getBoundingClientRect();
    if(pr.right > window.innerWidth - 8) pop.style.left = (window.scrollX + window.innerWidth - pr.width - 8) + 'px';
    if(pr.bottom > window.innerHeight - 8){
      pop.style.top = (window.scrollY + Math.max(8, r.top - pr.height - 5)) + 'px';
    }
    activeHdrTokenPop = pop;
    setTimeout(()=>{
      document.addEventListener('mousedown', onHdrTokenPopOutside, true);
      window.addEventListener('resize', closeHdrTokenPop);
      window.addEventListener('scroll', onHdrTokenPopScroll, true);
    }, 0);
  }

  function headerFormatExcel(f){
    if(!f) return '';
    let s = '';
    if(f.size)   s += '&' + Math.round(f.size);
    if(f.bold)   s += '&B';
    if(f.italic) s += '&I';
    if(f.color)  s += '&K' + String(f.color).replace('#','').toUpperCase();
    return s;
  }

  // The version number as it appears in the header: a lowercase "v" and then whatever was typed.
  //
  // Owner decision H1 (1 Sep 2026): the label is ALWAYS "v" + the input, with a leading v/V
  // stripped so that typing "3" and typing "v3" both read "v3", and ANY text is accepted -- owners
  // write 3, 3.1 and 3a. That is a LABEL, not arithmetic, which is why the field is a TextInput and
  // not a NumberInput.
  //
  // ⛔ AN EMPTY FIELD MUST RETURN THE EMPTY STRING, never a bare "v". That single line is the whole
  // of this feature's inertness. computeHeaderDefaults() puts this value in the l2 slot, and an
  // EMPTY l2 is filtered out of the workbook by withCodes(), filtered out of the direct PDF by
  // .filter(x=>x.t), and hidden on screen by .hdr-line.hdr-slot.hdr-empty -- but only while it is
  // empty. Return "v" for an empty field and every calendar ever saved gains a stray line in all
  // three outputs, and the gate's byte-identical PDF/Excel compare goes red. What buys that is the
  // FIRST trim plus the `num ?` ternary: "v" and "v  " both trim to "v", strip to "", and the
  // ternary returns "". The SECOND trim is a different job -- interior whitespace, so "v  3" reads
  // "v3" rather than "v  3".
  function versionLabel(){
    const el = document.getElementById('show-version');
    const raw = el ? String(el.value || '').trim() : '';
    const num = raw.replace(/^[vV]/, '').trim();
    return num ? 'v' + num : '';
  }

  // ---------- Header templates (HEADER-PRESETS-PLAN.md Step 2) ----------
  //
  // A header line can be a TEMPLATE: literal text mixed with {tokens} that resolve from the same
  // data the auto header reads. `Principal Photography {production.open}` renders live.
  //
  // ⛔ RESOLUTION HAPPENS IN headerLine(), THE ONE FUNCTION ALL THREE CONSUMERS CALL -- the screen
  // inside frozen renderSpreadsheetView, exportExcel and buildWaterfallPdf. That is the whole
  // design: they cannot disagree, and not one frozen line changes. Do not resolve anywhere else.

  // ⚠️ LOCAL vs UTC is not a style choice. {today} is the reader's own calendar date -- that is what
  // computeHeaderDefaults() has always printed -- while every schedule date is UTC midnight
  // (parseDateUTC / mondayOf). Format one with the other's getters and the date lands a day out for
  // readers west of UTC. So a date token carries the flag with it rather than letting the formatter
  // guess.
  function hdrDate(d, local){ return d ? { __hdrDate: d, local: !!local } : ''; }
  const HDR_MONTHS = ['January','February','March','April','May','June',
                      'July','August','September','October','November','December'];
  function fmtHeaderDate(box, fmt){
    const d = box.__hdrDate, L = box.local;
    const y   = L ? d.getFullYear() : d.getUTCFullYear();
    const m   = (L ? d.getMonth()   : d.getUTCMonth()) + 1;
    const day = L ? d.getDate()     : d.getUTCDate();
    switch(fmt){
      case 'slash': return `${m}/${day}/${String(y).slice(2)}`;   // the grid's fmtShort
      case 'long':  return `${HDR_MONTHS[m-1]} ${day}, ${y}`;
      case 'iso':   return `${y}-${String(m).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
      // ⛔ 'dotpad' is the MONTH header's form and it is NOT the same string as 'dot'. The month
      // view has always zero-padded the day (M.DD.YY); the waterfall header never has (M.D.YY).
      // They agree on 279 days a year and differ on the other 121 -- every 1st to 9th. Added so
      // DEFAULT_MV_TEMPLATE can reproduce the month's printed date exactly rather than nearly.
      case 'dotpad': return `${m}.${String(day).padStart(2,'0')}.${String(y).slice(2)}`;
      default:      return `${m}.${day}.${String(y).slice(2)}`;   // 'dot' -- the header's own form
    }
  }

  // Every value a token can carry, built ONCE per render and handed to headerLine() on the defaults
  // object. Reads exactly what computeHeaderDefaults() reads: Show Info from the DOM by id, schedule
  // facts from the schedule it is passed, phase names from getAllPhaseDefs().
  //
  // A token's value is '' when it has nothing to say -- that is what empties a [group]. A token that
  // is not in this map AT ALL is unknown and renders as typed, braces included, which is what makes
  // turning existing hand-typed manual text into templates safe for every file already saved.
  function buildHeaderCtx(schedule){
    const t = {};
    const val = id => { const el = document.getElementById(id); return el ? (el.value || '').trim() : ''; };

    // ---- Show and version --------------------------------------------------------------------
    const title = val('show-title');
    const season = val('season-num');
    t.title = title;
    t.season = season ? 'S' + season : '';
    // Verbatim c1: the season is a SUFFIX, and its leading space appears only when there is a title
    // to separate it from -- so a season with no title reads "S2", never " S2".
    t.titleSeason = title + (season ? (title ? ' ' : '') + 'S' + season : '');
    t.version = versionLabel();
    const numEpisodes = parseInt(val('num-episodes'), 10);
    t.episodes = (!isNaN(numEpisodes) && numEpisodes > 0) ? String(numEpisodes) : '';
    const perEp = dayCountVal(val('shoot-days-per-ep'));   // halves allowed: "4.5-Day Shooting Schedule"
    // In Blocks mode the per-episode field is hidden and drives nothing, so its value is not a fact
    // about this calendar any more: the token goes empty rather than printing a number nobody can
    // see (ruling 6). Episodes mode is unchanged.
    const blocksMode = isBlocksMode();
    t.shootDaysPerEp = (!blocksMode && !isNaN(perEp) && perEp > 0) ? String(perEp) : '';
    const numBlocks = parseInt(val('num-blocks'), 10);
    let totalShootDays = 0;
    try { totalShootDays = showInfoStatus().totalShootDays || 0; } catch(e){ totalShootDays = 0; }
    t.shootDays = totalShootDays ? String(totalShootDays) : '';

    // ---- Dates -------------------------------------------------------------------------------
    t.today = hdrDate(new Date(), true);   // LOCAL -- see the note above

    // ---- Phases, generic over every built-in AND custom key ----------------------------------
    const segs = (schedule && schedule.segments) || [];
    let defs = [];
    try { defs = getAllPhaseDefs(); } catch(e){ defs = []; }
    defs.forEach(p => {
      const seg = segs.find(sg => sg.key === p.key);
      t[p.key + '.name'] = p.label || '';
      if(!seg){
        t[p.key + '.open'] = ''; t[p.key + '.close'] = ''; t[p.key + '.weeks'] = '';
        return;
      }
      t[p.key + '.open'] = hdrDate(seg.start, false);
      // H5: the FRIDAY of the final week. seg.end is the EXCLUSIVE Monday after the last delivered
      // week (extendEndForHiatus counts delivered weeks and returns the Monday following them), so
      // seg.end is itself a day the phase is already over. "Writer's Room closes 3.6.26" has to name
      // a day the room is still open.
      // ⛔ FIXED 15 Oct 2026 (CUSTOM-PHASE-UNITS-PLAN.md §9): this was `seg.end - 3 days`, which is the
      // Friday only when seg.end is a Monday. A phase that ends mid-week -- any snap-off Weeks phase
      // starting off a Monday, and every Days or Dates phase -- named a day two or three days before
      // its real last day (a Wednesday start's close came out as the Sunday before). Now: the last
      // Mon-Fri day before the exclusive end. For a Monday end that is still end - 3, byte for byte,
      // so every calendar whose phases end on Mondays prints exactly what it printed before.
      let closeDay = seg.end ? addDays(seg.end, -1) : null, guard = 0;
      while(closeDay && (closeDay.getUTCDay() === 0 || closeDay.getUTCDay() === 6) && guard++ < 7) closeDay = addDays(closeDay, -1);
      t[p.key + '.close'] = closeDay ? hdrDate(closeDay, false) : '';
      t[p.key + '.weeks'] = seg.weeks ? String(seg.weeks) : '';
    });

    // Production is special-cased to REAL SHOOT DAYS, exactly as the auto header already is. The
    // entered Monday can be a union holiday or fall inside a hiatus, in which case it is a calendar
    // guess and the grid beside it says something else -- the bug README records as "the wrap date
    // was right; the date beside it was a calendar guess".
    const prodInfo = schedule && schedule.productionInfo;
    if(prodInfo){
      t['production.open']  = hdrDate(prodInfo.firstShootDay || prodInfo.startDate, false);
      t['production.wrap']  = hdrDate(prodInfo.lastShootDay, false);
      t['production.close'] = t['production.wrap'];   // an alias, per §3.2
    } else {
      t['production.wrap']  = '';
      t['production.close'] = '';
    }

    // ---- Compound tokens: the composite auto lines, so a preset can BE the auto header ---------
    // ⚠️ THIS IS A SECOND STATEMENT OF r1 / r2 / c3 AND THE TWO CAN DRIFT. computeHeaderDefaults()
    // stays hand-coded on purpose -- its strings are the byte-identical baseline the gate compares
    // against. The `hdrtemplate` leg asserts these three resolve to exactly what that function
    // returns on the fixture, so a drift fails loudly instead of quietly changing someone's header.
    // Keep them in step by hand; do not "fix" the duplication by making Auto read the template.
    let prodWeeks = 0;
    if(schedule && schedule.weeks){
      for(const w of schedule.weeks){
        // Production's key only (audit L-11) -- see computeHeaderDefaults(), which says why.
        if(w.cells.some(c => c.key === 'production')) prodWeeks++;
      }
    }
    // ⛔ KEEP IN STEP WITH computeHeaderDefaults()'s r1 -- including the Blocks branch (ruling 6).
    t['production.summary'] = [
      prodWeeks ? `${prodWeeks}-Week Production Span` : '',
      blocksMode ? shootingBlocksPhrase(numBlocks)
                 : (t.shootDaysPerEp ? `${t.shootDaysPerEp}-Day Shooting Schedule` : ''),
    ].filter(Boolean).join(' / ');
    t['production.dates'] = prodInfo
      ? `Principal Photography ${fmtHeaderDate(t['production.open'], 'dot')} / Wrap: ${fmtHeaderDate(t['production.wrap'], 'dot')}`
      : '';
    // ⚠️ Read from the FIELD, not from the segment, because that is what c3 does: the entered date
    // snapped to its Monday. Deriving it from the segment would be a different number the day a
    // hiatus or a solver moves the phase, and this token's contract is "verbatim c3".
    const wrRaw = val('start-writersRoom');
    let wrLine = '';
    if(wrRaw){
      const parsed = parseDateUTC(wrRaw);
      if(parsed) wrLine = `Writer's Room Opens: ${fmtHeaderDate(hdrDate(mondayOf(parsed), false), 'dot')}`;
    }
    t['writersRoom.line'] = wrLine;

    return { tokens: t };
  }

  // One token, resolved. Returns undefined for an UNKNOWN name -- the caller leaves those exactly as
  // typed -- and '' for a known token with nothing to say.
  function lookupHeaderToken(name, ctx){
    if(!ctx || !ctx.tokens) return undefined;
    const raw = String(name).trim();
    // {date:2026-10-05} and {date:2026-10-05:long} take their VALUE as the first argument, so they
    // cannot go through the generic key:format split below.
    if(raw === 'date' || raw.indexOf('date:') === 0){
      const parts = raw.split(':');
      const d = parseDateUTC((parts[1] || '').trim());
      return d ? fmtHeaderDate(hdrDate(d, false), (parts[2] || '').trim() || 'dot') : '';
    }
    const ci = raw.indexOf(':');
    const key = (ci < 0 ? raw : raw.slice(0, ci)).trim();
    const fmt = ci < 0 ? '' : raw.slice(ci + 1).trim();
    // OWN properties only (audit L-9): `in` also walks Object.prototype, so {constructor},
    // {toString}, {__proto__} resolved to engine internals -- "function Object() { [native code] }"
    // printed in a header, from a template anyone can share in a .spthdr preset.
    if(!Object.prototype.hasOwnProperty.call(ctx.tokens, key)) return undefined;
    const v = ctx.tokens[key];
    if(v === '' || v == null) return '';
    if(v && v.__hdrDate) return fmtHeaderDate(v, fmt || 'dot');
    return String(v);
  }

  // Resolve one template line. PURE: no DOM, no module state -- everything arrives in `ctx`, which
  // is what lets tests/harness/prove-header-template.mjs slice this function out of the file
  // verbatim and fuzz it in Node. Keep it that way.
  //
  // ⚠️ A SINGLE LEFT-TO-RIGHT SCAN, and that is a correctness decision rather than a style one.
  // The first cut of this resolved in stages -- protect the {{ }} escapes, then groups, then the
  // remaining tokens -- and staged passes cannot tokenise `{{{title}}}`: the escape pass eats the
  // leading `{{` and then the FIRST `}}` it meets, which is the token's own closing brace plus one,
  // so the token never forms and the line came out `{{title}}` -- neither literal nor resolved.
  // Caught by prove-header-template.mjs. One scan decides `{{` -> literal, then `{title}` -> token,
  // then `}}` -> literal, which is the reading a person would give it.
  //
  // ⭐ ONE PASS IS THEN TRUE BY CONSTRUCTION, which is the rule that matters most here: a resolved
  // value is appended to the output and the scanner never looks at it again, so a show titled
  // "{today}" prints the words {today} and a value containing "[x]" is not read as a group. No
  // sentinels, no re-scanning, nothing to get subtly wrong later.
  //
  // Anything malformed falls back to LITERAL -- an unterminated `{`, a `[` with no `]`, a name
  // containing a brace. The rule the grammar exists to protect is that text a user typed before
  // templates existed must render as they typed it.
  function resolveHeaderTemplate(str, ctx){
    if(!str) return str;
    const s = String(str);
    if(s.indexOf('{') < 0 && s.indexOf('[') < 0) return s;   // fast path: nothing to resolve
    // ⛔ A ceiling, not a rule change (audit L-9). Each unterminated `[` makes hdrScan rescan to the
    // end of the line before falling back to a literal bracket, so a line of N lone `[` costs N² --
    // a shared .spthdr preset of a few hundred KB could lock the tab. A real header line is a few
    // hundred characters at most (Excel caps the whole header at 255), so anything longer than
    // this is returned exactly as typed and every real template resolves byte-identically.
    if(s.length > 4096) return s;
    return hdrScan(s, 0, false, ctx, { empty: false }).out;
  }
  // The scanner. `stopAtBracket` is set for the inside of a [group]: a lone `]` ends it, and a `[`
  // is literal there because groups do not nest (§3.1). `state.empty` is how a group learns that one
  // of its tokens resolved to nothing -- which collapses the whole group, its literal text and the
  // spaces inside the brackets with it.
  function hdrScan(s, i, stopAtBracket, ctx, state){
    let out = '';
    while(i < s.length){
      const c = s[i], n = s[i+1];
      if(c === '{'){
        if(n === '{'){ out += '{'; i += 2; continue; }          // {{ -> a literal brace
        const close = s.indexOf('}', i+1);
        const name = close < 0 ? null : s.slice(i+1, close);
        // A name that runs to the end of the line, or that swallows another `{`, is not a token.
        if(name === null || name.indexOf('{') >= 0){ out += c; i++; continue; }
        const v = lookupHeaderToken(name, ctx);
        if(v === undefined) out += '{' + name + '}';            // unknown -> exactly as typed
        else if(v === '') state.empty = true;                   // known but empty -> gates the group
        else out += v;
        i = close + 1; continue;
      }
      if(c === '}'){
        if(n === '}'){ out += '}'; i += 2; continue; }          // }} -> a literal brace
        out += c; i++; continue;
      }
      if(c === '['){
        if(n === '['){ out += '['; i += 2; continue; }          // [[ -> a literal bracket
        if(stopAtBracket){ out += c; i++; continue; }           // no nesting: literal inside a group
        const sub = { empty: false };
        const r = hdrScan(s, i + 1, true, ctx, sub);
        if(!r.closed){ out += c; i++; continue; }               // unterminated group -> literal
        out += sub.empty ? '' : r.out;
        i = r.i; continue;
      }
      if(c === ']'){
        if(n === ']'){ out += ']'; i += 2; continue; }          // ]] -> a literal bracket
        if(stopAtBracket) return { out, i: i + 1, closed: true };
        out += c; i++; continue;
      }
      out += c; i++;
    }
    return { out, i, closed: false };
  }

  // ---------- The three header modes, and the popover that picks between them ----------
  //
  // Auto / Template / Manual (decision H3). What each one MEANS is documented on the
  // headerTemplates declaration; this is the machine that moves between them.

  // One undo step for a whole transition, so ⌘Z puts all nine lines and their formats back
  // together rather than one at a time.
  // ⚠️ Deliberately NOT the shift tools' asOneUndoStep(): that one is declared inside the
  // shift-tools IIFE, along with the refreshMenuFromCalendar() it calls, so it is not in scope
  // here -- and the file menu does not quote header text, so there is nothing for it to refresh.
  // Same contract, smaller body.
  function asOneHeaderStep(fn){
    pushUndoSnapshot();
    const out = fn();
    pushUndoSnapshot();
    return out;
  }

  // The five transitions of §3.4. Every one of them ends in a render and a markDirty(), because
  // every one of them changes what the calendar prints.
  // ⚠️ The OLD toggle never called markDirty() on Auto -> Manual -- a header takeover left the file
  // showing "Saved" and could not be undone. Same bug class as the one the notes-reset branch
  // carries a comment about. Fixed by construction here: one exit path, and it always marks.
  function setHeaderMode(next){
    // `shown` includes Off (headerModeKey); `from` is the mode underneath it, which is what the five
    // transitions below move between. Off -> the mode underneath only clears the flag, so the lines
    // come back exactly as they were; Off -> anything else clears it and then takes that transition.
    const shown = headerModeKey(false);
    if(next === shown) return;
    asOneHeaderStep(()=>{
      if(next === 'off'){ headerOff = true; render(currentSchedule); markDirty(); return; }
      headerOff = false;
      const from = headerMode === 'auto' ? 'auto' : (headerTemplates ? 'template' : 'manual');
      if(next === from){ render(currentSchedule); markDirty(); return; }
      if(next === 'auto'){
        // Discards hand edits AND formatting, exactly as "Header: Auto" always has.
        headerMode = 'auto'; headerManual = {}; headerFormat = {}; headerTemplates = false;
      } else if(next === 'template'){
        if(from === 'auto'){
          // Seed from the built-in default, so the lines keep TRACKING the data -- which is the
          // whole point of the mode. Seeding from the RESOLVED values instead (as this did before
          // Step 3) produced a header that looked identical and then silently stopped updating,
          // which is Manual wearing Template's name.
          headerManual = Object.assign({}, DEFAULT_HEADER_TEMPLATE);
        }
        // Manual -> Template keeps the literal strings as they are: text with no tokens is a valid
        // template, so nothing is lost and the user can add tokens to what is already there.
        headerMode = 'manual'; headerTemplates = true;
      } else {
        // -> Manual. From Template this is a BAKE: every line becomes the text it currently
        // resolves to, and the tokens are gone. Irreversible short of this undo step, which is why
        // the popover says so on the row before you click it.
        if(from === 'template'){
          const hd = computeHeaderDefaults(currentSchedule);
          const baked = {};
          HDR_IDS.forEach(id=>{ if(id in headerManual) baked[id] = headerLine(id, hd); });
          headerManual = baked;
        } else if(from === 'auto'){
          // Exactly as it always was: a snapshot of the resolved auto values.
          // ⚠️ Object.assign onto a fresh object, NOT the returned object itself -- computeHeaderDefaults
          // hangs a non-enumerable __ctx on what it returns, and while Object.assign would not copy
          // it, assigning the object wholesale would carry it into headerManual and therefore into
          // the undo stack. Copy the nine strings and nothing else.
          headerManual = Object.assign({}, computeHeaderDefaults(currentSchedule));
        }
        headerMode = 'manual'; headerTemplates = false;
      }
      render(currentSchedule);
      markDirty();
    });
    // Save-as is disabled in Manual (H8), so the preset block's state depends on the mode. Re-push
    // it here rather than leaving the button stale after a switch.
    pushHeaderPresets();
  }

  // The month's five transitions. The waterfall's setHeaderMode() in every respect except which
  // stores it touches -- deliberately a separate function rather than a parameterised one, because
  // the two differ in what they seed from and what they bake, and a shared body would be a chain of
  // `mv ?` conditionals through every branch.
  //
  // ⚠️ Auto -> Manual MARKS DIRTY here. The old two-state toggle did too, but only because it
  // happened to call markDirty() at the end; this makes it structural -- one exit path, and it
  // always marks and always renders. Same fix setHeaderMode() records for the waterfall.
  function setMvHeaderMode(next){
    const from = mvHeaderMode === 'auto' ? 'auto' : (mvHeaderTemplates ? 'template' : 'manual');
    if(next === from) return;
    asOneHeaderStep(()=>{
      if(next === 'auto'){
        // Discards hand edits AND formatting, exactly as "Header: Auto" always has.
        mvHeaderMode = 'auto'; mvHeaderManual = {}; mvHeaderFormat = {}; mvHeaderTemplates = false;
      } else if(next === 'template'){
        if(from === 'auto'){
          // Seed from the built-in default so the lines keep TRACKING the data -- seeding from the
          // RESOLVED values gives a header that looks identical and then silently stops updating,
          // which is Manual wearing Template's name.
          mvHeaderManual = Object.assign({}, DEFAULT_MV_TEMPLATE);
        }
        // Manual -> Template keeps the literal strings: text with no tokens is a valid template.
        mvHeaderMode = 'manual'; mvHeaderTemplates = true;
      } else {
        // -> Manual. From Template this is a BAKE: each line becomes the text it resolves to now
        // and the tokens are gone. The menu says so on the row before it is clicked.
        if(from === 'template'){
          const md = computeMvHeaderDefaults(currentSchedule);
          const baked = {};
          MV_HDR_IDS.forEach(id=>{ if(id in mvHeaderManual) baked[id] = mvHeaderLine(id, md); });
          mvHeaderManual = baked;
        } else if(from === 'auto'){
          // ⚠️ Object.assign onto a FRESH object, not the returned one: computeMvHeaderDefaults
          // hangs a non-enumerable __ctx on what it returns, and assigning it wholesale would carry
          // that into mvHeaderManual and therefore into the undo stack and the saved file.
          mvHeaderManual = Object.assign({}, computeMvHeaderDefaults(currentSchedule));
        }
        mvHeaderMode = 'manual'; mvHeaderTemplates = false;
      }
      render(currentSchedule);
      markDirty();
    });
    pushHeaderPresets();
  }

  // The mode menu. A body-level popover anchored to the button -- chrome, and explicitly fair game.
  // Built the way openPhaseColorPop() builds its picker: created on demand, appended to <body>,
  // clamped to the viewport, closed by an outside mousedown or any scroll/resize.
  // ⛔ NOT ONE id ANYWHERE IN HERE. collectFieldValues() sweeps every input[id]/select[id] into
  // every saved calendar and adds an undo step per change; these are buttons, and they carry
  // classes only. Same rule the header format toolbar follows.
  let activeHdrModePop = null;
  // The element the open menu hangs from. Since the header controls left the calendar (owner ruling
  // 1) that is the preview toolbar's #tb-hdr-mode-btn, which announces the menu with aria-expanded
  // and toggles it: a press on the anchor itself is NOT an outside press, so its click can close.
  let activeHdrModeAnchor = null;
  function closeHeaderModePop(){
    if(activeHdrModePop){ activeHdrModePop.remove(); activeHdrModePop = null; }
    if(activeHdrModeAnchor && activeHdrModeAnchor.hasAttribute('aria-haspopup')) activeHdrModeAnchor.setAttribute('aria-expanded', 'false');
    activeHdrModeAnchor = null;
    document.removeEventListener('mousedown', onHdrModePopOutside, true);
    window.removeEventListener('resize', closeHeaderModePop);
    window.removeEventListener('scroll', closeHeaderModePop, true);
  }
  function onHdrModePopOutside(e){
    if(activeHdrModeAnchor && activeHdrModeAnchor.contains(e.target)) return;   // the anchor's click decides
    if(activeHdrModePop && !activeHdrModePop.contains(e.target)) closeHeaderModePop();
  }
  const HDR_MODE_CHOICES = [
    { key:'auto',     label:'Auto',
      desc:'Every line mirrors Show Info and the schedule. Not editable.' },
    { key:'template', label:'Template',
      desc:'Lines you write, with live data in {braces}. Edit a line to see its tokens.' },
    { key:'manual',   label:'Manual',
      desc:'Plain text you type. Nothing updates itself.' },
    // Owner ruling 10 (20 Oct 2026). Waterfall only: openHeaderModePop() leaves it out of the month's menu.
    { key:'off',      label:'Off', sheetOnly: true,
      desc:'No title block. The grid starts at the top; Excel and the PDF print no header.' },
  ];
  // `mv` selects which header the menu drives. The rows, the copy and the bake warning are the
  // same in both views -- the modes mean the same thing -- so this is one menu, not two.
  function openHeaderModePop(anchorEl, mv){
    closeHeaderModePop();
    const current = headerModeKey(mv);
    const pop = document.createElement('div');
    pop.className = 'hdr-mode-pop';
    HDR_MODE_CHOICES.forEach(c=>{
      if(mv && c.sheetOnly) return;
      const row = document.createElement('button');
      row.type = 'button';
      row.className = 'hdr-mode-choice' + (c.key === current ? ' is-current' : '');
      const name = document.createElement('span');
      name.className = 'hdr-mode-name';
      name.textContent = c.label;
      const desc = document.createElement('span');
      desc.className = 'hdr-mode-desc';
      desc.textContent = c.desc;
      row.appendChild(name);
      row.appendChild(desc);
      // ⚠️ The bake warning is stated ON THE ROW, before the click, because Template -> Manual
      // throws the tokens away. The plan requires it be said first; an undo step is the only way
      // back.
      if(c.key === 'manual' && current === 'template'){
        const warn = document.createElement('span');
        warn.className = 'hdr-mode-warn';
        warn.textContent = 'Freezes today’s values and removes the tokens.';
        row.appendChild(warn);
      }
      // ⭐ The tokens are invisible while you are deciding whether Template is worth trying, which
      // is the wrong way round -- they ARE the reason to try it. Offer a look from here.
      if(c.key === 'template'){
        // ⭐ Opens the EDITOR, not a read-only peek. The editor shows the same tokens and lets you
        // use them, so a browse-only list is strictly worse now that it exists -- and this is the
        // discovery path for the whole feature: it is reachable from Auto, before you have chosen
        // anything, and opening it switches you into Template as one undo step.
        const peek = document.createElement('span');
        peek.className = 'hdr-mode-peek';
        peek.textContent = 'Open the template editor…';
        peek.addEventListener('click', ev=>{
          ev.stopPropagation();
          ev.preventDefault();
          closeHeaderModePop();
          openHeaderEditor(null, mv);
        });
        row.appendChild(peek);
      }
      if(c.key === current){
        row.disabled = true;
      } else {
        row.addEventListener('click', ev=>{
          ev.stopPropagation();
          closeHeaderModePop();
          if(mv) setMvHeaderMode(c.key); else setHeaderMode(c.key);
        });
      }
      pop.appendChild(row);
    });
    document.body.appendChild(pop);
    activeHdrModeAnchor = anchorEl;
    if(anchorEl.hasAttribute('aria-haspopup')) anchorEl.setAttribute('aria-expanded', 'true');
    const r = anchorEl.getBoundingClientRect();
    pop.style.top = (window.scrollY + r.bottom + 5) + 'px';
    pop.style.left = (window.scrollX + r.left) + 'px';
    const pr = pop.getBoundingClientRect();
    if(pr.right > window.innerWidth - 8) pop.style.left = (window.scrollX + window.innerWidth - pr.width - 8) + 'px';
    if(pr.bottom > window.innerHeight - 8) pop.style.top = (window.scrollY + r.top - pr.height - 5) + 'px';
    activeHdrModePop = pop;
    // Bound on the next tick, or the click that OPENED the popover closes it again.
    setTimeout(()=>{
      document.addEventListener('mousedown', onHdrModePopOutside, true);
      window.addEventListener('resize', closeHeaderModePop);
      window.addEventListener('scroll', closeHeaderModePop, true);
    }, 0);
  }

  // ---------- The header controls, off the calendar (owner rulings 1, 4, 5; relayed 30 Sep 2026) --------
  // The frozen renderers still emit #hdr-mode-btn, #notes-reset-btn and #mv-hdr-mode-btn inside
  // #table-wrap. They are HIDDEN by CSS, never deleted (the owner's build-time approval: no frozen
  // function is edited). What the user clicks is chrome now:
  //   * #tb-hdr-mode-btn in the preview toolbar (PreviewToolbar.jsx): the same mode menu, anchored
  //     under itself, for whichever view is showing;
  //   * #tb-notes-reset-btn in the app header, where Reset All was (Header.jsx). That was the owner's
  //     measured fallback: the two buttons together wrapped the toolbar below 1414 px. It reads "Reset
  //     Notes" in the Waterfall and "Reset Month Notes" in the Month view;
  //   * #hiatus-reset-btn at the foot of the sidebar's All-phase hiatus card (ruling 5).
  // All three are React-rendered, so they are reached by DELEGATION from document, never captured at
  // evaluation time (HANDOFF §2b-3's law).
  function headerModeKey(mv){
    if(!mv && headerOff) return 'off';
    const auto = mv ? mvHeaderMode === 'auto' : headerMode === 'auto';
    return auto ? 'auto' : ((mv ? mvHeaderTemplates : headerTemplates) ? 'template' : 'manual');
  }
  // What the two view-following buttons are told. Pushed from a childList observer on #table-wrap,
  // not from each call site: EVERY way the view or a header mode changes ends in render() rebuilding
  // #table-wrap -- a mode choice, a view switch, a Load, an undo -- and an observer cannot miss one
  // the way a list of pushes can. Observing the frozen surface edits nothing (sanctioned pattern 3).
  function pushViewControls(){
    const mv = viewMode === 'month';
    chrome.headerModeBtn({ view: mv ? 'month' : 'sheet', mode: headerModeKey(mv) });
    chrome.notesResetBtn({ view: mv ? 'month' : 'sheet' });
  }
  new MutationObserver(pushViewControls).observe(document.getElementById('table-wrap'), { childList: true });
  pushViewControls();
  // Header: Off on screen and in the print fallback (HEADER-ROW-PLAN §2). The frozen renderer still
  // emits .cal-header-bar, with every line empty; a <body> class hides it (legacy.css), because the
  // print fallback renders into #print-root, which is <body>'s child and not inside #table-wrap.
  // Run off the same re-render observer as the buttons above: every way headerOff changes -- the
  // menu, an undo, a Load, New -- ends in render() rebuilding #table-wrap (sanctioned pattern 3).
  function reflectHeaderOff(){ document.body.classList.toggle('wf-hdr-off', headerOff); }
  new MutationObserver(reflectHeaderOff).observe(document.getElementById('table-wrap'), { childList: true });
  reflectHeaderOff();
  document.addEventListener('click', e=>{
    const b = e.target.closest && e.target.closest('#tb-hdr-mode-btn');
    if(!b) return;
    if(activeHdrModePop && activeHdrModeAnchor === b){ closeHeaderModePop(); return; }   // a second click closes
    openHeaderModePop(b, viewMode === 'month');
  });

  // Ruling 4: the notes reset SPLITS BY VIEW, and both keep the old branch's shape -- render(), since
  // notes are not schedule inputs, then markDirty(), which makes it one undo step and marks the file
  // unsaved. Neither touches hiatus bands (ruling 5 gave them their own reset) or holidayView ("Reset
  // holidays" already clears it). An editor that is open is discarded: a reset is not an edit.
  //   Waterfall: the waterfall notes -- text overrides and cleared-note tombstones (so suppressed
  //   milestones come back), their colours and sizes. The Month view shows the same notes, so they
  //   reset there too.
  //   Month: the month's OWN notes only -- day notes, their legacy colours, the extra lanes.
  function resetWaterfallNotes(){
    if(activeNoteEditor){ closeNoteEditorPop(); activeNoteEditor = null; }
    Object.keys(userNotes).forEach(k=>delete userNotes[k]);
    noteColors = {}; noteFontSize = {};
    textStyle.note = {};     // their text styles too, as their colours and sizes (TEXT-STYLE-BAR-PLAN.md §2)
    render(currentSchedule);
    markDirty();
  }
  function resetMonthNotes(){
    if(activeMvNote) closeMvNoteEditor();
    Object.keys(dayNotes).forEach(k=>delete dayNotes[k]);
    dayNoteColors = {}; mvExtraLanes = {};
    mvWfNotePlace = {};   // where the waterfall's lines sat in the month view is month-view state too (MONTH-ORDER-PLAN.md)
    render(currentSchedule);
    markDirty();
  }
  // Ruling 5: the hiatus bands' own reset -- every band's label, colour and size, all-phase and
  // per-phase. update(), NOT render(), and that is a fix: the old combined reset only rendered, so a
  // NAMED hiatus row's band read the default "Hiatus" until some later edit happened to run
  // syncHiatusNamesFromSidebar() and re-claim it (reproduced on v1.4.1: both weeks of a "Winter
  // Break" row read "Hiatus"). update() runs that sync first. It also ends in markDirty().
  function resetHiatusBands(){
    hiatusTexts = {}; hiatusNameSyncedKeys = {}; hiatusColors = {}; hiatusFontSize = {};
    textStyle.hiatus = {};
    update();
  }
  document.addEventListener('click', e=>{
    const t = e.target.closest && e.target.closest('#tb-notes-reset-btn, #hiatus-reset-btn');
    if(!t) return;
    if(t.id === 'hiatus-reset-btn') resetHiatusBands();
    else if(viewMode === 'month') resetMonthNotes();
    else resetWaterfallNotes();
  });

  // "5 Shooting Blocks" / "1 Shooting Block" -- r1's Blocks-mode half (ruling 6). '' without a count.
  function shootingBlocksPhrase(n){
    return (Number.isFinite(n) && n > 0) ? `${n} Shooting Block${n === 1 ? '' : 's'}` : '';
  }

  // Compute the auto defaults for every header line from the current form inputs + schedule.
  function computeHeaderDefaults(schedule){
    const today = new Date();
    const todayStr = `${today.getMonth()+1}.${today.getDate()}.${String(today.getFullYear()).slice(2)}`;
    const showTitle = (document.getElementById('show-title').value || '').trim();
    // Carry the season as a short suffix, e.g. "Show Name S2" -- same convention as the month
    // view header, so the two documents identify the season identically.
    const seasonSel = document.getElementById('season-num');
    const seasonNum = seasonSel ? (seasonSel.value || '').trim() : '';
    const titleLine = showTitle + (seasonNum ? (showTitle ? ' ' : '') + 'S' + seasonNum : '');
    const wrStartRaw = document.getElementById('start-writersRoom') ? document.getElementById('start-writersRoom').value : '';
    let wrLine = '';
    if(wrStartRaw){
      const parsed = parseDateUTC(wrStartRaw);
      if(parsed){ const mon = mondayOf(parsed); wrLine = `Writer's Room Opens: ${mon.getUTCMonth()+1}.${mon.getUTCDate()}.${String(mon.getUTCFullYear()).slice(2)}`; }
    }
    let r1='', r2='', r3='';
    // dayCountVal, not parseInt: a 4.5-day episode prints "4.5-Day Shooting Schedule" (half days,
    // owner 15 Oct 2026). A whole number prints exactly as before.
    const shootDaysPerEp = dayCountVal((document.getElementById('shoot-days-per-ep').value||'').trim());
    if(schedule && schedule.productionInfo){
      const prodInfo = schedule.productionInfo;
      let prodWeeks = 0;
      for(const w of schedule.weeks){
        // ⛔ PRODUCTION'S KEY, NEVER A LABEL (audit L-11, v1.4.1). This used to be
        // `c.key==='production' || c.label.startsWith('Production')`, a clause that goes back to the
        // first version of the file, and a label is whatever the user typed: a custom phase named
        // "Production 2nd Unit" (cells "Production 2nd Unit wk N") or a built-in phase RENAMED
        // "Production Prep" added its own weeks to the shoot's span -- a 4-week shoot read "7-Week
        // Production Span" in the header, in Excel and in the waterfall PDF. The key is the only thing
        // that means Production. Nothing this clause was meant to catch is lost: Production's own
        // per-phase hiatus band is pushed with key 'production' (so a paused week stays in the span,
        // as before), and a renamed Production keeps its key. ⛔ {production.summary} in
        // buildHeaderCtx() counts the same way -- change both or neither (the hdrtemplate leg).
        if(w.cells.some(c=>c.key==='production')) prodWeeks++;
      }
      const fmt = d => `${d.getUTCMonth()+1}.${d.getUTCDate()}.${String(d.getUTCFullYear()).slice(2)}`;
      // ✅ RULING 6 (owner, 22 Sep 2026): in Blocks mode the per-episode half reads
      // "5 Shooting Blocks". The block COUNT, not a day figure, because per-block overrides mean
      // blocks can differ in length and "20-Day Blocks" would then be false. Episodes mode is the
      // pre-Blocks string, byte for byte. ⛔ The {production.summary} token restates this line and
      // the hdrtemplate leg requires the two to agree -- change both or neither.
      const parts = [
        prodWeeks ? `${prodWeeks}-Week Production Span` : '',
        isBlocksMode()
          ? shootingBlocksPhrase(parseInt((document.getElementById('num-blocks').value||'').trim(), 10))
          : (!isNaN(shootDaysPerEp) && shootDaysPerEp > 0 ? `${shootDaysPerEp}-Day Shooting Schedule` : ''),
      ].filter(Boolean);
      r1 = parts.join(' / ');
      // Both ends of this line are REAL SHOOT DAYS. It used to print the entered Monday against a
      // computed last shoot day, so one end was a calendar guess and the other was measured -- and
      // when the Monday was a holiday or inside a hiatus the line contradicted the grid beside it.
      r2 = `Principal Photography ${fmt(prodInfo.firstShootDay || prodInfo.startDate)} / Wrap: ${fmt(prodInfo.lastShootDay)}`;
    }
    const numEpisodes = parseInt((document.getElementById('num-episodes').value||'').trim(), 10);
    if(!isNaN(numEpisodes) && numEpisodes > 0) r3 = `${numEpisodes} Episodes`;
    // l2 and c4 are the two slots added 31 Aug 2026. c4 still has no auto value. l2 now carries the
    // VERSION NUMBER, which is what the bottom-left slot is FOR as far as a user is concerned
    // (owner, 1 Sep 2026: "I also want this version number thing to be part of the default header
    // and be in the very bottom left side text box of the header"). It stays EMPTY -- and so stays
    // invisible on screen, absent from the workbook's &L section and undrawn in the PDF -- until
    // someone types a version into Show Info. See versionLabel() for why empty must mean empty.
    const out = { left: todayStr, l2: versionLabel(), l3: '', c1: titleLine, c2: 'Planning Calendar', c3: wrLine, c4: '', r1, r2, r3 };
    // The token context rides on the return value, because headerLine(id, defaults)'s SIGNATURE
    // cannot change -- three of its call sites are inside frozen functions (§9). Built once here,
    // so a nine-line header costs one ctx rather than nine.
    //
    // ⚠️ NON-ENUMERABLE, and that is the whole trick rather than fastidiousness. This object is
    // assigned DIRECTLY to headerManual in two places -- the popover's Auto -> Manual snapshot, and
    // the legacy headerOverrides restore path -- and headerManual goes into captureSnapshot(). An
    // ordinary property would be serialised into every saved calendar and every undo frame, as a
    // junk key in a format that is a permanent contract. Object.assign, {...spread} and
    // JSON.stringify all skip non-enumerable properties; `defaults.__ctx` still reads normally.
    Object.defineProperty(out, '__ctx', { value: buildHeaderCtx(schedule), enumerable: false });
    return out;
  }
  // Effective text for a header line: the manual value in manual mode, else the auto default.
  //
  // ⛔ THIS IS THE CHOKE POINT THE WHOLE FEATURE HANGS OFF. All three consumers call it -- the
  // screen inside frozen renderSpreadsheetView, exportExcel, buildWaterfallPdf -- so resolving here
  // is what makes it impossible for them to disagree, and what keeps every frozen function
  // untouched. ⛔ Do not change the signature: three of those call sites are frozen (§9).
  //
  // Two things are deliberate about WHAT gets resolved:
  //   * only when headerTemplates is true. With the flag false this function is byte-for-byte what
  //     it always was, which is what makes every already-saved Manual header safe.
  //   * only the headerManual branch. The `defaults[id]` fallback is computeHeaderDefaults()'s
  //     hand-coded output -- already final text, never a template -- so resolving it would be
  //     asking the resolver to re-read a value, which is exactly what the one-pass rule forbids.
  function headerLine(id, defaults){
    // Header: Off prints nothing, and every consumer drops a line whose text is empty (HEADER-ROW-PLAN
    // §2). ⚠️ setHeaderMode() clears the flag BEFORE it bakes a Template into Manual, or the bake would
    // read these empty strings and wipe the lines.
    if(headerOff) return '';
    if(headerMode === 'manual'){
      if(id in headerManual){
        const raw = headerManual[id];
        return headerTemplates ? resolveHeaderTemplate(raw, defaults && defaults.__ctx) : raw;
      }
      return defaults[id] || '';
    }
    return defaults[id] || '';
  }
  // Rebuild the render-facing rowHeights from the by-week truth. ⚠️ Called from update() only,
  // which is correct and not laziness: the index<->week mapping can only change when the SCHEDULE
  // changes, and computeSchedule runs nowhere else. The ~30 bare render() calls elsewhere repaint
  // the same week list and need no resync.
  function syncRowHeights(schedule){
    const weeks = (schedule && schedule.weeks) || [];
    // ⭐ MIGRATION, forward-only, for every file saved before 10 Sep 2026: those carry index-keyed
    // rowHeights and no by-week store. Detected by state rather than a flag -- an un-migrated file
    // is the only way to have index keys and an empty by-week map, and once converted the map is
    // non-empty so this cannot run twice. A calendar with no dragged rows has both empty and needs
    // nothing.
    if(!Object.keys(rowHeightsByWeek).length && Object.keys(rowHeights).length && weeks.length){
      Object.keys(rowHeights).forEach(k=>{
        const i = +k;
        if(Number.isInteger(i) && weeks[i]) rowHeightsByWeek[isoOf(weeks[i].date)] = rowHeights[k];
      });
    }
    const next = {};
    weeks.forEach((w, i)=>{
      // ⛔ A NUMBER or nothing: the frozen renderer writes this straight into
      // `<tr style="height:${rh}px">`, so a string from a file could break out of the attribute
      // (audit H-1). The drag writes numbers, and sanitizeSnapshot already holds restored values to
      // that; this is the belt to its braces, at the last non-frozen step before the markup.
      const h = finiteNum(rowHeightsByWeek[isoOf(w.date)]);
      if(h !== null && h > 0) next[i] = h;
    });
    rowHeights = next;
  }

  function update(){
    // Belt and braces around render()'s own snapshot: markDirty() below touches the DOM after the
    // grid is rebuilt, and update() is what the handlers that add or
    // remove sidebar rows call once they have already changed the page height.
    const scrollSnap = captureScroll();
    const state = readState();
    syncHiatusNamesFromSidebar();
    // A tool is moving the shoot: put every day override on its shoot day for the dates as they
    // stand NOW, before anything is scheduled from them (see beginShootDayMove).
    if(overrideMove){ const r = overridesForMove(overrideMove); if(r) dayOverrides = r.map; }
    currentSchedule = computeSchedule(state);
    // ⛔ The gate runs HERE, once per update() -- never inside computeSchedule, which
    // productionStartEndingBy calls up to 300 times in a backward search and would pay 300 gates.
    // update() is bound undebounced to the `input` event of every phase date/weeks field, so this is
    // also cached on a cheap structural key: a fingerprint pass is one computeBlockLayout PLUS one
    // sheetColumnWidths, and the latter measures every label and note of every week.
    const gated = maybeRunColSwapGate(state, currentSchedule);
    if(gated && gated.schedule) currentSchedule = gated.schedule;
    // ⭐ THE CALENDAR RANGE CUTS THE WATERFALL, EXCEL AND THE WATERFALL PDF, NEVER THE MONTH VIEW (owner
    // ruling 3, 20 Oct 2026). computeSchedule hands back the waterfall's rows, so in the month view this
    // puts the whole calendar back. Picked here, per view, because frozen render() hands its schedule to
    // frozen renderMonthView, and frozen exportMonthPdf reads currentSchedule itself. Each export runs only
    // from its own view (Excel and the waterfall PDF from the waterfall, the month PDF from the month view),
    // so each reads the right one, and setViewMode() runs update(), so a switch re-picks. Without a range
    // there is nothing to put back and this is the schedule itself.
    reflectCalRangeNotice(currentSchedule);
    if(viewMode === 'month') currentSchedule = wholeCalendar(currentSchedule);
    // ⛔ L-17 (owner ruling, 29 Sep 2026): a DIFFERENT calendar opens where it always did.
    // renderMonthView (frozen) now clamps an out-of-range month cursor to the NEAREST month, which is
    // right for a range that shrinks while you edit. But Load, backup recovery and New/Reset REPLACE
    // the calendar, and those must still open on the new calendar's FIRST month when the month on
    // screen is outside it, and keep the month on screen when it is inside it -- both exactly as
    // before. They arm this flag; forgetting the cursor HERE, against the very schedule about to be
    // rendered, sends renderMonthView down its unchanged !monthCursor branch. It stays armed until a
    // schedule HAS a month range: New leaves no dates, and today the first month is decided only once
    // some are typed.
    // ⚠️ Since 20 Oct 2026 (one month each side, MONTH-NOTES-PLAN.md §3) "inside it" means the CORE months, the
    // ones the phases cover, so a loaded calendar never opens on its empty edge month.
    if(monthCursorRecheck){
      const mr = monthCoreRange(currentSchedule);
      if(mr){
        monthCursorRecheck = false;
        if(monthCursor && (monthCursor < mr.first || monthCursor > mr.last)) monthCursor = null;
      }
    }
    // ⭐ THE CURSOR NEVER LANDS ON AN EMPTY EDGE BY ITSELF (MONTH-NOTES-PLAN.md §3). The screen's range now runs
    // one month past the phases each side, and frozen renderMonthView sends a cursor with no month, or one
    // outside that range, to the range's end: the edge. So the cursor is placed HERE first, against the
    // schedule about to be rendered: an absent one, or one off either end, goes to the nearest month the phases
    // cover, which is exactly where renderMonthView used to put it. A cursor the user paged to an edge is inside
    // the range and is left alone.
    {
      const core = monthCoreRange(currentSchedule);
      if(core){
        const first = monthStep(core.first, -1), last = monthStep(core.last, 1);
        if(!monthCursor || monthCursor < first) monthCursor = new Date(core.first.getTime());
        else if(monthCursor > last) monthCursor = new Date(core.last.getTime());
      }
    }
    // ⛔ BEFORE render(), which reads rowHeights by index. The week list may just have changed.
    syncRowHeights(currentSchedule);
    render(currentSchedule);
    // AFTER render(), which owns meta-<key> and is frozen. See refreshOverrideNote().
    refreshOverrideNote();
    reflectColMoveNotes();
    refreshCustomUnitMeta(currentSchedule);
    refreshPrepUI(currentSchedule);
    refreshHolidayCoverageNote();
    // The "Label Production by" control (Preferences, month view). Here because a change of Schedule by,
    // an undo or a Load can change what it shows without touching mvProdLabel's own setter.
    reflectMvProdLabel();
    // The Automatic notes card (ruling 9): here for the same reason -- an undo, a Load or New changes
    // autoNotesOff without touching the boxes.
    reflectAutoNoteKinds();
    // Chrome OUTPUT: the date-picker popovers (src/chrome/DatePop.jsx) mark enabled holidays and
    // all-phase hiatus weeks in their calendars -- mark, never exclude. Pushed here like every
    // other chrome surface, so the popover never reaches into the engine.
    chrome.dateContext({
      holidays: fullHolidayList(state.unionCountry)
        .filter(h => h.enabled !== false)
        .map(h => ({ iso: h.date, name: h.name })),
      hiatuses: (state.hiatuses || []).map(h => ({ start: h.start, weeks: h.weeks }))
    });
    reflectStartDateValidity(state, refreshSpanHint(state).concat(calRangeEmptyFields(currentSchedule)));
    markDirty();
    restoreScroll(scrollSnap);
  }

  // The schedule the MONTH view reads: the whole week list under a calendar range (computeSchedule's
  // fullRange), the schedule itself without one. Also what anything about the calendar rather than the
  // waterfall's rows reads (weekAutoTexts), so it answers the same in either view.
  function wholeCalendar(sch){
    return (sch && sch.fullRange) ? Object.assign({}, sch, sch.fullRange) : sch;
  }
  // A range that leaves the waterfall no row rings both of its dates; render() says why.
  function calRangeEmptyFields(sch){
    if(!(sch && sch.calRangeCut && sch.error === 'invalid-range')) return [];
    return ['cal-range-start', 'cal-range-end'].map(id => document.getElementById(id)).filter(el => el && el.value);
  }
  // The strip naming the phases a calendar range cuts (owner, 20 Oct 2026, by picker: "Strip above the
  // grid", "Names and weeks"). Waterfall view only, since the month view cuts nothing. Dismissed per
  // MESSAGE, as the column-order strip is, so a different cut later still speaks up.
  const calRangeNoticeState = { text: '', dismissed: '' };
  function reflectCalRangeNotice(sch){
    const el = document.getElementById('calrange-notice');
    if(!el) return;
    const lost = (sch && sch.calRangeCut) || {};
    const parts = [];
    let total = 0;
    getAllPhaseDefs().forEach(p=>{
      const n = lost[p.key];
      if(!n) return;
      total += n;
      parts.push(n + (n === 1 ? ' week of ' : ' weeks of ') + phaseDisplayName(p.key));
    });
    const list = parts.length > 1 ? parts.slice(0, -1).join(', ') + ' and ' + parts[parts.length - 1] : (parts[0] || '');
    const msg = list ? 'The calendar range cuts ' + list + ' from the waterfall, Excel and PDF. The month view still shows '
                     + (total === 1 ? 'it.' : 'them.') : '';
    calRangeNoticeState.text = msg;
    const txt = el.querySelector('.ln-text');
    if(txt && txt.textContent !== msg) txt.textContent = msg;
    el.hidden = !msg || viewMode === 'month' || calRangeNoticeState.dismissed === msg;
  }
  document.addEventListener('click', e=>{
    if(!(e.target.closest && e.target.closest('#calrange-notice .ln-x'))) return;
    calRangeNoticeState.dismissed = calRangeNoticeState.text;
    const el = document.getElementById('calrange-notice');
    if(el) el.hidden = true;
  });

  // The diegetic invalid-date signal (owner request №4). Until now a bad start date said so ONLY
  // in the phase's meta readout ("Check that year — doesn't look right"), which sits below the
  // field and reads as commentary; the field itself looked fine. This rings the field.
  //
  // ⛔ Note where it does NOT live. The obvious home is render()'s meta branch, which already
  // computes the verdict -- but that is frozen. So the ring is applied from update() (not frozen)
  // to a SIDEBAR field (chrome), and it CALLS the frozen readCfgForMeta() for the verdict rather
  // than re-deriving it. Reading from the frozen surface is explicitly allowed; this way there is
  // no second copy of the validity rule to drift out of step with the meta line.
  //
  // ⛔ AUDIT L-10: the HIATUS date fields too. readState() also refuses the calendar for a bad year
  // in an all-phase hiatus or an ENABLED per-phase hiatus, and those were never ringed, so the
  // calendar blanked with "check the fields above" and no field was marked. They are ringed from
  // state.badYearFields, which readState() fills with the very tests that set hasInvalidYear --
  // so a per-phase hiatus whose toggle is off (not counted) is not ringed either. Every hiatus
  // field is visited, so a ring clears the moment its field stops being counted.
  //
  // `extraBad` (audit N-2): the one field refreshSpanHint() found to explain a too-long refusal --
  // a weeks field, a hiatus's weeks, or a phase's start. The weeks fields are in the sweep below
  // for that reason, so their ring clears on the next update() like every other.
  //
  // ⛔ AUDIT L-12, and FIX-PLAN's defaults table: "Keep whole-number semantics. Ring the field and
  // say 'whole weeks/days only'. The schedule does not change." Every duration is read with
  // parseInt, so 2.5 weeks is 2, "1e3" is 1 and a 7.5-day episode is 7 -- silently. The rule is
  // exactly that: a field is flagged when what was typed is a number that parseInt reads
  // DIFFERENTLY ("2.0" is 2 both ways, so it is fine). Nothing here changes a value or a date.
  // The Show Info COUNTS (episodes, blocks) are Mantine NumberInputs with allowDecimal={false}; a
  // decimal cannot be typed there, so they are not in the list. The two Show Info DAY fields are,
  // since half days (below). The words go in a data attribute on the field's
  // own label, or on its row where the field sits in a row (the episode and block day boxes, and
  // Sim Post's offset line), and legacy.css prints them as the host's ::after.
  //
  // ✅ HALF DAYS (owner, 15 Oct 2026): the EPISODE and BLOCK day counts now read in halves
  // (dayCountVal), so for those -- the row boxes and the two Show Info defaults, which allow one
  // decimal now -- the rule is the same rule against a different reader: flagged when dayCountVal
  // reads the number differently, i.e. anything that is not a whole or half (4.3). The words say
  // "Whole or half days only". Weeks fields are unchanged.
  function isWholeNumberTypo(el){
    const v = String((el && el.value) || '').trim();
    if(v === '') return false;
    // Production's day count is a hidden field the ENGINE writes (Σ episodes or blocks), never typed,
    // and since half days it can hold 45.5. Nothing to flag there.
    if(el.id === 'weeks-production') return false;
    const n = Number(v);
    if(el.matches && el.matches(HALF_FIELDS)) return Number.isFinite(n) && n > 0 && n !== dayCountVal(v);
    return Number.isFinite(n) && n !== parseInt(v, 10);
  }
  const HALF_FIELDS = '#episode-rows .ep-days, #episode-rows .blk-days, #shoot-days-per-ep, #days-per-block';
  // The prep lengths (EPISODE-PREP-PLAN.md) count WORKING days, whole ones, like a Days phase.
  const PREP_FIELDS = '.form-panel .prep-days-in';
  const WHOLE_FIELDS = '.form-panel input[id^="weeks-"], #hiatus-list .hiatus-weeks, .phiatus-weeks, #simpost-offset, '
                     + HALF_FIELDS + ', .form-panel .phase-days, ' + PREP_FIELDS;
  function reflectStartDateValidity(state, extraBad){
    // unitBadFields: a Dates phase's end before its start (CUSTOM-PHASE-UNITS-PLAN.md) -- one phase
    // left out, never the whole calendar refused, so it is not a badYearField.
    const bad = new Set([...((state && state.badYearFields) || []), ...((state && state.unitBadFields) || []), ...(extraBad || [])]);
    const hosts = new Map();   // message host -> its words
    document.querySelectorAll(WHOLE_FIELDS).forEach(el=>{
      if(!isWholeNumberTypo(el)) return;
      bad.add(el);
      // The two Show Info defaults are Mantine NumberInputs, whose input sits in the wrapper rather
      // than inside its <label>, so the wrapper hosts the words (printed under the field).
      const host = el.closest('.episode-row') || el.closest('.block-head') || el.closest('.prep-unit-row')
                || el.closest('label') || el.closest('.mantine-InputWrapper-root');
      // Both rules, kept side by side (merged 15 Oct 2026): an episode's or block's count may end in .5
      // (HALF_FIELDS, the half-days ruling), while a custom phase's Days box counts WORKING days,
      // which are whole (CUSTOM-PHASE-UNITS-PLAN.md) -- isWholeNumberTypo() applies the whole rule to
      // it because it is not in HALF_FIELDS.
      if(host) hosts.set(host, el.matches(HALF_FIELDS) ? 'Whole or half days only'
                             : (el.classList.contains('phase-days') || el.classList.contains('prep-days-in')) ? 'Whole days only'
                             : 'Whole weeks only');
    });
    document.querySelectorAll('.form-panel [data-whole-err]').forEach(h=>{ if(!hosts.has(h)) h.removeAttribute('data-whole-err'); });
    hosts.forEach((words, h)=>{ if(h.getAttribute('data-whole-err') !== words) h.setAttribute('data-whole-err', words); });
    document.querySelectorAll('#hiatus-list .hiatus-start, .phiatus-start, #hiatus-list .hiatus-weeks, .phiatus-weeks, .form-panel input[id^="weeks-"], #simpost-offset, ' + HALF_FIELDS + ', .form-panel .phase-days, .form-panel .phase-end, ' + PREP_FIELDS + ', #cal-range-start, #cal-range-end').forEach(el=>{
      el.classList.toggle('is-invalid', bad.has(el));
    });
    getAllPhaseDefs().forEach(p=>{
      const el = document.getElementById('start-'+p.key);
      if(!el) return;
      let bad = false;
      // Defensive: a row mid-rebuild can be missing its weeks field, and a thrown error here
      // would take the rest of update() with it.
      try { bad = readCfgForMeta(p.key) === 'invalid'; } catch(err){ bad = false; }
      el.classList.toggle('is-invalid', bad || (extraBad || []).includes(el));
    });
  }

  // ⛔ AUDIT N-2 -- owner ruling, 30 Sep 2026: "name the cause, above the preview". When the calendar
  // is refused as too long, frozen render() says "that's almost certainly a typo in one of the
  // years". Measured on the reference calendar, that was wrong in 4 of 5 cases: Post's weeks, the
  // shooting days per episode, a hiatus's weeks and a smaller weeks overrun were all blamed on a
  // year. That sentence cannot be edited -- render() is frozen and its .empty-state is inside
  // #table-wrap -- so #span-hint, a chrome line ABOVE the preview (at the top of the panel, visible on
  // every sidebar tab), names the one field that explains the refusal, and that field is ringed.
  //
  // Sanctioned pattern 2: the verdict comes from computeSchedule itself, never from a second copy
  // of its span arithmetic. Each candidate is re-checked with that ONE field neutralised (a length
  // set to 1, or a phase left out); it is the cause when the calendar then fits. computeSchedule
  // writes no module state (checked 30 Sep 2026) and the shift solvers already call it up to 300
  // times a solve. It runs only while the calendar is refused, so a normal update() pays nothing,
  // and Production's day loop is bounded (5,000 days) inside simulateProductionSchedule.
  function phaseDisplayName(key){
    const el = document.getElementById('name-'+key);
    const typed = el ? (el.value || '').trim() : '';
    return typed || (PHASES.find(x=>x.key===key)||{}).label || 'A phase';
  }
  function spanCulprit(state){
    const fits = st => { try { const r = computeSchedule(st); return !r.error && r.weeks.length > 0; } catch(e){ return false; } };
    const num = v => Number(v).toLocaleString('en-US');
    const withPhase = (key, cfg) => Object.assign({}, state, {phases: Object.assign({}, state.phases, {[key]: cfg})});
    // A calendar range typed far from the work (owner ruling 3) stretches the week loop as a typo'd year
    // does, so it is asked first: the cause when the calendar fits without it.
    if(state.calRange && fits(Object.assign({}, state, {calRange: null}))){
      const end = !!state.calRange.end && fits(Object.assign({}, state, {calRange: Object.assign({}, state.calRange, {end: ''})}));
      return {text: 'The calendar range\u2019s ' + (end ? 'end' : 'start') + ' date makes the calendar too long. Check that year.',
              el: document.getElementById(end ? 'cal-range-end' : 'cal-range-start')};
    }
    const found = [];
    (state.allDefs || []).forEach(p=>{
      const cfg = state.phases[p.key];
      if(cfg && cfg.weeks > 1 && fits(withPhase(p.key, Object.assign({}, cfg, {weeks:1, rawValue:1}))))
        found.push({size:cfg.weeks, kind: p.inputMode === 'days' ? 'days' : 'weeks', key:p.key, value:cfg.rawValue});
    });
    (state.hiatuses || []).forEach((h, i)=>{
      if(!(h.weeks > 1)) return;
      const hs = state.hiatuses.map((x, j)=> j === i ? Object.assign({}, x, {weeks:1}) : x);
      if(fits(Object.assign({}, state, {hiatuses: hs}))) found.push({size:h.weeks, kind:'hiatus', index:i, value:h.weeks, start:h.start});
    });
    Object.keys(state.phaseHiatuses || {}).forEach(key=>{
      const ph = state.phaseHiatuses[key];
      if(!(ph.weeks > 1)) return;
      const phs = Object.assign({}, state.phaseHiatuses, {[key]: Object.assign({}, ph, {weeks:1})});
      if(fits(Object.assign({}, state, {phaseHiatuses: phs}))) found.push({size:ph.weeks, kind:'phiatus', key, value:ph.weeks});
    });
    const tail = ' make the calendar too long. Check that number.';
    if(found.length){
      // More than one can fit on its own only when each is big; the biggest is the likelier typo.
      const c = found.sort((a, b)=> b.size - a.size)[0];
      const lead = 'It isn\u2019t a year: ';
      if(c.kind === 'weeks') return {text: lead + phaseDisplayName(c.key) + '\u2019s ' + num(c.value) + ' weeks' + tail,
                                     el: document.getElementById('weeks-'+c.key)};
      // Production's total is never typed (it is the episode or block list's sum), so there is no
      // field of its own to ring: the hint says where the number comes from instead.
      if(c.kind === 'days') return {text: lead + phaseDisplayName(c.key) + '\u2019s ' + num(c.value) + ' shooting days ('
                                     + (isBlocksMode() ? 'the blocks' : 'Show Info') + ')' + tail, el: null};
      if(c.kind === 'hiatus'){
        const row = (state.hiatusRows || [])[c.index];
        const d = parseDateUTC(c.start);
        return {text: lead + 'the ' + (d ? fmtShort(d) + ' ' : '') + 'hiatus\u2019s ' + num(c.value) + ' weeks' + tail,
                el: row ? row.querySelector('.hiatus-weeks') : null};
      }
      return {text: lead + phaseDisplayName(c.key) + '\u2019s own hiatus, ' + num(c.value) + ' weeks, makes the calendar too long. Check that number.',
              el: document.getElementById('phiatus-weeks-'+c.key)};
    }
    // No single length explains it. Then it IS a year -- which phase's? The one whose leaving-out
    // makes the calendar fit, compared with the calendar's first other phase.
    const starters = (state.allDefs || []).filter(p=> state.phases[p.key] && fits(withPhase(p.key, null)));
    if(starters.length === 1){
      const key = starters[0].key, cfg = state.phases[key], t = parseDateUTC(cfg.start);
      const others = state.allDefs.filter(p=> p.key !== key && state.phases[p.key])
        .map(p=> ({key:p.key, t:parseDateUTC(state.phases[p.key].start)})).filter(o=> o.t).sort((a, b)=> a.t - b.t);
      if(t && others.length){
        // The difference in YEAR NUMBERS, not elapsed time: someone who typed 2062 for 2026 thinks
        // "36 years off", while 2026-01-05 to 2062-11-02 is 36.8 years and would round to 37.
        const ref = others[0], yrs = Math.abs(t.getUTCFullYear() - ref.t.getUTCFullYear());
        return {text: phaseDisplayName(key) + ' starts in ' + t.getUTCFullYear() + ', ' + yrs + ' year' + (yrs === 1 ? '' : 's') + ' '
                      + (t > ref.t ? 'after' : 'before') + ' ' + phaseDisplayName(ref.key) + ' \u2014 check that year.',
                el: document.getElementById('start-'+key)};
      }
    }
    return {text: 'It may not be a year: the weeks and shooting days can make the calendar too long as well. Check them too.', el: null};
  }
  // Returns the fields to ring, for reflectStartDateValidity(). Hidden, and empty, unless refused.
  function refreshSpanHint(state){
    const host = document.getElementById('span-hint');
    let c = null;
    if(currentSchedule && currentSchedule.error === 'too-large'){
      try { c = spanCulprit(state); } catch(e){ console.error(e); c = null; }   // never take update() down
    }
    const text = c ? c.text : '';
    if(host){
      if(host.textContent !== text) host.textContent = text;
      host.hidden = !text;
    }
    return (c && c.el) ? [c.el] : [];
  }

