    Object.keys(dayNotes).forEach(k=>delete dayNotes[k]);
    mvExtraLanes = {};
    dayNoteColors = {};
    // ⚠️ RESET ALL clears these; "Reset Notes & Hiatus" deliberately DOES NOT. An override is
